-- First guarded publication of the 36 Perfect Video lessons in modules 13–14.
-- Existing modules, access grants, progress and attempts stay unchanged.
SET lock_timeout = '5s';

CREATE OR REPLACE FUNCTION academy_private.lesson_validation(p_version uuid)
RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path TO ''
AS $function$
DECLARE
  v public.academy_lesson_versions;
  errors jsonb := '[]'::jsonb;
  warnings jsonb := '[]'::jsonb;
  n integer;
  kinds text[];
BEGIN
  SELECT * INTO v FROM public.academy_lesson_versions WHERE id=p_version;
  IF NOT FOUND THEN RAISE EXCEPTION 'Version not found'; END IF;

  SELECT count(*),coalesce(array_agg(DISTINCT block_type),'{}')
    INTO n,kinds
  FROM public.academy_lesson_blocks WHERE version_id=p_version;

  IF btrim(v.objective)='' THEN errors:=errors||jsonb_build_array('missing_objective'); END IF;
  IF btrim(v.hook)='' THEN errors:=errors||jsonb_build_array('missing_hook'); END IF;
  IF n<5 THEN errors:=errors||jsonb_build_array('too_few_blocks'); END IF;
  IF NOT (kinds && ARRAY[
    'sequence_sort','matching','image_hotspot','decision_tree','scenario',
    'client_simulation','calculator','prompt_builder','practical_response',
    'reflection','checklist','quiz','homework','submission','flip_cards'
  ]) THEN errors:=errors||jsonb_build_array('missing_interaction'); END IF;
  IF NOT ('quiz'=ANY(kinds)) THEN errors:=errors||jsonb_build_array('missing_knowledge_check'); END IF;
  IF NOT (
    kinds && ARRAY['prompt_builder','practical_response','homework','submission']
    OR (
      EXISTS (
        SELECT 1 FROM public.academy_lessons l
        WHERE l.id=v.academy_lesson_id
          AND l.module_id IN (
            's02-m01','s02-m02','s02-m03','s02-m04','s02-m05','s02-m06',
            's02-m07','s02-m08','s02-m09',
            's02-m10','s02-m11','s02-m12',
            's02-m13','s02-m14'
          )
      )
      AND kinds && ARRAY[
        'sequence_sort','matching','image_hotspot','decision_tree',
        'scenario','client_simulation','calculator'
      ]
    )
  ) THEN errors:=errors||jsonb_build_array('missing_practice'); END IF;
  IF NOT ('summary'=ANY(kinds)) THEN errors:=errors||jsonb_build_array('missing_summary'); END IF;
  IF EXISTS (
    SELECT 1 FROM public.academy_lesson_blocks b
    WHERE b.version_id=p_version AND b.required AND b.points=0
  ) THEN warnings:=warnings||jsonb_build_array('required_block_has_no_xp'); END IF;
  IF EXISTS (
    SELECT 1
    FROM public.academy_lesson_blocks b
    LEFT JOIN academy_private.lesson_block_keys k ON k.block_id=b.id
    WHERE b.version_id=p_version
      AND b.block_type IN (
        'sequence_sort','matching','image_hotspot','decision_tree','scenario',
        'client_simulation','calculator','quiz'
      )
      AND k.block_id IS NULL
  ) THEN errors:=errors||jsonb_build_array('missing_server_evaluation'); END IF;

  RETURN jsonb_build_object(
    'errors',errors,
    'warnings',warnings,
    'block_count',n,
    'interactive',kinds && ARRAY[
      'sequence_sort','matching','image_hotspot','decision_tree','scenario',
      'client_simulation','calculator','prompt_builder','practical_response',
      'reflection','checklist','quiz','homework','submission','flip_cards'
    ],
    'has_quiz','quiz'=ANY(kinds),
    'has_assignment',kinds && ARRAY['practical_response','homework','submission']
  );
END
$function$;



DO $release$
DECLARE
  payload jsonb := $curriculum$[{"module_id":"s02-m13","lesson_id":"pv13-01","title":"Реши за конкретен проект — сам или с екип","subtitle":"Клиентски бриф, изпълним бюджет и професионално предаване","objective":"За всяка паралелна задача има отговорник, реално време, бюджет и резерв; не обещаваш дрон или други права по подразбиране.","hook":"Клиент иска две версии утре, интервю на шумен терен и кадри от дрон. Ти си сам и имаш един микрофон.","estimated_minutes":38,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"За всяка паралелна задача има отговорник, реално време, бюджет и резерв; не обещаваш дрон или други права по подразбиране."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Клиент иска две версии утре, интервю на шумен терен и кадри от дрон. Ти си сам и имаш един микрофон."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Решението сам или с екип се взема по едновременни роли, риск и налично време. Разбий обещанието на подготовка, камера, звук, осветление, организация, монтаж и одобрения. Не продавай капацитет, който нямаш. Дори да повикаш колега, клиентът трябва да знае кой води проекта, кого одобрява и кой носи отговорност за файла."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Дръж отделно допускане, потвърден факт и обещание към клиента. Сверявай разходите и часовете с действителния обхват; примерните суми в урока не са тарифа. За договор, данъци, професионална реклама или лични данни провери приложимите правила и потърси компетентен преглед преди реална употреба. Не публикувай човек, музика, чужд продукт или резултат без проверен обхват на правото.\n\nЗа тази задача: Ограничи сцените или добави човек за звук с бюджет и отговорник; направи пробен запис преди основното интервю."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Извади отделните задачи и часовете от брифа.\n2. Отбележи кои задачи се случват едновременно и кои изискват квалификация или разрешение.\n3. Сравни три варианта: сам с по-малък обхват, партньор с ясна роля, отказ или нов срок.\n4. Потвърди избрания обхват, хората, резерва и сроковете писмено.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"За интервю в работилница човек снима, втори следи звук и шум от машини; дронът отпада, защото няма проверен оператор и разрешение. Клиентът получава две изпълними версии и цена за двамата.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"В офертата пише „пълна продукция“, но никой не слуша звука по време на интервюто."},"after":{"label":"Как го поправяш","text":"Ограничи сцените или добави човек за звук с бюджет и отговорник; направи пробен запис преди основното интервю."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: В офертата пише „пълна продукция“, но никой не слуша звука по време на интервюто.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Извади отделните задачи и часовете от брифа. След него: Сравни три варианта: сам с по-малък обхват, партньор с ясна роля, отказ или нов срок.\n\nКорекция: Ограничи сцените или добави човек за звук с бюджет и отговорник; направи пробен запис преди основното интервю.\n\nНови данни, които ще приемеш за успешна поправка: За всяка паралелна задача има отговорник, реално време, бюджет и резерв; не обещаваш дрон или други права по подразбиране. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Вземи измислен бриф за интервю и продуктови кадри. Направи матрица задача × човек × час × риск, две варианти на екип и писмено решение.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"За всяка паралелна задача има отговорник, реално време, бюджет и резерв; не обещаваш дрон или други права по подразбиране.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: За интервю в работилница човек снима, втори следи звук и шум от машини; дронът отпада, защото няма проверен оператор и разрешение. Клиентът получава две изпълними версии и цена за двамата.\n\nДоставка: Вземи измислен бриф за интервю и продуктови кадри. Направи матрица задача × човек × час × риск, две варианти на екип и писмено решение.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: За всяка паралелна задача има отговорник, реално време, бюджет и резерв; не обещаваш дрон или други права по подразбиране."},"points":1,"required":false},{"position":11,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Кой сигнал изисква втори човек?","options":[{"id":"a","label":"Самият факт, че камерата е скъпа."},{"id":"b","label":"Едновременно интервю, следене на звук и сложна площадка."},{"id":"c","label":"Желание клипът да изглежда голям."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Едновременно интервю, следене на звук и сложна площадка.\n\nПървият слаб ход — Самият факт, че камерата е скъпа. — пропуска тази проверка: За всяка паралелна задача има отговорник, реално време, бюджет и резерв; не обещаваш дрон или други права по подразбиране. Вторият — Желание клипът да изглежда голям. — оставя този риск: В офертата пише „пълна продукция“, но никой не слуша звука по време на интервюто. В работна ситуация поправката е: Ограничи сцените или добави човек за звук с бюджет и отговорник; направи пробен запис преди основното интервю. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Бюджетът стига само за един човек. Какво предлагаш?","options":[{"id":"a","label":"Снимаш без проба и поправяш звук с AI."},{"id":"b","label":"По-малък обхват или нов срок с писмено уточнение."},{"id":"c","label":"Същия план с неплатен втори човек."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: По-малък обхват или нов срок с писмено уточнение.\n\nПървият слаб ход — Същия план с неплатен втори човек. — пропуска тази проверка: За всяка паралелна задача има отговорник, реално време, бюджет и резерв; не обещаваш дрон или други права по подразбиране. Вторият — Снимаш без проба и поправяш звук с AI. — оставя този риск: В офертата пише „пълна продукция“, но никой не слуша звука по време на интервюто. В работна ситуация поправката е: Ограничи сцените или добави човек за звук с бюджет и отговорник; направи пробен запис преди основното интервю. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Как доказваш, че планът е изпълним?","options":[{"id":"a","label":"Часове, роли, зависимост и проба на най-рисковия запис."},{"id":"b","label":"Само обща цена."},{"id":"c","label":"Брой лога в брифа."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Часове, роли, зависимост и проба на най-рисковия запис.\n\nПървият слаб ход — Брой лога в брифа. — пропуска тази проверка: За всяка паралелна задача има отговорник, реално време, бюджет и резерв; не обещаваш дрон или други права по подразбиране. Вторият — Само обща цена. — оставя този риск: В офертата пише „пълна продукция“, но никой не слуша звука по време на интервюто. В работна ситуация поправката е: Ограничи сцените или добави човек за звук с бюджет и отговорник; направи пробен запис преди основното интервю. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: В офертата пише „пълна продукция“, но никой не слуша звука по време на интервюто. Как продължаваш?","options":[{"id":"a","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"b","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"c","label":"Ограничи сцените или добави човек за звук с бюджет и отговорник; направи пробен запис преди основното интервю."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Ограничи сцените или добави човек за звук с бюджет и отговорник; направи пробен запис преди основното интервю.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: За всяка паралелна задача има отговорник, реално време, бюджет и резерв; не обещаваш дрон или други права по подразбиране. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: В офертата пише „пълна продукция“, но никой не слуша звука по време на интервюто. В работна ситуация поправката е: Ограничи сцените или добави човек за звук с бюджет и отговорник; направи пробен запис преди основното интервю. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s2","text":"Отбележи кои задачи се случват едновременно и кои изискват квалификация или разрешение."},{"id":"s3","text":"Сравни три варианта: сам с по-малък обхват, партньор с ясна роля, отказ или нов срок."},{"id":"s4","text":"Потвърди избрания обхват, хората, резерва и сроковете писмено."},{"id":"s1","text":"Извади отделните задачи и часовете от брифа."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Извади отделните задачи и часовете от брифа.\n2. Отбележи кои задачи се случват едновременно и кои изискват квалификация или разрешение.\n3. Сравни три варианта: сам с по-малък обхват, партньор с ясна роля, отказ или нов срок.\n4. Потвърди избрания обхват, хората, резерва и сроковете писмено.\n\nПреди окончателното предаване потвърди: За всяка паралелна задача има отговорник, реално време, бюджет и резерв; не обещаваш дрон или други права по подразбиране. Ако разместиш проверката след предаването, остава този риск: В офертата пише „пълна продукция“, но никой не слуша звука по време на интервюто."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Решението сам или с екип се взема по едновременни роли, риск и налично време. Разбий обещанието на подготовка, камера, звук, осветление, организация, монтаж и одобрения. Не продавай капацитет, който нямаш. Дори да повикаш колега, клиентът трябва да знае кой води проекта, кого одобрява и кой носи отговорност за файла.","Ограничи сцените или добави човек за звук с бюджет и отговорник; направи пробен запис преди основното интервю.","За всяка паралелна задача има отговорник, реално време, бюджет и резерв; не обещаваш дрон или други права по подразбиране."],"nextStep":"Вземи измислен бриф за интервю и продуктови кадри. Направи матрица задача × човек × час × риск, две варианти на екип и писмено решение."},"points":1,"required":true}]},{"module_id":"s02-m13","lesson_id":"pv13-02","title":"Напиши бриф, който друг човек може да разбере без обяснения","subtitle":"Клиентски бриф, изпълним бюджет и професионално предаване","objective":"Друг човек може да планира снимки и да назове неизвестното без устно дообясняване; клиентът потвърждава критичните факти.","hook":"„Направете ми нещо яко за социалните мрежи“ звучи като задача, докато монтажистът не попита кое е важно.","estimated_minutes":36,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Друг човек може да планира снимки и да назове неизвестното без устно дообясняване; клиентът потвърждава критичните факти."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"„Направете ми нещо яко за социалните мрежи“ звучи като задача, докато монтажистът не попита кое е важно."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Работещият бриф позволява на непознат колега да вземе същите решения. Той съдържа бизнес задача, конкретна публика, едно обещание, доказателство, действие, канали, размери, срокове, материал, права и кой одобрява. Отдели известните факти от хипотезите и въпросите. Ако клиентът не може да потвърди твърдение, не го слагай в кадъра."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Дръж отделно допускане, потвърден факт и обещание към клиента. Сверявай разходите и часовете с действителния обхват; примерните суми в урока не са тарифа. За договор, данъци, професионална реклама или лични данни провери приложимите правила и потърси компетентен преглед преди реална употреба. Не публикувай човек, музика, чужд продукт или резултат без проверен обхват на правото.\n\nЗа тази задача: Върни се към бизнес задачата и напиши проверим кадър, действие и отговорник за всяко твърдение."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Питай какво човекът трябва да разбере или направи след видеото.\n2. Запиши целева публика, сцена с доказателство и действие с точен адрес.\n3. Потвърди налични файлове, лица, забрани, срокове и един вземащ решение.\n4. Дай брифа на колега и поправи местата, за които пита.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Малка пекарна иска клип за поръчка на торта. Брифът показва истинската украса и срок за поръчка, не обещава доставка навсякъде; собственикът потвърждава цената и финалния надпис.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Брифът описва настроение и музика, но не казва какво се продава и кой одобрява."},"after":{"label":"Как го поправяш","text":"Върни се към бизнес задачата и напиши проверим кадър, действие и отговорник за всяко твърдение."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Брифът описва настроение и музика, но не казва какво се продава и кой одобрява.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Питай какво човекът трябва да разбере или направи след видеото. След него: Потвърди налични файлове, лица, забрани, срокове и един вземащ решение.\n\nКорекция: Върни се към бизнес задачата и напиши проверим кадър, действие и отговорник за всяко твърдение.\n\nНови данни, които ще приемеш за успешна поправка: Друг човек може да планира снимки и да назове неизвестното без устно дообясняване; клиентът потвърждава критичните факти. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Напиши едностраничен бриф за продукт с цел, публика, сцена, формат, права, срок, одобрение и три отворени въпроса. Дай го на човек без контекст.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Друг човек може да планира снимки и да назове неизвестното без устно дообясняване; клиентът потвърждава критичните факти.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Малка пекарна иска клип за поръчка на торта. Брифът показва истинската украса и срок за поръчка, не обещава доставка навсякъде; собственикът потвърждава цената и финалния надпис.\n\nДоставка: Напиши едностраничен бриф за продукт с цел, публика, сцена, формат, права, срок, одобрение и три отворени въпроса. Дай го на човек без контекст.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Друг човек може да планира снимки и да назове неизвестното без устно дообясняване; клиентът потвърждава критичните факти."},"points":1,"required":false},{"position":11,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Кое липсва в „искам модерно видео“?","options":[{"id":"a","label":"Цел, публика, доказателство и следващо действие."},{"id":"b","label":"Още прилагателни."},{"id":"c","label":"Име на камера."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Цел, публика, доказателство и следващо действие.\n\nПървият слаб ход — Още прилагателни. — пропуска тази проверка: Друг човек може да планира снимки и да назове неизвестното без устно дообясняване; клиентът потвърждава критичните факти. Вторият — Име на камера. — оставя този риск: Брифът описва настроение и музика, но не казва какво се продава и кой одобрява. В работна ситуация поправката е: Върни се към бизнес задачата и напиши проверим кадър, действие и отговорник за всяко твърдение. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Клиентът не знае точния срок за доставка. Какво влиза в брифа?","options":[{"id":"a","label":"„Доставяме утре“ за по-силен hook."},{"id":"b","label":"Отворен въпрос с отговорник; без непотвърдено обещание."},{"id":"c","label":"Измислен диапазон."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Отворен въпрос с отговорник; без непотвърдено обещание.\n\nПървият слаб ход — „Доставяме утре“ за по-силен hook. — пропуска тази проверка: Друг човек може да планира снимки и да назове неизвестното без устно дообясняване; клиентът потвърждава критичните факти. Вторият — Измислен диапазон. — оставя този риск: Брифът описва настроение и музика, но не казва какво се продава и кой одобрява. В работна ситуация поправката е: Върни се към бизнес задачата и напиши проверим кадър, действие и отговорник за всяко твърдение. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Кой е тестът за яснота?","options":[{"id":"a","label":"Дължина две страници."},{"id":"b","label":"Колега прави план и връща само действителните неизвестни."},{"id":"c","label":"Клиентът казва „супер“ без да е чел."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Колега прави план и връща само действителните неизвестни.\n\nПървият слаб ход — Клиентът казва „супер“ без да е чел. — пропуска тази проверка: Друг човек може да планира снимки и да назове неизвестното без устно дообясняване; клиентът потвърждава критичните факти. Вторият — Дължина две страници. — оставя този риск: Брифът описва настроение и музика, но не казва какво се продава и кой одобрява. В работна ситуация поправката е: Върни се към бизнес задачата и напиши проверим кадър, действие и отговорник за всяко твърдение. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Брифът описва настроение и музика, но не казва какво се продава и кой одобрява. Как продължаваш?","options":[{"id":"a","label":"Върни се към бизнес задачата и напиши проверим кадър, действие и отговорник за всяко твърдение."},{"id":"b","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"c","label":"Продължаваш без проверка и наричаш тази версия окончателна."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Върни се към бизнес задачата и напиши проверим кадър, действие и отговорник за всяко твърдение.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Друг човек може да планира снимки и да назове неизвестното без устно дообясняване; клиентът потвърждава критичните факти. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Брифът описва настроение и музика, но не казва какво се продава и кой одобрява. В работна ситуация поправката е: Върни се към бизнес задачата и напиши проверим кадър, действие и отговорник за всяко твърдение. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s2","text":"Запиши целева публика, сцена с доказателство и действие с точен адрес."},{"id":"s1","text":"Питай какво човекът трябва да разбере или направи след видеото."},{"id":"s4","text":"Дай брифа на колега и поправи местата, за които пита."},{"id":"s3","text":"Потвърди налични файлове, лица, забрани, срокове и един вземащ решение."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Питай какво човекът трябва да разбере или направи след видеото.\n2. Запиши целева публика, сцена с доказателство и действие с точен адрес.\n3. Потвърди налични файлове, лица, забрани, срокове и един вземащ решение.\n4. Дай брифа на колега и поправи местата, за които пита.\n\nПреди окончателното предаване потвърди: Друг човек може да планира снимки и да назове неизвестното без устно дообясняване; клиентът потвърждава критичните факти. Ако разместиш проверката след предаването, остава този риск: Брифът описва настроение и музика, но не казва какво се продава и кой одобрява."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Работещият бриф позволява на непознат колега да вземе същите решения. Той съдържа бизнес задача, конкретна публика, едно обещание, доказателство, действие, канали, размери, срокове, материал, права и кой одобрява. Отдели известните факти от хипотезите и въпросите. Ако клиентът не може да потвърди твърдение, не го слагай в кадъра.","Върни се към бизнес задачата и напиши проверим кадър, действие и отговорник за всяко твърдение.","Друг човек може да планира снимки и да назове неизвестното без устно дообясняване; клиентът потвърждава критичните факти."],"nextStep":"Напиши едностраничен бриф за продукт с цел, публика, сцена, формат, права, срок, одобрение и три отворени въпроса. Дай го на човек без контекст."},"points":1,"required":true}]},{"module_id":"s02-m13","lesson_id":"pv13-03","title":"Направи реален бюджет за проект по часове и разходи","subtitle":"Клиентски бриф, изпълним бюджет и професионално предаване","objective":"Сметката може да се повтори от входните данни; отделни са разход, резерв, цена и данъчни допускания.","hook":"Оферта за два клипа изглежда печеливша, докато не добавиш срещите, пътя и втория монтаж.","estimated_minutes":42,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Сметката може да се повтори от входните данни; отделни са разход, резерв, цена и данъчни допускания."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Оферта за два клипа изглежда печеливша, докато не добавиш срещите, пътя и втория монтаж."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Бюджетът започва с работа по етапи и допускания, после външни разходи и резерв. Различавай себестойност, предложена цена, данъци и свободни пари. В пример: 14 часа × 40 € вътрешна ставка = 560 €, наем и път 120 €, резерв 10% върху 680 € = 68 €; основата е 748 €. Това не е универсална пазарна тарифа и данъчното третиране се проверява със счетоводител."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Дръж отделно допускане, потвърден факт и обещание към клиента. Сверявай разходите и часовете с действителния обхват; примерните суми в урока не са тарифа. За договор, данъци, професионална реклама или лични данни провери приложимите правила и потърси компетентен преглед преди реална употреба. Не публикувай човек, музика, чужд продукт или резултат без проверен обхват на правото.\n\nЗа тази задача: Разбий цената на дейности и запиши допусканията; за нов обхват направи нова оценка, вместо да скриеш разхода."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Разпиши часове за бриф, подготовка, снимки, монтаж, ревизии и предаване.\n2. Добави хора, техника, лиценз, транспорт и допускане за броя версии.\n3. Изчисли вътрешна основа и резерв отделно от клиентската цена.\n4. Провери как се променя резултатът при още една снимачна смяна.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Пекарна иска 1 основен клип и 2 изрязвания. Бюджетът отделя 2 часа срещи, 3 снимки, 6 монтаж, 3 корекции и доставка; ако добави втори адрес, офертата се променя преди снимките.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Пишеш „снимки 200“, а после плащаш наем и четири непланирани ревизии."},"after":{"label":"Как го поправяш","text":"Разбий цената на дейности и запиши допусканията; за нов обхват направи нова оценка, вместо да скриеш разхода."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Пишеш „снимки 200“, а после плащаш наем и четири непланирани ревизии.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Разпиши часове за бриф, подготовка, снимки, монтаж, ревизии и предаване. След него: Изчисли вътрешна основа и резерв отделно от клиентската цена.\n\nКорекция: Разбий цената на дейности и запиши допусканията; за нов обхват направи нова оценка, вместо да скриеш разхода.\n\nНови данни, които ще приемеш за успешна поправка: Сметката може да се повтори от входните данни; отделни са разход, резерв, цена и данъчни допускания. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Построй таблица за конкретен двудневен проект с часове, ставки, външни разходи, 10% резерв и сценарий +1 смяна. Покажи всяка формула.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Сметката може да се повтори от входните данни; отделни са разход, резерв, цена и данъчни допускания.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Пекарна иска 1 основен клип и 2 изрязвания. Бюджетът отделя 2 часа срещи, 3 снимки, 6 монтаж, 3 корекции и доставка; ако добави втори адрес, офертата се променя преди снимките.\n\nДоставка: Построй таблица за конкретен двудневен проект с часове, ставки, външни разходи, 10% резерв и сценарий +1 смяна. Покажи всяка формула.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Сметката може да се повтори от входните данни; отделни са разход, резерв, цена и данъчни допускания."},"points":1,"required":false},{"position":11,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Колко е основата в примера преди клиентска надценка?","options":[{"id":"a","label":"560 € с включен наем и път."},{"id":"b","label":"680 € с включен резерв."},{"id":"c","label":"748 € при посочените допускания."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: 748 € при посочените допускания.\n\nПървият слаб ход — 680 € с включен резерв. — пропуска тази проверка: Сметката може да се повтори от входните данни; отделни са разход, резерв, цена и данъчни допускания. Вторият — 560 € с включен наем и път. — оставя този риск: Пишеш „снимки 200“, а после плащаш наем и четири непланирани ревизии. В работна ситуация поправката е: Разбий цената на дейности и запиши допусканията; за нов обхват направи нова оценка, вместо да скриеш разхода. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Клиентът добавя втори адрес след офертата. Какво правиш?","options":[{"id":"a","label":"Преизчисляваш часове и път, уточняваш цена и срок преди работа."},{"id":"b","label":"Приемаш, защото видеото е същото."},{"id":"c","label":"Премахваш резерва тайно."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Преизчисляваш часове и път, уточняваш цена и срок преди работа.\n\nПървият слаб ход — Приемаш, защото видеото е същото. — пропуска тази проверка: Сметката може да се повтори от входните данни; отделни са разход, резерв, цена и данъчни допускания. Вторият — Премахваш резерва тайно. — оставя този риск: Пишеш „снимки 200“, а после плащаш наем и четири непланирани ревизии. В работна ситуация поправката е: Разбий цената на дейности и запиши допусканията; за нов обхват направи нова оценка, вместо да скриеш разхода. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Кое число трябва да е видимо отделно?","options":[{"id":"a","label":"Само крайното число."},{"id":"b","label":"Външен разход и резерв, с основата за изчисление."},{"id":"c","label":"Брой филтри в монтажа."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Външен разход и резерв, с основата за изчисление.\n\nПървият слаб ход — Само крайното число. — пропуска тази проверка: Сметката може да се повтори от входните данни; отделни са разход, резерв, цена и данъчни допускания. Вторият — Брой филтри в монтажа. — оставя този риск: Пишеш „снимки 200“, а после плащаш наем и четири непланирани ревизии. В работна ситуация поправката е: Разбий цената на дейности и запиши допусканията; за нов обхват направи нова оценка, вместо да скриеш разхода. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Пишеш „снимки 200“, а после плащаш наем и четири непланирани ревизии. Как продължаваш?","options":[{"id":"a","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"b","label":"Разбий цената на дейности и запиши допусканията; за нов обхват направи нова оценка, вместо да скриеш разхода."},{"id":"c","label":"Продължаваш без проверка и наричаш тази версия окончателна."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Разбий цената на дейности и запиши допусканията; за нов обхват направи нова оценка, вместо да скриеш разхода.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Сметката може да се повтори от входните данни; отделни са разход, резерв, цена и данъчни допускания. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Пишеш „снимки 200“, а после плащаш наем и четири непланирани ревизии. В работна ситуация поправката е: Разбий цената на дейности и запиши допусканията; за нов обхват направи нова оценка, вместо да скриеш разхода. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s4","text":"Провери как се променя резултатът при още една снимачна смяна."},{"id":"s1","text":"Разпиши часове за бриф, подготовка, снимки, монтаж, ревизии и предаване."},{"id":"s2","text":"Добави хора, техника, лиценз, транспорт и допускане за броя версии."},{"id":"s3","text":"Изчисли вътрешна основа и резерв отделно от клиентската цена."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Разпиши часове за бриф, подготовка, снимки, монтаж, ревизии и предаване.\n2. Добави хора, техника, лиценз, транспорт и допускане за броя версии.\n3. Изчисли вътрешна основа и резерв отделно от клиентската цена.\n4. Провери как се променя резултатът при още една снимачна смяна.\n\nПреди окончателното предаване потвърди: Сметката може да се повтори от входните данни; отделни са разход, резерв, цена и данъчни допускания. Ако разместиш проверката след предаването, остава този риск: Пишеш „снимки 200“, а после плащаш наем и четири непланирани ревизии."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Бюджетът започва с работа по етапи и допускания, после външни разходи и резерв. Различавай себестойност, предложена цена, данъци и свободни пари. В пример: 14 часа × 40 € вътрешна ставка = 560 €, наем и път 120 €, резерв 10% върху 680 € = 68 €; основата е 748 €. Това не е универсална пазарна тарифа и данъчното третиране се проверява със счетоводител.","Разбий цената на дейности и запиши допусканията; за нов обхват направи нова оценка, вместо да скриеш разхода.","Сметката може да се повтори от входните данни; отделни са разход, резерв, цена и данъчни допускания."],"nextStep":"Построй таблица за конкретен двудневен проект с часове, ставки, външни разходи, 10% резерв и сценарий +1 смяна. Покажи всяка формула."},"points":1,"required":true}]},{"module_id":"s02-m13","lesson_id":"pv13-04","title":"Скицирай какво би снимал за ресторант/магазин клиент","subtitle":"Клиентски бриф, изпълним бюджет и професионално предаване","objective":"Всеки кадър помага за избраното действие, а продукт, цени, наличност и разпознаваеми хора са проверени.","hook":"Ресторант показва перфектен десерт от stock, а клиентите получават друг продукт.","estimated_minutes":38,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Всеки кадър помага за избраното действие, а продукт, цени, наличност и разпознаваеми хора са проверени."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Ресторант показва перфектен десерт от stock, а клиентите получават друг продукт."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"За местен бизнес снимай действителното преживяване: вход, поръчка, приготвяне, сервиране и един проверен път до резервация или покупка. При магазин покажи размер, наличност и използване, без да измисляш качество от кадър. Разрешения за персонал и посетители се планират преди камерата; при неяснота кадрирай без разпознаваеми лица."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Дръж отделно допускане, потвърден факт и обещание към клиента. Сверявай разходите и часовете с действителния обхват; примерните суми в урока не са тарифа. За договор, данъци, професионална реклама или лични данни провери приложимите правила и потърси компетентен преглед преди реална употреба. Не публикувай човек, музика, чужд продукт или резултат без проверен обхват на правото.\n\nЗа тази задача: Подмени общия кадър с процес и реален продукт; потвърди търговските факти и правата за хората."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Избери едно решение на клиента: резервация, посещение или конкретна покупка.\n2. Направи списък на шест доказващи кадъра и една честна граница на офертата.\n3. Провери наличност, актуално меню/цена, хора в кадър и адреса на действието.\n4. Заснеми пробен продукт и провери дали екранът показва същото.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Семейна пекарна снима истинската торта в разрез, избор на размер, ръчно декориране и кутия с име. Видео за поръчки води към действаща страница и посочва кога се приемат заявки.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Широк красив кадър, но продуктът, адресът и хората на фокус не са проверени."},"after":{"label":"Как го поправяш","text":"Подмени общия кадър с процес и реален продукт; потвърди търговските факти и правата за хората."}},"points":2,"required":true},{"position":7,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Скицирай 6 кадъра за реален ресторант или магазин без да ползваш чужд материал; срещу всеки напиши какво доказва и кой го одобрява.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Всеки кадър помага за избраното действие, а продукт, цени, наличност и разпознаваеми хора са проверени.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":9,"block_key":"reference","block_type":"rich_text","title":"Проверен първоизточник","content":{"body":"EDPB — насоки за обработване на лични данни чрез видео: https://www.edpb.europa.eu/documents/guideline/guidelines-32019-on-processing-of-personal-data-through-video-devices_en\nПровери текущата версия на функцията преди да повториш стъпките."},"points":0,"required":false},{"position":10,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Кой кадър доказва обещанието?","options":[{"id":"a","label":"Чужд viral десерт."},{"id":"b","label":"Произволно drone видео."},{"id":"c","label":"Реалният продукт и процесът на конкретния обект."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Реалният продукт и процесът на конкретния обект.\n\nПървият слаб ход — Чужд viral десерт. — пропуска тази проверка: Всеки кадър помага за избраното действие, а продукт, цени, наличност и разпознаваеми хора са проверени. Вторият — Произволно drone видео. — оставя този риск: Широк красив кадър, но продуктът, адресът и хората на фокус не са проверени. В работна ситуация поправката е: Подмени общия кадър с процес и реален продукт; потвърди търговските факти и правата за хората. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"В ресторанта има гости без разрешение за реклама. Как снимаш?","options":[{"id":"a","label":"Публикуваш без звук."},{"id":"b","label":"Разчиташ на това, че са на публично място."},{"id":"c","label":"Променяш ъгъла или организираш разрешена сцена."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Променяш ъгъла или организираш разрешена сцена.\n\nПървият слаб ход — Разчиташ на това, че са на публично място. — пропуска тази проверка: Всеки кадър помага за избраното действие, а продукт, цени, наличност и разпознаваеми хора са проверени. Вторият — Публикуваш без звук. — оставя този риск: Широк красив кадър, но продуктът, адресът и хората на фокус не са проверени. В работна ситуация поправката е: Подмени общия кадър с процес и реален продукт; потвърди търговските факти и правата за хората. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Какво проверяваш преди финалния файл?","options":[{"id":"a","label":"Реален продукт, актуални факти, разрешени лица и работеща връзка."},{"id":"b","label":"Само красив цвят."},{"id":"c","label":"Брой преходи."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Реален продукт, актуални факти, разрешени лица и работеща връзка.\n\nПървият слаб ход — Само красив цвят. — пропуска тази проверка: Всеки кадър помага за избраното действие, а продукт, цени, наличност и разпознаваеми хора са проверени. Вторият — Брой преходи. — оставя този риск: Широк красив кадър, но продуктът, адресът и хората на фокус не са проверени. В работна ситуация поправката е: Подмени общия кадър с процес и реален продукт; потвърди търговските факти и правата за хората. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Широк красив кадър, но продуктът, адресът и хората на фокус не са проверени. Как продължаваш?","options":[{"id":"a","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"b","label":"Подмени общия кадър с процес и реален продукт; потвърди търговските факти и правата за хората."},{"id":"c","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Подмени общия кадър с процес и реален продукт; потвърди търговските факти и правата за хората.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Всеки кадър помага за избраното действие, а продукт, цени, наличност и разпознаваеми хора са проверени. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Широк красив кадър, но продуктът, адресът и хората на фокус не са проверени. В работна ситуация поправката е: Подмени общия кадър с процес и реален продукт; потвърди търговските факти и правата за хората. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s4","text":"Заснеми пробен продукт и провери дали екранът показва същото."},{"id":"s3","text":"Провери наличност, актуално меню/цена, хора в кадър и адреса на действието."},{"id":"s2","text":"Направи списък на шест доказващи кадъра и една честна граница на офертата."},{"id":"s1","text":"Избери едно решение на клиента: резервация, посещение или конкретна покупка."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Избери едно решение на клиента: резервация, посещение или конкретна покупка.\n2. Направи списък на шест доказващи кадъра и една честна граница на офертата.\n3. Провери наличност, актуално меню/цена, хора в кадър и адреса на действието.\n4. Заснеми пробен продукт и провери дали екранът показва същото.\n\nПреди окончателното предаване потвърди: Всеки кадър помага за избраното действие, а продукт, цени, наличност и разпознаваеми хора са проверени. Ако разместиш проверката след предаването, остава този риск: Широк красив кадър, но продуктът, адресът и хората на фокус не са проверени."},"scoring":{"mode":"exact_order"}},{"position":15,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["За местен бизнес снимай действителното преживяване: вход, поръчка, приготвяне, сервиране и един проверен път до резервация или покупка. При магазин покажи размер, наличност и използване, без да измисляш качество от кадър. Разрешения за персонал и посетители се планират преди камерата; при неяснота кадрирай без разпознаваеми лица.","Подмени общия кадър с процес и реален продукт; потвърди търговските факти и правата за хората.","Всеки кадър помага за избраното действие, а продукт, цени, наличност и разпознаваеми хора са проверени."],"nextStep":"Скицирай 6 кадъра за реален ресторант или магазин без да ползваш чужд материал; срещу всеки напиши какво доказва и кой го одобрява."},"points":1,"required":true}]},{"module_id":"s02-m13","lesson_id":"pv13-05","title":"Скицирай какво би снимал за адвокат/лекар клиент","subtitle":"Клиентски бриф, изпълним бюджет и професионално предаване","objective":"Няма идентифицируем клиент без надлежно основание; професионалист е одобрил фактите и видеото не обещава резултат.","hook":"Клиника иска „видео, което обещава резултат“, а един пациент случайно се вижда зад лекаря.","estimated_minutes":40,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Няма идентифицируем клиент без надлежно основание; професионалист е одобрил фактите и видеото не обещава резултат."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Клиника иска „видео, което обещава резултат“, а един пациент случайно се вижда зад лекаря."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Професионалните услуги се снимат с по-висока проверка на твърдения и лична информация. Покажи процес на първи контакт, въпроси за консултация, екип и среда, без индивидуална диагноза, гарантиран изход или непроверено професионално твърдение. Случаите и кадрите с пациенти/клиенти изискват отделна правна и редакционна проверка, а ограниченията за конкретната професия и държава се потвърждават от клиента и специалист."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Дръж отделно допускане, потвърден факт и обещание към клиента. Сверявай разходите и часовете с действителния обхват; примерните суми в урока не са тарифа. За договор, данъци, професионална реклама или лични данни провери приложимите правила и потърси компетентен преглед преди реална употреба. Не публикувай човек, музика, чужд продукт или резултат без проверен обхват на правото.\n\nЗа тази задача: Махни внушението и личния случай; покажи проверим процес и отбележи какво зависи от индивидуална оценка."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Запиши коя информация е обща и коя е лична или професионално чувствителна.\n2. Избери кадри без разпознаваеми посетители и скрити документи.\n3. Изпрати сценария за фактологично и професионално одобрение.\n4. Провери финалния export кадър по кадър за лица, екрани и обещания.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"За адвокатска кантора видеото показва как се записва първоначален разговор и какви документи е полезно да се подготвят. Не показва дело на клиент и не обещава спечелване.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Драматичен testimonial подсказва, че всяко дело или лечение завършва еднакво."},"after":{"label":"Как го поправяш","text":"Махни внушението и личния случай; покажи проверим процес и отбележи какво зависи от индивидуална оценка."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Драматичен testimonial подсказва, че всяко дело или лечение завършва еднакво.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Запиши коя информация е обща и коя е лична или професионално чувствителна. След него: Изпрати сценария за фактологично и професионално одобрение.\n\nКорекция: Махни внушението и личния случай; покажи проверим процес и отбележи какво зависи от индивидуална оценка.\n\nНови данни, които ще приемеш за успешна поправка: Няма идентифицируем клиент без надлежно основание; професионалист е одобрил фактите и видеото не обещава резултат. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Направи shot list и текст за 30-секундно видео за лекар или адвокат; маркирай всеки потенциален личен детайл и всяко твърдение за преглед.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Няма идентифицируем клиент без надлежно основание; професионалист е одобрил фактите и видеото не обещава резултат.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: За адвокатска кантора видеото показва как се записва първоначален разговор и какви документи е полезно да се подготвят. Не показва дело на клиент и не обещава спечелване.\n\nДоставка: Направи shot list и текст за 30-секундно видео за лекар или адвокат; маркирай всеки потенциален личен детайл и всяко твърдение за преглед.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Няма идентифицируем клиент без надлежно основание; професионалист е одобрил фактите и видеото не обещава резултат."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Проверен първоизточник","content":{"body":"EDPB — насоки за обработване на лични данни чрез видео: https://www.edpb.europa.eu/documents/guideline/guidelines-32019-on-processing-of-personal-data-through-video-devices_en\nПровери текущата версия на функцията преди да повториш стъпките."},"points":0,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Кой сюжет е най-защитим?","options":[{"id":"a","label":"Пътят до консултация с факти, одобрени от професионалиста."},{"id":"b","label":"Случай с видими документи."},{"id":"c","label":"Гаранция за излекуване."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Пътят до консултация с факти, одобрени от професионалиста.\n\nПървият слаб ход — Гаранция за излекуване. — пропуска тази проверка: Няма идентифицируем клиент без надлежно основание; професионалист е одобрил фактите и видеото не обещава резултат. Вторият — Случай с видими документи. — оставя този риск: Драматичен testimonial подсказва, че всяко дело или лечение завършва еднакво. В работна ситуация поправката е: Махни внушението и личния случай; покажи проверим процес и отбележи какво зависи от индивидуална оценка. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"В отражение се вижда пациент. Какво правиш?","options":[{"id":"a","label":"Пускаш го, защото е на заден план."},{"id":"b","label":"Променяш музиката."},{"id":"c","label":"Изключваш кадъра или го преработваш и правиш нов QA."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Изключваш кадъра или го преработваш и правиш нов QA.\n\nПървият слаб ход — Пускаш го, защото е на заден план. — пропуска тази проверка: Няма идентифицируем клиент без надлежно основание; професионалист е одобрил фактите и видеото не обещава резултат. Вторият — Променяш музиката. — оставя този риск: Драматичен testimonial подсказва, че всяко дело или лечение завършва еднакво. В работна ситуация поправката е: Махни внушението и личния случай; покажи проверим процес и отбележи какво зависи от индивидуална оценка. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Кой подписва съдържателния преглед?","options":[{"id":"a","label":"Алгоритъм за трендове."},{"id":"b","label":"Само монтажистът."},{"id":"c","label":"Компетентен представител на клиента и при нужда правен специалист."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Компетентен представител на клиента и при нужда правен специалист.\n\nПървият слаб ход — Само монтажистът. — пропуска тази проверка: Няма идентифицируем клиент без надлежно основание; професионалист е одобрил фактите и видеото не обещава резултат. Вторият — Алгоритъм за трендове. — оставя този риск: Драматичен testimonial подсказва, че всяко дело или лечение завършва еднакво. В работна ситуация поправката е: Махни внушението и личния случай; покажи проверим процес и отбележи какво зависи от индивидуална оценка. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Драматичен testimonial подсказва, че всяко дело или лечение завършва еднакво. Как продължаваш?","options":[{"id":"a","label":"Махни внушението и личния случай; покажи проверим процес и отбележи какво зависи от индивидуална оценка."},{"id":"b","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"c","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Махни внушението и личния случай; покажи проверим процес и отбележи какво зависи от индивидуална оценка.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Няма идентифицируем клиент без надлежно основание; професионалист е одобрил фактите и видеото не обещава резултат. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Драматичен testimonial подсказва, че всяко дело или лечение завършва еднакво. В работна ситуация поправката е: Махни внушението и личния случай; покажи проверим процес и отбележи какво зависи от индивидуална оценка. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s2","text":"Избери кадри без разпознаваеми посетители и скрити документи."},{"id":"s3","text":"Изпрати сценария за фактологично и професионално одобрение."},{"id":"s4","text":"Провери финалния export кадър по кадър за лица, екрани и обещания."},{"id":"s1","text":"Запиши коя информация е обща и коя е лична или професионално чувствителна."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Запиши коя информация е обща и коя е лична или професионално чувствителна.\n2. Избери кадри без разпознаваеми посетители и скрити документи.\n3. Изпрати сценария за фактологично и професионално одобрение.\n4. Провери финалния export кадър по кадър за лица, екрани и обещания.\n\nПреди окончателното предаване потвърди: Няма идентифицируем клиент без надлежно основание; професионалист е одобрил фактите и видеото не обещава резултат. Ако разместиш проверката след предаването, остава този риск: Драматичен testimonial подсказва, че всяко дело или лечение завършва еднакво."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Професионалните услуги се снимат с по-висока проверка на твърдения и лична информация. Покажи процес на първи контакт, въпроси за консултация, екип и среда, без индивидуална диагноза, гарантиран изход или непроверено професионално твърдение. Случаите и кадрите с пациенти/клиенти изискват отделна правна и редакционна проверка, а ограниченията за конкретната професия и държава се потвърждават от клиента и специалист.","Махни внушението и личния случай; покажи проверим процес и отбележи какво зависи от индивидуална оценка.","Няма идентифицируем клиент без надлежно основание; професионалист е одобрил фактите и видеото не обещава резултат."],"nextStep":"Направи shot list и текст за 30-секундно видео за лекар или адвокат; маркирай всеки потенциален личен детайл и всяко твърдение за преглед."},"points":1,"required":true}]},{"module_id":"s02-m13","lesson_id":"pv13-06","title":"Скицирай какво би снимал за фитнес/масажно студио","subtitle":"Клиентски бриф, изпълним бюджет и професионално предаване","objective":"Зрителят разбира услугата и следващото действие; няма внушено медицинско или гарантирано физическо въздействие.","hook":"Студио за масажи предлага кадър „преди и след“, който внушава медицински ефект, без измерване.","estimated_minutes":36,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Зрителят разбира услугата и следващото действие; няма внушено медицинско или гарантирано физическо въздействие."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Студио за масажи предлага кадър „преди и след“, който внушава медицински ефект, без измерване."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Покажи какво реално получава посетителят: посрещане, помещение, протокол на срещата, чистота и реална възможност за записване. Не превръщай промяна в осветлението или стойката в доказателство за здравен резултат. При фитнес показвай техника със съгласуван треньор, безопасна дистанция и вариации за начинаещи; клиентът проверява професионалните и рекламните твърдения."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Дръж отделно допускане, потвърден факт и обещание към клиента. Сверявай разходите и часовете с действителния обхват; примерните суми в урока не са тарифа. За договор, данъци, професионална реклама или лични данни провери приложимите правила и потърси компетентен преглед преди реална употреба. Не публикувай човек, музика, чужд продукт или резултат без проверен обхват на правото.\n\nЗа тази задача: Изключи сравнението; замени го с действителен процес, условия и проверим цитат само при основание."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Избери една задача: първо посещение, записване или ориентация.\n2. Направи кадри, които описват услугата, вместо да обещават лечение.\n3. Провери участниците, безопасността и условията за резервация.\n4. Тествай дали зрител без контекст разбира какво следва.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Малко фитнес студио снима първо посещение: къде оставяш вещите, как инструкторът наглася упражнение и как се запазва час. Никой не е представен като „трансформация за 7 дни“.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Две различно осветени снимки се монтират като доказано отслабване."},"after":{"label":"Как го поправяш","text":"Изключи сравнението; замени го с действителен процес, условия и проверим цитат само при основание."}},"points":2,"required":true},{"position":7,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Напиши 30-секунден план за студио с 5 кадъра, ясна граница на обещанието и проверка на безопасността на упражнението.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Зрителят разбира услугата и следващото действие; няма внушено медицинско или гарантирано физическо въздействие.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":9,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Кое показва услугата честно?","options":[{"id":"a","label":"Непроверени медицински проценти."},{"id":"b","label":"Първото посещение и работа на инструктора в реалната среда."},{"id":"c","label":"Произволен before/after."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Първото посещение и работа на инструктора в реалната среда.\n\nПървият слаб ход — Произволен before/after. — пропуска тази проверка: Зрителят разбира услугата и следващото действие; няма внушено медицинско или гарантирано физическо въздействие. Вторият — Непроверени медицински проценти. — оставя този риск: Две различно осветени снимки се монтират като доказано отслабване. В работна ситуация поправката е: Изключи сравнението; замени го с действителен процес, условия и проверим цитат само при основание. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Кадърът показва рискована техника. Какво правиш?","options":[{"id":"a","label":"Спираш и сверяваш с компетентния инструктор преди повторно снимане."},{"id":"b","label":"Ускоряваш го."},{"id":"c","label":"Добавяш warning само на финалния кадър."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Спираш и сверяваш с компетентния инструктор преди повторно снимане.\n\nПървият слаб ход — Добавяш warning само на финалния кадър. — пропуска тази проверка: Зрителят разбира услугата и следващото действие; няма внушено медицинско или гарантирано физическо въздействие. Вторият — Ускоряваш го. — оставя този риск: Две различно осветени снимки се монтират като доказано отслабване. В работна ситуация поправката е: Изключи сравнението; замени го с действителен процес, условия и проверим цитат само при основание. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Кое е доказателството за готовност?","options":[{"id":"a","label":"Само музика."},{"id":"b","label":"Само красив интериор."},{"id":"c","label":"Одобрен процес, безопасен кадър и точен път за записване."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Одобрен процес, безопасен кадър и точен път за записване.\n\nПървият слаб ход — Само музика. — пропуска тази проверка: Зрителят разбира услугата и следващото действие; няма внушено медицинско или гарантирано физическо въздействие. Вторият — Само красив интериор. — оставя този риск: Две различно осветени снимки се монтират като доказано отслабване. В работна ситуация поправката е: Изключи сравнението; замени го с действителен процес, условия и проверим цитат само при основание. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Две различно осветени снимки се монтират като доказано отслабване. Как продължаваш?","options":[{"id":"a","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"b","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"c","label":"Изключи сравнението; замени го с действителен процес, условия и проверим цитат само при основание."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Изключи сравнението; замени го с действителен процес, условия и проверим цитат само при основание.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Зрителят разбира услугата и следващото действие; няма внушено медицинско или гарантирано физическо въздействие. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Две различно осветени снимки се монтират като доказано отслабване. В работна ситуация поправката е: Изключи сравнението; замени го с действителен процес, условия и проверим цитат само при основание. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s2","text":"Направи кадри, които описват услугата, вместо да обещават лечение."},{"id":"s1","text":"Избери една задача: първо посещение, записване или ориентация."},{"id":"s4","text":"Тествай дали зрител без контекст разбира какво следва."},{"id":"s3","text":"Провери участниците, безопасността и условията за резервация."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Избери една задача: първо посещение, записване или ориентация.\n2. Направи кадри, които описват услугата, вместо да обещават лечение.\n3. Провери участниците, безопасността и условията за резервация.\n4. Тествай дали зрител без контекст разбира какво следва.\n\nПреди окончателното предаване потвърди: Зрителят разбира услугата и следващото действие; няма внушено медицинско или гарантирано физическо въздействие. Ако разместиш проверката след предаването, остава този риск: Две различно осветени снимки се монтират като доказано отслабване."},"scoring":{"mode":"exact_order"}},{"position":14,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Покажи какво реално получава посетителят: посрещане, помещение, протокол на срещата, чистота и реална възможност за записване. Не превръщай промяна в осветлението или стойката в доказателство за здравен резултат. При фитнес показвай техника със съгласуван треньор, безопасна дистанция и вариации за начинаещи; клиентът проверява професионалните и рекламните твърдения.","Изключи сравнението; замени го с действителен процес, условия и проверим цитат само при основание.","Зрителят разбира услугата и следващото действие; няма внушено медицинско или гарантирано физическо въздействие."],"nextStep":"Напиши 30-секунден план за студио с 5 кадъра, ясна граница на обещанието и проверка на безопасността на упражнението."},"points":1,"required":true}]},{"module_id":"s02-m13","lesson_id":"pv13-07","title":"Скицирай какво би снимал за строителна фирма/автосервиз","subtitle":"Клиентски бриф, изпълним бюджет и професионално предаване","objective":"Площадката и хората са одобрени; зрителят вижда процес и проверка без опасни указания или чужди данни.","hook":"Сервизът иска „истинска работа“, но камерата застава до работещ подемник и вижда регистрационен номер.","estimated_minutes":40,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Площадката и хората са одобрени; зрителят вижда процес и проверка без опасни указания или чужди данни."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Сервизът иска „истинска работа“, но камерата застава до работещ подемник и вижда регистрационен номер."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Индустриалният сюжет започва със зона за снимки и безопасност, после с процес, който клиентът може да обясни вярно. Не инструктирай зрителя да повтаря опасни действия само защото кадърът изглежда впечатляващ. Скрий клиентски данни и имоти, които не са разрешени. За строителна фирма покажи етап, контрол и реален резултат, без да представяш един обект като универсална гаранция."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Дръж отделно допускане, потвърден факт и обещание към клиента. Сверявай разходите и часовете с действителния обхват; примерните суми в урока не са тарифа. За договор, данъци, професионална реклама или лични данни провери приложимите правила и потърси компетентен преглед преди реална употреба. Не публикувай човек, музика, чужд продукт или резултат без проверен обхват на правото.\n\nЗа тази задача: Премести снимачната точка, организирай безопасна демонстрация и прегледай всеки кадър за идентификатори."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Уговори отговорник по безопасност и кои зони са допустими.\n2. Избери три доказателствени кадъра: проблем, работа, проверка.\n3. Провери видими номера, документи, лица, брандове и възможни опасни действия.\n4. Изгледай export-а със собственика и отбележи коя процедура не трябва да се имитира.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Автосервиз снима клиентски автомобил само след отделно разрешение; номерът не се вижда, техникът обяснява диагностиката с изключено оборудване, а финалният кадър показва документ за извършена проверка без лични данни.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Снимаш ефектен кадър в забранена зона и разкриваш номера на колата."},"after":{"label":"Как го поправяш","text":"Премести снимачната точка, организирай безопасна демонстрация и прегледай всеки кадър за идентификатори."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Снимаш ефектен кадър в забранена зона и разкриваш номера на колата.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Уговори отговорник по безопасност и кои зони са допустими. След него: Провери видими номера, документи, лица, брандове и възможни опасни действия.\n\nКорекция: Премести снимачната точка, организирай безопасна демонстрация и прегледай всеки кадър за идентификатори.\n\nНови данни, които ще приемеш за успешна поправка: Площадката и хората са одобрени; зрителят вижда процес и проверка без опасни указания или чужди данни. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Направи план за сервиз или строителен обект: зони, отговорник, 6 кадъра, списък на скриваните данни и доказателство за крайния резултат.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Площадката и хората са одобрени; зрителят вижда процес и проверка без опасни указания или чужди данни.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Автосервиз снима клиентски автомобил само след отделно разрешение; номерът не се вижда, техникът обяснява диагностиката с изключено оборудване, а финалният кадър показва документ за извършена проверка без лични данни.\n\nДоставка: Направи план за сервиз или строителен обект: зони, отговорник, 6 кадъра, списък на скриваните данни и доказателство за крайния резултат.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Площадката и хората са одобрени; зрителят вижда процес и проверка без опасни указания или чужди данни."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Проверен първоизточник","content":{"body":"EDPB — насоки за обработване на лични данни чрез видео: https://www.edpb.europa.eu/documents/guideline/guidelines-32019-on-processing-of-personal-data-through-video-devices_en\nПровери текущата версия на функцията преди да повториш стъпките."},"points":0,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Какво предхожда първия кадър?","options":[{"id":"a","label":"Избор на LUT."},{"id":"b","label":"Разрешени зони, безопасност и отговорник."},{"id":"c","label":"Финален CTA."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Разрешени зони, безопасност и отговорник.\n\nПървият слаб ход — Избор на LUT. — пропуска тази проверка: Площадката и хората са одобрени; зрителят вижда процес и проверка без опасни указания или чужди данни. Вторият — Финален CTA. — оставя този риск: Снимаш ефектен кадър в забранена зона и разкриваш номера на колата. В работна ситуация поправката е: Премести снимачната точка, организирай безопасна демонстрация и прегледай всеки кадър за идентификатори. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"В кадъра има номер на чужда кола. Какво правиш?","options":[{"id":"a","label":"Добавяш emoji отгоре без да провериш export-а."},{"id":"b","label":"Спираш употребата му и правиш кадър без идентификатора или разрешена редакция."},{"id":"c","label":"Качваш го само като story."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Спираш употребата му и правиш кадър без идентификатора или разрешена редакция.\n\nПървият слаб ход — Качваш го само като story. — пропуска тази проверка: Площадката и хората са одобрени; зрителят вижда процес и проверка без опасни указания или чужди данни. Вторият — Добавяш emoji отгоре без да провериш export-а. — оставя този риск: Снимаш ефектен кадър в забранена зона и разкриваш номера на колата. В работна ситуация поправката е: Премести снимачната точка, организирай безопасна демонстрация и прегледай всеки кадър за идентификатори. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Какъв резултат може да покажеш?","options":[{"id":"a","label":"Проверен етап от реална работа и неговата граница."},{"id":"b","label":"Произволно stock изображение."},{"id":"c","label":"Гаранция за всяка повреда."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Проверен етап от реална работа и неговата граница.\n\nПървият слаб ход — Гаранция за всяка повреда. — пропуска тази проверка: Площадката и хората са одобрени; зрителят вижда процес и проверка без опасни указания или чужди данни. Вторият — Произволно stock изображение. — оставя този риск: Снимаш ефектен кадър в забранена зона и разкриваш номера на колата. В работна ситуация поправката е: Премести снимачната точка, организирай безопасна демонстрация и прегледай всеки кадър за идентификатори. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Снимаш ефектен кадър в забранена зона и разкриваш номера на колата. Как продължаваш?","options":[{"id":"a","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"b","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"c","label":"Премести снимачната точка, организирай безопасна демонстрация и прегледай всеки кадър за идентификатори."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Премести снимачната точка, организирай безопасна демонстрация и прегледай всеки кадър за идентификатори.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Площадката и хората са одобрени; зрителят вижда процес и проверка без опасни указания или чужди данни. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Снимаш ефектен кадър в забранена зона и разкриваш номера на колата. В работна ситуация поправката е: Премести снимачната точка, организирай безопасна демонстрация и прегледай всеки кадър за идентификатори. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s4","text":"Изгледай export-а със собственика и отбележи коя процедура не трябва да се имитира."},{"id":"s1","text":"Уговори отговорник по безопасност и кои зони са допустими."},{"id":"s2","text":"Избери три доказателствени кадъра: проблем, работа, проверка."},{"id":"s3","text":"Провери видими номера, документи, лица, брандове и възможни опасни действия."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Уговори отговорник по безопасност и кои зони са допустими.\n2. Избери три доказателствени кадъра: проблем, работа, проверка.\n3. Провери видими номера, документи, лица, брандове и възможни опасни действия.\n4. Изгледай export-а със собственика и отбележи коя процедура не трябва да се имитира.\n\nПреди окончателното предаване потвърди: Площадката и хората са одобрени; зрителят вижда процес и проверка без опасни указания или чужди данни. Ако разместиш проверката след предаването, остава този риск: Снимаш ефектен кадър в забранена зона и разкриваш номера на колата."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Индустриалният сюжет започва със зона за снимки и безопасност, после с процес, който клиентът може да обясни вярно. Не инструктирай зрителя да повтаря опасни действия само защото кадърът изглежда впечатляващ. Скрий клиентски данни и имоти, които не са разрешени. За строителна фирма покажи етап, контрол и реален резултат, без да представяш един обект като универсална гаранция.","Премести снимачната точка, организирай безопасна демонстрация и прегледай всеки кадър за идентификатори.","Площадката и хората са одобрени; зрителят вижда процес и проверка без опасни указания или чужди данни."],"nextStep":"Направи план за сервиз или строителен обект: зони, отговорник, 6 кадъра, списък на скриваните данни и доказателство за крайния резултат."},"points":1,"required":true}]},{"module_id":"s02-m13","lesson_id":"pv13-08","title":"Скицирай какво би снимал за инфлуенсър/личен бранд","subtitle":"Клиентски бриф, изпълним бюджет и професионално предаване","objective":"Търговската връзка е ясна, фактите са проверени, а ползването на образа и файла има определени граници.","hook":"Инфлуенсър казва „личен избор“, но продуктът е платена интеграция и марката иска клипът да остане без обозначение.","estimated_minutes":38,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Търговската връзка е ясна, фактите са проверени, а ползването на образа и файла има определени граници."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Инфлуенсър казва „личен избор“, но продуктът е платена интеграция и марката иска клипът да остане без обозначение."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Личният бранд се гради от наблюдавана позиция, конкретен опит и честно отношение към спонсорството. Напиши кое е твой опит и кое е твърдение на рекламодателя. Провери факти, право на повторно използване на образа, одобрителен процес и ясно обозначение на търговското съдържание според канала и приложимите правила. Не обещавай продажби от броя последователи."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Дръж отделно допускане, потвърден факт и обещание към клиента. Сверявай разходите и часовете с действителния обхват; примерните суми в урока не са тарифа. За договор, данъци, професионална реклама или лични данни провери приложимите правила и потърси компетентен преглед преди реална употреба. Не публикувай човек, музика, чужд продукт или резултат без проверен обхват на правото.\n\nЗа тази задача: Постави видимо и разбираемо обозначение и редактирай твърденията до проверим личен опит и продуктови факти."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Избери реална ситуация и едно лично доказателство.\n2. Отдели личния разказ от продуктови твърдения и редакционни ограничения.\n3. Уточни права за органично и платено повторно използване, срок и обозначение.\n4. Предай сценарий за одобрение без право на скрита подмяна на твърдения.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Създател показва как действително използва раница на път. Видео за платено партньорство го казва ясно, посочва проверения размер и не обещава „водоустойчива“ без технически източник.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Маркираш реклама само в края, а във видеото говориш сякаш е независим преглед."},"after":{"label":"Как го поправяш","text":"Постави видимо и разбираемо обозначение и редактирай твърденията до проверим личен опит и продуктови факти."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Маркираш реклама само в края, а във видеото говориш сякаш е независим преглед.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Избери реална ситуация и едно лично доказателство. След него: Уточни права за органично и платено повторно използване, срок и обозначение.\n\nКорекция: Постави видимо и разбираемо обозначение и редактирай твърденията до проверим личен опит и продуктови факти.\n\nНови данни, които ще приемеш за успешна поправка: Търговската връзка е ясна, фактите са проверени, а ползването на образа и файла има определени граници. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Напиши кратък бриф за личен бранд и партньор: собствен опит, две доказателства, спорни твърдения, права, обозначение и преглед.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Търговската връзка е ясна, фактите са проверени, а ползването на образа и файла има определени граници.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Създател показва как действително използва раница на път. Видео за платено партньорство го казва ясно, посочва проверения размер и не обещава „водоустойчива“ без технически източник.\n\nДоставка: Напиши кратък бриф за личен бранд и партньор: собствен опит, две доказателства, спорни твърдения, права, обозначение и преглед.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Търговската връзка е ясна, фактите са проверени, а ползването на образа и файла има определени граници."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Проверен първоизточник","content":{"body":"Европейска комисия — Influencer Legal Hub: https://commission.europa.eu/topics/consumers/consumer-rights-and-complaints/influencer-legal-hub_en\nПровери текущата версия на функцията преди да повториш стъпките."},"points":0,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Кое е задължително при платено партньорство?","options":[{"id":"a","label":"Ясно обозначение и проверени твърдения."},{"id":"b","label":"Само hashtag в края."},{"id":"c","label":"Представяне като независим избор."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Ясно обозначение и проверени твърдения.\n\nПървият слаб ход — Само hashtag в края. — пропуска тази проверка: Търговската връзка е ясна, фактите са проверени, а ползването на образа и файла има определени граници. Вторият — Представяне като независим избор. — оставя този риск: Маркираш реклама само в края, а във видеото говориш сякаш е независим преглед. В работна ситуация поправката е: Постави видимо и разбираемо обозначение и редактирай твърденията до проверим личен опит и продуктови факти. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Клиентът иска да пусне клипа и като платена реклама за година. Какво правиш?","options":[{"id":"a","label":"Приемаш, че едно story дава всички права."},{"id":"b","label":"Уточняваш отделно правата, срока и възнаграждението преди съгласие."},{"id":"c","label":"Скриваш спонсорството."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Уточняваш отделно правата, срока и възнаграждението преди съгласие.\n\nПървият слаб ход — Приемаш, че едно story дава всички права. — пропуска тази проверка: Търговската връзка е ясна, фактите са проверени, а ползването на образа и файла има определени граници. Вторият — Скриваш спонсорството. — оставя този риск: Маркираш реклама само в края, а във видеото говориш сякаш е независим преглед. В работна ситуация поправката е: Постави видимо и разбираемо обозначение и редактирай твърденията до проверим личен опит и продуктови факти. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Кое измерваш реалистично?","options":[{"id":"a","label":"Предсказан вирусен ефект."},{"id":"b","label":"Договореното действие и качествени сигнали, без гаранция за продажби."},{"id":"c","label":"Само брой последователи."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Договореното действие и качествени сигнали, без гаранция за продажби.\n\nПървият слаб ход — Само брой последователи. — пропуска тази проверка: Търговската връзка е ясна, фактите са проверени, а ползването на образа и файла има определени граници. Вторият — Предсказан вирусен ефект. — оставя този риск: Маркираш реклама само в края, а във видеото говориш сякаш е независим преглед. В работна ситуация поправката е: Постави видимо и разбираемо обозначение и редактирай твърденията до проверим личен опит и продуктови факти. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Маркираш реклама само в края, а във видеото говориш сякаш е независим преглед. Как продължаваш?","options":[{"id":"a","label":"Постави видимо и разбираемо обозначение и редактирай твърденията до проверим личен опит и продуктови факти."},{"id":"b","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"c","label":"Продължаваш без проверка и наричаш тази версия окончателна."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Постави видимо и разбираемо обозначение и редактирай твърденията до проверим личен опит и продуктови факти.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Търговската връзка е ясна, фактите са проверени, а ползването на образа и файла има определени граници. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Маркираш реклама само в края, а във видеото говориш сякаш е независим преглед. В работна ситуация поправката е: Постави видимо и разбираемо обозначение и редактирай твърденията до проверим личен опит и продуктови факти. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s4","text":"Предай сценарий за одобрение без право на скрита подмяна на твърдения."},{"id":"s3","text":"Уточни права за органично и платено повторно използване, срок и обозначение."},{"id":"s2","text":"Отдели личния разказ от продуктови твърдения и редакционни ограничения."},{"id":"s1","text":"Избери реална ситуация и едно лично доказателство."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Избери реална ситуация и едно лично доказателство.\n2. Отдели личния разказ от продуктови твърдения и редакционни ограничения.\n3. Уточни права за органично и платено повторно използване, срок и обозначение.\n4. Предай сценарий за одобрение без право на скрита подмяна на твърдения.\n\nПреди окончателното предаване потвърди: Търговската връзка е ясна, фактите са проверени, а ползването на образа и файла има определени граници. Ако разместиш проверката след предаването, остава този риск: Маркираш реклама само в края, а във видеото говориш сякаш е независим преглед."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Личният бранд се гради от наблюдавана позиция, конкретен опит и честно отношение към спонсорството. Напиши кое е твой опит и кое е твърдение на рекламодателя. Провери факти, право на повторно използване на образа, одобрителен процес и ясно обозначение на търговското съдържание според канала и приложимите правила. Не обещавай продажби от броя последователи.","Постави видимо и разбираемо обозначение и редактирай твърденията до проверим личен опит и продуктови факти.","Търговската връзка е ясна, фактите са проверени, а ползването на образа и файла има определени граници."],"nextStep":"Напиши кратък бриф за личен бранд и партньор: собствен опит, две доказателства, спорни твърдения, права, обозначение и преглед."},"points":1,"required":true}]},{"module_id":"s02-m13","lesson_id":"pv13-09","title":"Провери какви права/лицензи ти трябват за конкретен проект","subtitle":"Клиентски бриф, изпълним бюджет и професионално предаване","objective":"Всеки използван елемент има проследим източник и проверен обхват за действителния канал; неизвестните не влизат в export-а.","hook":"Монтажът е готов, но музиката е от личен абонамент, актьорът не е одобрил реклама и stock файлът допуска само редакционна употреба.","estimated_minutes":40,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Всеки използван елемент има проследим източник и проверен обхват за действителния канал; неизвестните не влизат в export-а."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Монтажът е готов, но музиката е от личен абонамент, актьорът не е одобрил реклама и stock файлът допуска само редакционна употреба."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Правата са матрица по актив, носител, територия, срок и начин на използване. Разрешение за снимане, авторско право върху музика и визуални елементи, права върху образа и обработване на лични данни са различни въпроси. Не използвай израза „free to use“ без условия; пази лиценз, версия, платец и ограничения. При правна несигурност спри съответния актив и искай преглед от специалист."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Дръж отделно допускане, потвърден факт и обещание към клиента. Сверявай разходите и часовете с действителния обхват; примерните суми в урока не са тарифа. За договор, данъци, професионална реклама или лични данни провери приложимите правила и потърси компетентен преглед преди реална употреба. Не публикувай човек, музика, чужд продукт или резултат без проверен обхват на правото.\n\nЗа тази задача: Провери условията за конкретния носител и срок; замени актива, ако няма доказуемо право."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Извади всички външни активи и разпознаваеми хора от timeline-а.\n2. За всеки опиши източник, право, обхват, срок и документ.\n3. Сравни с планираните канали, платена реклама и бъдещи адаптации.\n4. Замени или спри непокритото и архивирай доказателствата с версията.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"За клип на ресторант се ползва собствен звук, лицензирана музика за платената кампания и писмено уредена употреба на образа на участващия готвач. Случаен гост отпада от кадъра.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"„Има го в интернет“ се записва като основание за употреба."},"after":{"label":"Как го поправяш","text":"Провери условията за конкретния носител и срок; замени актива, ако няма доказуемо право."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: „Има го в интернет“ се записва като основание за употреба.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Извади всички външни активи и разпознаваеми хора от timeline-а. След него: Сравни с планираните канали, платена реклама и бъдещи адаптации.\n\nКорекция: Провери условията за конкретния носител и срок; замени актива, ако няма доказуемо право.\n\nНови данни, които ще приемеш за успешна поправка: Всеки използван елемент има проследим източник и проверен обхват за действителния канал; неизвестните не влизат в export-а. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Направи таблица с музика, шрифт, stock, лице, локация и клиентско лого за избран проект; отбележи липсите и резервите.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Всеки използван елемент има проследим източник и проверен обхват за действителния канал; неизвестните не влизат в export-а.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: За клип на ресторант се ползва собствен звук, лицензирана музика за платената кампания и писмено уредена употреба на образа на участващия готвач. Случаен гост отпада от кадъра.\n\nДоставка: Направи таблица с музика, шрифт, stock, лице, локация и клиентско лого за избран проект; отбележи липсите и резервите.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Всеки използван елемент има проследим източник и проверен обхват за действителния канал; неизвестните не влизат в export-а."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Проверен първоизточник","content":{"body":"Your Europe — авторски права и лицензиране: https://europa.eu/youreurope/business/growing/protecting-intellectual-property/copyright/index_en.htm\nYour Europe — лицензиране и прехвърляне на права: https://europa.eu/youreurope/business/growing/protecting-intellectual-property/licensing-selling/index_en.htm\nEDPB — насоки за обработване на лични данни чрез видео: https://www.edpb.europa.eu/documents/guideline/guidelines-32019-on-processing-of-personal-data-through-video-devices_en\nПровери текущата версия на функцията преди да повториш стъпките."},"points":0,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Кое е отделен въпрос от авторския лиценз за музика?","options":[{"id":"a","label":"Броят кадри."},{"id":"b","label":"Цветът на таймлайна."},{"id":"c","label":"Основанието за използване на разпознаваемо лице в реклама."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Основанието за използване на разпознаваемо лице в реклама.\n\nПървият слаб ход — Цветът на таймлайна. — пропуска тази проверка: Всеки използван елемент има проследим източник и проверен обхват за действителния канал; неизвестните не влизат в export-а. Вторият — Броят кадри. — оставя този риск: „Има го в интернет“ се записва като основание за употреба. В работна ситуация поправката е: Провери условията за конкретния носител и срок; замени актива, ако няма доказуемо право. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Stock лицензът е само редакционен, а клипът е реклама. Какво правиш?","options":[{"id":"a","label":"Не използваш файла, докато не осигуриш подходящо право."},{"id":"b","label":"Преименуваш файла."},{"id":"c","label":"Публикуваш от личен акаунт."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Не използваш файла, докато не осигуриш подходящо право.\n\nПървият слаб ход — Преименуваш файла. — пропуска тази проверка: Всеки използван елемент има проследим източник и проверен обхват за действителния канал; неизвестните не влизат в export-а. Вторият — Публикуваш от личен акаунт. — оставя този риск: „Има го в интернет“ се записва като основание за употреба. В работна ситуация поправката е: Провери условията за конкретния носител и срок; замени актива, ако няма доказуемо право. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Какво пазиш за предаването?","options":[{"id":"a","label":"Само MP4."},{"id":"b","label":"Матрица на активите, условия и документи, съпоставени с каналите."},{"id":"c","label":"Снимка на началния екран."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Матрица на активите, условия и документи, съпоставени с каналите.\n\nПървият слаб ход — Само MP4. — пропуска тази проверка: Всеки използван елемент има проследим източник и проверен обхват за действителния канал; неизвестните не влизат в export-а. Вторият — Снимка на началния екран. — оставя този риск: „Има го в интернет“ се записва като основание за употреба. В работна ситуация поправката е: Провери условията за конкретния носител и срок; замени актива, ако няма доказуемо право. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: „Има го в интернет“ се записва като основание за употреба. Как продължаваш?","options":[{"id":"a","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"b","label":"Провери условията за конкретния носител и срок; замени актива, ако няма доказуемо право."},{"id":"c","label":"Продължаваш без проверка и наричаш тази версия окончателна."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Провери условията за конкретния носител и срок; замени актива, ако няма доказуемо право.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Всеки използван елемент има проследим източник и проверен обхват за действителния канал; неизвестните не влизат в export-а. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: „Има го в интернет“ се записва като основание за употреба. В работна ситуация поправката е: Провери условията за конкретния носител и срок; замени актива, ако няма доказуемо право. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s2","text":"За всеки опиши източник, право, обхват, срок и документ."},{"id":"s3","text":"Сравни с планираните канали, платена реклама и бъдещи адаптации."},{"id":"s4","text":"Замени или спри непокритото и архивирай доказателствата с версията."},{"id":"s1","text":"Извади всички външни активи и разпознаваеми хора от timeline-а."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Извади всички външни активи и разпознаваеми хора от timeline-а.\n2. За всеки опиши източник, право, обхват, срок и документ.\n3. Сравни с планираните канали, платена реклама и бъдещи адаптации.\n4. Замени или спри непокритото и архивирай доказателствата с версията.\n\nПреди окончателното предаване потвърди: Всеки използван елемент има проследим източник и проверен обхват за действителния канал; неизвестните не влизат в export-а. Ако разместиш проверката след предаването, остава този риск: „Има го в интернет“ се записва като основание за употреба."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Правата са матрица по актив, носител, територия, срок и начин на използване. Разрешение за снимане, авторско право върху музика и визуални елементи, права върху образа и обработване на лични данни са различни въпроси. Не използвай израза „free to use“ без условия; пази лиценз, версия, платец и ограничения. При правна несигурност спри съответния актив и искай преглед от специалист.","Провери условията за конкретния носител и срок; замени актива, ако няма доказуемо право.","Всеки използван елемент има проследим източник и проверен обхват за действителния канал; неизвестните не влизат в export-а."],"nextStep":"Направи таблица с музика, шрифт, stock, лице, локация и клиентско лого за избран проект; отбележи липсите и резервите."},"points":1,"required":true}]},{"module_id":"s02-m13","lesson_id":"pv13-10","title":"Напиши стъпките от \"умея да снимам\" до \"имам първи клиент\"","subtitle":"Клиентски бриф, изпълним бюджет и професионално предаване","objective":"Има наблюдение, полезен резултат, реалистичен обхват и следваща стъпка; няма измислени успехи.","hook":"Снимаш добре, но изпращаш 50 еднакви съобщения „правя видеа“ и никой не отговаря.","estimated_minutes":36,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Има наблюдение, полезен резултат, реалистичен обхват и следваща стъпка; няма измислени успехи."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Снимаш добре, но изпращаш 50 еднакви съобщения „правя видеа“ и никой не отговаря."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Първият клиент идва от наблюдаван проблем и малка изпълнима оферта. Избери ниша, прегледай публичните материали на три бизнеса и формулирай конкретна идея с обхват. Не твърди, че си работил за тях, не ползвай чужди активи като свое портфолио и уважи отказа."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Дръж отделно допускане, потвърден факт и обещание към клиента. Сверявай разходите и часовете с действителния обхват; примерните суми в урока не са тарифа. За договор, данъци, професионална реклама или лични данни провери приложимите правила и потърси компетентен преглед преди реална употреба. Не публикувай човек, музика, чужд продукт или резултат без проверен обхват на правото.\n\nЗа тази задача: Замени обещанието с конкретна задача и разговор за приоритетите на бизнеса."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Избери три бизнеса с видима видео задача.\n2. За всеки запиши наблюдение, идея и въпрос без обещание за продажби.\n3. Подготви разрешен пример, обхват и срок.\n4. При уместен контакт изпрати персонално предложение и отбележи действителния отговор.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Пекарна има страница за торти без видео за размер. Предлагаш един демонстрационен клип с два формата; уточняваш достъп, снимки и одобрение.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Продаваш „вирусен клип“ без продукт, достъп или бюджет."},"after":{"label":"Как го поправяш","text":"Замени обещанието с конкретна задача и разговор за приоритетите на бизнеса."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Продаваш „вирусен клип“ без продукт, достъп или бюджет.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Избери три бизнеса с видима видео задача. След него: Подготви разрешен пример, обхват и срок.\n\nКорекция: Замени обещанието с конкретна задача и разговор за приоритетите на бизнеса.\n\nНови данни, които ще приемеш за успешна поправка: Има наблюдение, полезен резултат, реалистичен обхват и следваща стъпка; няма измислени успехи. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Напиши три различни предложения по публично наблюдаван проблем и един уважителен follow-up за избран контакт.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Има наблюдение, полезен резултат, реалистичен обхват и следваща стъпка; няма измислени успехи.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Пекарна има страница за торти без видео за размер. Предлагаш един демонстрационен клип с два формата; уточняваш достъп, снимки и одобрение.\n\nДоставка: Напиши три различни предложения по публично наблюдаван проблем и един уважителен follow-up за избран контакт.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Има наблюдение, полезен резултат, реалистичен обхват и следваща стъпка; няма измислени успехи."},"points":1,"required":false},{"position":11,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Кое отваря работен разговор?","options":[{"id":"a","label":"Масово „правя съдържание“."},{"id":"b","label":"Обещание за милион гледания."},{"id":"c","label":"Конкретна задача и въпрос за приоритетите."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Конкретна задача и въпрос за приоритетите.\n\nПървият слаб ход — Масово „правя съдържание“. — пропуска тази проверка: Има наблюдение, полезен резултат, реалистичен обхват и следваща стъпка; няма измислени успехи. Вторият — Обещание за милион гледания. — оставя този риск: Продаваш „вирусен клип“ без продукт, достъп или бюджет. В работна ситуация поправката е: Замени обещанието с конкретна задача и разговор за приоритетите на бизнеса. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Бизнесът няма бюджет. Какво правиш?","options":[{"id":"a","label":"Пишеш му ежедневно."},{"id":"b","label":"Снимаш безплатно без граници."},{"id":"c","label":"Предлагаш по-малък платен обхват или приемаш отказа."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Предлагаш по-малък платен обхват или приемаш отказа.\n\nПървият слаб ход — Снимаш безплатно без граници. — пропуска тази проверка: Има наблюдение, полезен резултат, реалистичен обхват и следваща стъпка; няма измислени успехи. Вторият — Пишеш му ежедневно. — оставя този риск: Продаваш „вирусен клип“ без продукт, достъп или бюджет. В работна ситуация поправката е: Замени обещанието с конкретна задача и разговор за приоритетите на бизнеса. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Какъв е истинският сигнал за напредък?","options":[{"id":"a","label":"Отговор по предложението или уговорен разговор."},{"id":"b","label":"Само изпратени съобщения."},{"id":"c","label":"Размерът на портфолиото."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Отговор по предложението или уговорен разговор.\n\nПървият слаб ход — Само изпратени съобщения. — пропуска тази проверка: Има наблюдение, полезен резултат, реалистичен обхват и следваща стъпка; няма измислени успехи. Вторият — Размерът на портфолиото. — оставя този риск: Продаваш „вирусен клип“ без продукт, достъп или бюджет. В работна ситуация поправката е: Замени обещанието с конкретна задача и разговор за приоритетите на бизнеса. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Продаваш „вирусен клип“ без продукт, достъп или бюджет. Как продължаваш?","options":[{"id":"a","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"b","label":"Замени обещанието с конкретна задача и разговор за приоритетите на бизнеса."},{"id":"c","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Замени обещанието с конкретна задача и разговор за приоритетите на бизнеса.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Има наблюдение, полезен резултат, реалистичен обхват и следваща стъпка; няма измислени успехи. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Продаваш „вирусен клип“ без продукт, достъп или бюджет. В работна ситуация поправката е: Замени обещанието с конкретна задача и разговор за приоритетите на бизнеса. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s2","text":"За всеки запиши наблюдение, идея и въпрос без обещание за продажби."},{"id":"s1","text":"Избери три бизнеса с видима видео задача."},{"id":"s4","text":"При уместен контакт изпрати персонално предложение и отбележи действителния отговор."},{"id":"s3","text":"Подготви разрешен пример, обхват и срок."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Избери три бизнеса с видима видео задача.\n2. За всеки запиши наблюдение, идея и въпрос без обещание за продажби.\n3. Подготви разрешен пример, обхват и срок.\n4. При уместен контакт изпрати персонално предложение и отбележи действителния отговор.\n\nПреди окончателното предаване потвърди: Има наблюдение, полезен резултат, реалистичен обхват и следваща стъпка; няма измислени успехи. Ако разместиш проверката след предаването, остава този риск: Продаваш „вирусен клип“ без продукт, достъп или бюджет."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Първият клиент идва от наблюдаван проблем и малка изпълнима оферта. Избери ниша, прегледай публичните материали на три бизнеса и формулирай конкретна идея с обхват. Не твърди, че си работил за тях, не ползвай чужди активи като свое портфолио и уважи отказа.","Замени обещанието с конкретна задача и разговор за приоритетите на бизнеса.","Има наблюдение, полезен резултат, реалистичен обхват и следваща стъпка; няма измислени успехи."],"nextStep":"Напиши три различни предложения по публично наблюдаван проблем и един уважителен follow-up за избран контакт."},"points":1,"required":true}]},{"module_id":"s02-m13","lesson_id":"pv13-11","title":"Начертай своя клиентски workflow от запитване до архив","subtitle":"Клиентски бриф, изпълним бюджет и професионално предаване","objective":"Колега проследява кой е одобрил коя версия и намира файловете и решенията без личен чат.","hook":"Клиентът праща бележки в чат, монтажистът работи по стар файл, а всички версии се казват final.","estimated_minutes":38,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Колега проследява кой е одобрил коя версия и намира файловете и решенията без личен чат."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Клиентът праща бележки в чат, монтажистът работи по стар файл, а всички версии се казват final."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Клиентският процес има вход и изход за всеки етап: запитване, бриф, оферта, условия, подготовка, снимки, чернова, консолидирани бележки, приемане, плащане и архив. Назови кой решава и коя версия е одобрена. Достъпът до суровини и срокът за съхранение се уточняват според проекта."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Дръж отделно допускане, потвърден факт и обещание към клиента. Сверявай разходите и часовете с действителния обхват; примерните суми в урока не са тарифа. За договор, данъци, професионална реклама или лични данни провери приложимите правила и потърси компетентен преглед преди реална употреба. Не публикувай човек, музика, чужд продукт или резултат без проверен обхват на правото.\n\nЗа тази задача: Въведи версия, дата, отговорник и писмено приемане; събери обратната връзка на едно място."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Начертай етапите и документа, който отключва всеки следващ.\n2. Определи един канал за бележки и имена на версиите.\n3. Запиши точка на приемане и процес за допълнителна работа.\n4. Планирай предаване, достъп и срок за архив.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Собственикът на магазин одобрява бриф, shot list и v2. Екипът пази източниците и лицензите в ограничена папка, а срокът за архив е записан в предаването.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Има три файла final.mp4 и никой не знае кой е публикуван."},"after":{"label":"Как го поправяш","text":"Въведи версия, дата, отговорник и писмено приемане; събери обратната връзка на едно място."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Има три файла final.mp4 и никой не знае кой е публикуван.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Начертай етапите и документа, който отключва всеки следващ. След него: Запиши точка на приемане и процес за допълнителна работа.\n\nКорекция: Въведи версия, дата, отговорник и писмено приемане; събери обратната връзка на едно място.\n\nНови данни, които ще приемеш за успешна поправка: Колега проследява кой е одобрил коя версия и намира файловете и решенията без личен чат. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Нарисувай workflow за двуседмичен проект с артефакт, собственик, срок и критерий за всеки етап.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Колега проследява кой е одобрил коя версия и намира файловете и решенията без личен чат.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Собственикът на магазин одобрява бриф, shot list и v2. Екипът пази източниците и лицензите в ограничена папка, а срокът за архив е записан в предаването.\n\nДоставка: Нарисувай workflow за двуседмичен проект с артефакт, собственик, срок и критерий за всеки етап.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Колега проследява кой е одобрил коя версия и намира файловете и решенията без личен чат."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Проверен първоизточник","content":{"body":"EDPB — насоки за обработване на лични данни чрез видео: https://www.edpb.europa.eu/documents/guideline/guidelines-32019-on-processing-of-personal-data-through-video-devices_en\nПровери текущата версия на функцията преди да повториш стъпките."},"points":0,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Какво отключва снимките?","options":[{"id":"a","label":"Одобрени бриф, условия и снимачен план."},{"id":"b","label":"Първият свободен час."},{"id":"c","label":"Само устно „давай“."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Одобрени бриф, условия и снимачен план.\n\nПървият слаб ход — Само устно „давай“. — пропуска тази проверка: Колега проследява кой е одобрил коя версия и намира файловете и решенията без личен чат. Вторият — Първият свободен час. — оставя този риск: Има три файла final.mp4 и никой не знае кой е публикуван. В работна ситуация поправката е: Въведи версия, дата, отговорник и писмено приемане; събери обратната връзка на едно място. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Двама мениджъри пращат противоречиви бележки. Какво правиш?","options":[{"id":"a","label":"Избираш на случаен принцип."},{"id":"b","label":"Правиш две версии без оценка."},{"id":"c","label":"Искаш консолидиран отговор от определеното лице."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Искаш консолидиран отговор от определеното лице.\n\nПървият слаб ход — Избираш на случаен принцип. — пропуска тази проверка: Колега проследява кой е одобрил коя версия и намира файловете и решенията без личен чат. Вторият — Правиш две версии без оценка. — оставя този риск: Има три файла final.mp4 и никой не знае кой е публикуван. В работна ситуация поправката е: Въведи версия, дата, отговорник и писмено приемане; събери обратната връзка на едно място. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Какво включва архивният план?","options":[{"id":"a","label":"Публичен линк без срок."},{"id":"b","label":"Само име final."},{"id":"c","label":"Договорен срок, достъп, версия и права за суровините."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Договорен срок, достъп, версия и права за суровините.\n\nПървият слаб ход — Само име final. — пропуска тази проверка: Колега проследява кой е одобрил коя версия и намира файловете и решенията без личен чат. Вторият — Публичен линк без срок. — оставя този риск: Има три файла final.mp4 и никой не знае кой е публикуван. В работна ситуация поправката е: Въведи версия, дата, отговорник и писмено приемане; събери обратната връзка на едно място. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Има три файла final.mp4 и никой не знае кой е публикуван. Как продължаваш?","options":[{"id":"a","label":"Въведи версия, дата, отговорник и писмено приемане; събери обратната връзка на едно място."},{"id":"b","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"c","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Въведи версия, дата, отговорник и писмено приемане; събери обратната връзка на едно място.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Колега проследява кой е одобрил коя версия и намира файловете и решенията без личен чат. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Има три файла final.mp4 и никой не знае кой е публикуван. В работна ситуация поправката е: Въведи версия, дата, отговорник и писмено приемане; събери обратната връзка на едно място. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s4","text":"Планирай предаване, достъп и срок за архив."},{"id":"s1","text":"Начертай етапите и документа, който отключва всеки следващ."},{"id":"s2","text":"Определи един канал за бележки и имена на версиите."},{"id":"s3","text":"Запиши точка на приемане и процес за допълнителна работа."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Начертай етапите и документа, който отключва всеки следващ.\n2. Определи един канал за бележки и имена на версиите.\n3. Запиши точка на приемане и процес за допълнителна работа.\n4. Планирай предаване, достъп и срок за архив.\n\nПреди окончателното предаване потвърди: Колега проследява кой е одобрил коя версия и намира файловете и решенията без личен чат. Ако разместиш проверката след предаването, остава този риск: Има три файла final.mp4 и никой не знае кой е публикуван."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Клиентският процес има вход и изход за всеки етап: запитване, бриф, оферта, условия, подготовка, снимки, чернова, консолидирани бележки, приемане, плащане и архив. Назови кой решава и коя версия е одобрена. Достъпът до суровини и срокът за съхранение се уточняват според проекта.","Въведи версия, дата, отговорник и писмено приемане; събери обратната връзка на едно място.","Колега проследява кой е одобрил коя версия и намира файловете и решенията без личен чат."],"nextStep":"Нарисувай workflow за двуседмичен проект с артефакт, собственик, срок и критерий за всеки етап."},"points":1,"required":true}]},{"module_id":"s02-m13","lesson_id":"pv13-12","title":"Изчисли цена за конкретна услуга по реален модел","subtitle":"Клиентски бриф, изпълним бюджет и професионално предаване","objective":"Друг човек възпроизвежда цената; разход, марж, данъци и обхват са отделни.","hook":"Конкурент иска 300 €, затова и ти пишеш 300 €, без да знаеш колко часа ще работиш.","estimated_minutes":42,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Друг човек възпроизвежда цената; разход, марж, данъци и обхват са отделни."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Конкурент иска 300 €, затова и ти пишеш 300 €, без да знаеш колко часа ще работиш."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Цена покрива труд, нефактурируемо време, режийни, външни разходи, риск и печалба. Пример: цел 2 400 € за месец при 80 фактурируеми часа дава основа 30 €/ч. При 12 часа и 90 € външни разходи основата е 450 €; цена за 20% марж върху продажната цена е 450 / 0,8 = 562,50 € преди приложимите данъци. Това е сметка по допускания, не универсална тарифа."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Дръж отделно допускане, потвърден факт и обещание към клиента. Сверявай разходите и часовете с действителния обхват; примерните суми в урока не са тарифа. За договор, данъци, професионална реклама или лични данни провери приложимите правила и потърси компетентен преглед преди реална употреба. Не публикувай човек, музика, чужд продукт или резултат без проверен обхват на правото.\n\nЗа тази задача: Запиши формулата цена = основа / (1 - марж) и провери кое влиза в основата."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Изчисли фактурируемите часове, не целия календар.\n2. Раздели месечната цел на тях и добави разходите по проекта.\n3. Изчисли цена по марж и сценарий с допълнителна ревизия.\n4. Провери обхвата и данъчните условия с компетентен специалист.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Два монтажа с 12 часа и 90 € лицензи имат основа 450 €. Още четири часа променят основата на 570 €, а същият марж изисква 712,50 €.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Бъркаш 20% надценка върху разхода с 20% марж върху продажната цена."},"after":{"label":"Как го поправяш","text":"Запиши формулата цена = основа / (1 - марж) и провери кое влиза в основата."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Бъркаш 20% надценка върху разхода с 20% марж върху продажната цена.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Изчисли фактурируемите часове, не целия календар. След него: Изчисли цена по марж и сценарий с допълнителна ревизия.\n\nКорекция: Запиши формулата цена = основа / (1 - марж) и провери кое влиза в основата.\n\nНови данни, които ще приемеш за успешна поправка: Друг човек възпроизвежда цената; разход, марж, данъци и обхват са отделни. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Сметни своя услуга с часове, режийни, разходи и два сценария за ревизии; покажи формулите.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Друг човек възпроизвежда цената; разход, марж, данъци и обхват са отделни.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Два монтажа с 12 часа и 90 € лицензи имат основа 450 €. Още четири часа променят основата на 570 €, а същият марж изисква 712,50 €.\n\nДоставка: Сметни своя услуга с часове, режийни, разходи и два сценария за ревизии; покажи формулите.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Друг човек възпроизвежда цената; разход, марж, данъци и обхват са отделни."},"points":1,"required":false},{"position":11,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Колко е цената при основа 450 € и 20% марж?","options":[{"id":"a","label":"450 €."},{"id":"b","label":"562,50 € преди приложимите данъци."},{"id":"c","label":"540 €."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: 562,50 € преди приложимите данъци.\n\nПървият слаб ход — 540 €. — пропуска тази проверка: Друг човек възпроизвежда цената; разход, марж, данъци и обхват са отделни. Вторият — 450 €. — оставя този риск: Бъркаш 20% надценка върху разхода с 20% марж върху продажната цена. В работна ситуация поправката е: Запиши формулата цена = основа / (1 - марж) и провери кое влиза в основата. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Имаш само 60 фактурируеми часа. Какво правиш?","options":[{"id":"a","label":"Преизчисляваш стойността на час и обхвата."},{"id":"b","label":"Изваждаш режийните."},{"id":"c","label":"Оставяш 30 € като закон."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Преизчисляваш стойността на час и обхвата.\n\nПървият слаб ход — Оставяш 30 € като закон. — пропуска тази проверка: Друг човек възпроизвежда цената; разход, марж, данъци и обхват са отделни. Вторият — Изваждаш режийните. — оставя този риск: Бъркаш 20% надценка върху разхода с 20% марж върху продажната цена. В работна ситуация поправката е: Запиши формулата цена = основа / (1 - марж) и провери кое влиза в основата. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Кое показва устойчивост?","options":[{"id":"a","label":"Копирана цена."},{"id":"b","label":"Само усещане за премиум."},{"id":"c","label":"Изрични допускания и тест при промяна на времето."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Изрични допускания и тест при промяна на времето.\n\nПървият слаб ход — Копирана цена. — пропуска тази проверка: Друг човек възпроизвежда цената; разход, марж, данъци и обхват са отделни. Вторият — Само усещане за премиум. — оставя този риск: Бъркаш 20% надценка върху разхода с 20% марж върху продажната цена. В работна ситуация поправката е: Запиши формулата цена = основа / (1 - марж) и провери кое влиза в основата. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Бъркаш 20% надценка върху разхода с 20% марж върху продажната цена. Как продължаваш?","options":[{"id":"a","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"b","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"c","label":"Запиши формулата цена = основа / (1 - марж) и провери кое влиза в основата."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Запиши формулата цена = основа / (1 - марж) и провери кое влиза в основата.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Друг човек възпроизвежда цената; разход, марж, данъци и обхват са отделни. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Бъркаш 20% надценка върху разхода с 20% марж върху продажната цена. В работна ситуация поправката е: Запиши формулата цена = основа / (1 - марж) и провери кое влиза в основата. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s4","text":"Провери обхвата и данъчните условия с компетентен специалист."},{"id":"s3","text":"Изчисли цена по марж и сценарий с допълнителна ревизия."},{"id":"s2","text":"Раздели месечната цел на тях и добави разходите по проекта."},{"id":"s1","text":"Изчисли фактурируемите часове, не целия календар."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Изчисли фактурируемите часове, не целия календар.\n2. Раздели месечната цел на тях и добави разходите по проекта.\n3. Изчисли цена по марж и сценарий с допълнителна ревизия.\n4. Провери обхвата и данъчните условия с компетентен специалист.\n\nПреди окончателното предаване потвърди: Друг човек възпроизвежда цената; разход, марж, данъци и обхват са отделни. Ако разместиш проверката след предаването, остава този риск: Бъркаш 20% надценка върху разхода с 20% марж върху продажната цена."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Цена покрива труд, нефактурируемо време, режийни, външни разходи, риск и печалба. Пример: цел 2 400 € за месец при 80 фактурируеми часа дава основа 30 €/ч. При 12 часа и 90 € външни разходи основата е 450 €; цена за 20% марж върху продажната цена е 450 / 0,8 = 562,50 € преди приложимите данъци. Това е сметка по допускания, не универсална тарифа.","Запиши формулата цена = основа / (1 - марж) и провери кое влиза в основата.","Друг човек възпроизвежда цената; разход, марж, данъци и обхват са отделни."],"nextStep":"Сметни своя услуга с часове, режийни, разходи и два сценария за ревизии; покажи формулите."},"points":1,"required":true}]},{"module_id":"s02-m13","lesson_id":"pv13-13","title":"Напиши оферта за конкретен потенциален клиент","subtitle":"Клиентски бриф, изпълним бюджет и професионално предаване","objective":"Клиентът може да каже какво получава, кога, за какви канали и при какви граници.","hook":"Две оферти имат еднаква цена, но едната включва снимки и два формата, другата само монтаж.","estimated_minutes":38,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Клиентът може да каже какво получава, кога, за какви канали и при какви граници."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Две оферти имат еднаква цена, но едната включва снимки и два формата, другата само монтаж."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Офертата превежда брифа в резултат: цел, файлове, формати, включена работа, ревизии, срок и зависимости, цена, плащания, права и изключения. Варианти имат смисъл, когато обхватът им действително е различен. Не крий съществен разход с „всичко включено“."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Дръж отделно допускане, потвърден факт и обещание към клиента. Сверявай разходите и часовете с действителния обхват; примерните суми в урока не са тарифа. За договор, данъци, професионална реклама или лични данни провери приложимите правила и потърси компетентен преглед преди реална употреба. Не публикувай човек, музика, чужд продукт или резултат без проверен обхват на правото.\n\nЗа тази задача: Прикачи обхвата и допусканията към цената преди приемане."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Повтори задачата с думи, които клиентът потвърждава.\n2. Опиши всеки файл с формат, дължина, канал и срок.\n3. Напиши включено, изключено, входни материали и одобрител.\n4. Свържи цена, плащания, права и валидност с тези условия.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Сервиз получава оферта за 1 клип 45 секунди и 2 вертикални версии, един снимачен ден и два кръга бележки. Дрон и втори адрес са отделни.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Пращаш „видео 900 €“ и месец по-късно спорите дали има втори снимачен ден."},"after":{"label":"Как го поправяш","text":"Прикачи обхвата и допусканията към цената преди приемане."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Пращаш „видео 900 €“ и месец по-късно спорите дали има втори снимачен ден.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Повтори задачата с думи, които клиентът потвърждава. След него: Напиши включено, изключено, входни материали и одобрител.\n\nКорекция: Прикачи обхвата и допусканията към цената преди приемане.\n\nНови данни, които ще приемеш за успешна поправка: Клиентът може да каже какво получава, кога, за какви канали и при какви граници. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Напиши едностранична оферта по конкретен бриф с файлове, версии, права, срок и допълнителна работа.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Клиентът може да каже какво получава, кога, за какви канали и при какви граници.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Сервиз получава оферта за 1 клип 45 секунди и 2 вертикални версии, един снимачен ден и два кръга бележки. Дрон и втори адрес са отделни.\n\nДоставка: Напиши едностранична оферта по конкретен бриф с файлове, версии, права, срок и допълнителна работа.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Клиентът може да каже какво получава, кога, за какви канали и при какви граници."},"points":1,"required":false},{"position":11,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Коя оферта е сравнима?","options":[{"id":"a","label":"Най-красивият PDF."},{"id":"b","label":"Тази с ясни доставими файлове, обхват и условия."},{"id":"c","label":"Само най-ниската цена."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Тази с ясни доставими файлове, обхват и условия.\n\nПървият слаб ход — Най-красивият PDF. — пропуска тази проверка: Клиентът може да каже какво получава, кога, за какви канали и при какви граници. Вторият — Само най-ниската цена. — оставя този риск: Пращаш „видео 900 €“ и месец по-късно спорите дали има втори снимачен ден. В работна ситуация поправката е: Прикачи обхвата и допусканията към цената преди приемане. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Искат втори адрес след приемане. Какво правиш?","options":[{"id":"a","label":"Махаш версия без да кажеш."},{"id":"b","label":"Оценяваш промяната и новия срок преди снимките."},{"id":"c","label":"Приемаш устно."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Оценяваш промяната и новия срок преди снимките.\n\nПървият слаб ход — Приемаш устно. — пропуска тази проверка: Клиентът може да каже какво получава, кога, за какви канали и при какви граници. Вторият — Махаш версия без да кажеш. — оставя този риск: Пращаш „видео 900 €“ и месец по-късно спорите дали има втори снимачен ден. В работна ситуация поправката е: Прикачи обхвата и допусканията към цената преди приемане. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Какво проверяваш преди изпращане?","options":[{"id":"a","label":"Съответствие между бриф, цена, срок и права."},{"id":"b","label":"Само логото."},{"id":"c","label":"Само правопис."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Съответствие между бриф, цена, срок и права.\n\nПървият слаб ход — Само правопис. — пропуска тази проверка: Клиентът може да каже какво получава, кога, за какви канали и при какви граници. Вторият — Само логото. — оставя този риск: Пращаш „видео 900 €“ и месец по-късно спорите дали има втори снимачен ден. В работна ситуация поправката е: Прикачи обхвата и допусканията към цената преди приемане. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Пращаш „видео 900 €“ и месец по-късно спорите дали има втори снимачен ден. Как продължаваш?","options":[{"id":"a","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"b","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"c","label":"Прикачи обхвата и допусканията към цената преди приемане."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Прикачи обхвата и допусканията към цената преди приемане.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Клиентът може да каже какво получава, кога, за какви канали и при какви граници. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Пращаш „видео 900 €“ и месец по-късно спорите дали има втори снимачен ден. В работна ситуация поправката е: Прикачи обхвата и допусканията към цената преди приемане. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s2","text":"Опиши всеки файл с формат, дължина, канал и срок."},{"id":"s3","text":"Напиши включено, изключено, входни материали и одобрител."},{"id":"s4","text":"Свържи цена, плащания, права и валидност с тези условия."},{"id":"s1","text":"Повтори задачата с думи, които клиентът потвърждава."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Повтори задачата с думи, които клиентът потвърждава.\n2. Опиши всеки файл с формат, дължина, канал и срок.\n3. Напиши включено, изключено, входни материали и одобрител.\n4. Свържи цена, плащания, права и валидност с тези условия.\n\nПреди окончателното предаване потвърди: Клиентът може да каже какво получава, кога, за какви канали и при какви граници. Ако разместиш проверката след предаването, остава този риск: Пращаш „видео 900 €“ и месец по-късно спорите дали има втори снимачен ден."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Офертата превежда брифа в резултат: цел, файлове, формати, включена работа, ревизии, срок и зависимости, цена, плащания, права и изключения. Варианти имат смисъл, когато обхватът им действително е различен. Не крий съществен разход с „всичко включено“.","Прикачи обхвата и допусканията към цената преди приемане.","Клиентът може да каже какво получава, кога, за какви канали и при какви граници."],"nextStep":"Напиши едностранична оферта по конкретен бриф с файлове, версии, права, срок и допълнителна работа."},"points":1,"required":true}]},{"module_id":"s02-m13","lesson_id":"pv13-14","title":"Подготви договор и условия за капаро","subtitle":"Клиентски бриф, изпълним бюджет и професионално предаване","objective":"Условията отразяват обхвата; непровереното е маркирано като въпрос, не като готова клауза.","hook":"Клиент иска капаро, но срокът започва преди брифът да е готов, а музикалният лиценз не покрива реклама.","estimated_minutes":42,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Условията отразяват обхвата; непровереното е маркирано като въпрос, не като готова клауза."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Клиент иска капаро, но срокът започва преди брифът да е готов, а музикалният лиценз не покрива реклама."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Подготви checklist за индивидуален договор, а не универсален правен образец: страни, предмет, приемане, етапи, аванс, промени, прекратяване, финални и сурови файлове, лицензи, лични данни и конфиденциалност. За начало на работа и резервиран ресурс посочи ясни условия. Правни и данъчни клаузи изискват преглед според юрисдикцията."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Дръж отделно допускане, потвърден факт и обещание към клиента. Сверявай разходите и часовете с действителния обхват; примерните суми в урока не са тарифа. За договор, данъци, професионална реклама или лични данни провери приложимите правила и потърси компетентен преглед преди реална употреба. Не публикувай човек, музика, чужд продукт или резултат без проверен обхват на правото.\n\nЗа тази задача: Направи индивидуален списък с въпроси и не обявявай непроверена клауза за приложим закон."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Извади реалните рискове от офертата.\n2. Запиши обхват, срок, плащане, одобрение и права.\n3. Добави условия за отмяна, промяна и забавен клиентски материал.\n4. Потърси компетентен правен и счетоводен преглед преди употреба.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Клиент резервира снимачен ден след одобрен бриф и уговорено плащане; условията казват как се пренасрочва и кои канали покрива музиката.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Копираш чужд договор и пишеш „капарото не се връща“ без преглед."},"after":{"label":"Как го поправяш","text":"Направи индивидуален списък с въпроси и не обявявай непроверена клауза за приложим закон."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Копираш чужд договор и пишеш „капарото не се връща“ без преглед.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Извади реалните рискове от офертата. След него: Добави условия за отмяна, промяна и забавен клиентски материал.\n\nКорекция: Направи индивидуален списък с въпроси и не обявявай непроверена клауза за приложим закон.\n\nНови данни, които ще приемеш за успешна поправка: Условията отразяват обхвата; непровереното е маркирано като въпрос, не като готова клауза. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Подготви 12 точки за договор по примерния проект и 3 въпроса към юрист или счетоводител.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Условията отразяват обхвата; непровереното е маркирано като въпрос, не като готова клауза.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Клиент резервира снимачен ден след одобрен бриф и уговорено плащане; условията казват как се пренасрочва и кои канали покрива музиката.\n\nДоставка: Подготви 12 точки за договор по примерния проект и 3 въпроса към юрист или счетоводител.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Условията отразяват обхвата; непровереното е маркирано като въпрос, не като готова клауза."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Проверен първоизточник","content":{"body":"Your Europe — лицензиране и прехвърляне на права: https://europa.eu/youreurope/business/growing/protecting-intellectual-property/licensing-selling/index_en.htm\nПровери текущата версия на функцията преди да повториш стъпките."},"points":0,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Какво предхожда резервирания снимачен ден?","options":[{"id":"a","label":"Потвърдени условия, бриф и ясно плащане."},{"id":"b","label":"Само чат."},{"id":"c","label":"Копиран шаблон."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Потвърдени условия, бриф и ясно плащане.\n\nПървият слаб ход — Само чат. — пропуска тази проверка: Условията отразяват обхвата; непровереното е маркирано като въпрос, не като готова клауза. Вторият — Копиран шаблон. — оставя този риск: Копираш чужд договор и пишеш „капарото не се връща“ без преглед. В работна ситуация поправката е: Направи индивидуален списък с въпроси и не обявявай непроверена клауза за приложим закон. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Искат всички суровини и неограничена употреба. Какво правиш?","options":[{"id":"a","label":"Приемаш, че MP4 включва всичко."},{"id":"b","label":"Уточняваш активи, права, срок и цена за преглед."},{"id":"c","label":"Игнорираш лицензите."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Уточняваш активи, права, срок и цена за преглед.\n\nПървият слаб ход — Приемаш, че MP4 включва всичко. — пропуска тази проверка: Условията отразяват обхвата; непровереното е маркирано като въпрос, не като готова клауза. Вторият — Игнорираш лицензите. — оставя този риск: Копираш чужд договор и пишеш „капарото не се връща“ без преглед. В работна ситуация поправката е: Направи индивидуален списък с въпроси и не обявявай непроверена клауза за приложим закон. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Кога checklist е за реален подпис?","options":[{"id":"a","label":"Когато има сложни думи."},{"id":"b","label":"След адаптация и компетентен правен/счетоводен преглед."},{"id":"c","label":"Когато е дълъг."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: След адаптация и компетентен правен/счетоводен преглед.\n\nПървият слаб ход — Когато е дълъг. — пропуска тази проверка: Условията отразяват обхвата; непровереното е маркирано като въпрос, не като готова клауза. Вторият — Когато има сложни думи. — оставя този риск: Копираш чужд договор и пишеш „капарото не се връща“ без преглед. В работна ситуация поправката е: Направи индивидуален списък с въпроси и не обявявай непроверена клауза за приложим закон. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Копираш чужд договор и пишеш „капарото не се връща“ без преглед. Как продължаваш?","options":[{"id":"a","label":"Направи индивидуален списък с въпроси и не обявявай непроверена клауза за приложим закон."},{"id":"b","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"c","label":"Продължаваш без проверка и наричаш тази версия окончателна."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Направи индивидуален списък с въпроси и не обявявай непроверена клауза за приложим закон.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Условията отразяват обхвата; непровереното е маркирано като въпрос, не като готова клауза. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Копираш чужд договор и пишеш „капарото не се връща“ без преглед. В работна ситуация поправката е: Направи индивидуален списък с въпроси и не обявявай непроверена клауза за приложим закон. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s2","text":"Запиши обхват, срок, плащане, одобрение и права."},{"id":"s1","text":"Извади реалните рискове от офертата."},{"id":"s4","text":"Потърси компетентен правен и счетоводен преглед преди употреба."},{"id":"s3","text":"Добави условия за отмяна, промяна и забавен клиентски материал."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Извади реалните рискове от офертата.\n2. Запиши обхват, срок, плащане, одобрение и права.\n3. Добави условия за отмяна, промяна и забавен клиентски материал.\n4. Потърси компетентен правен и счетоводен преглед преди употреба.\n\nПреди окончателното предаване потвърди: Условията отразяват обхвата; непровереното е маркирано като въпрос, не като готова клауза. Ако разместиш проверката след предаването, остава този риск: Копираш чужд договор и пишеш „капарото не се връща“ без преглед."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Подготви checklist за индивидуален договор, а не универсален правен образец: страни, предмет, приемане, етапи, аванс, промени, прекратяване, финални и сурови файлове, лицензи, лични данни и конфиденциалност. За начало на работа и резервиран ресурс посочи ясни условия. Правни и данъчни клаузи изискват преглед според юрисдикцията.","Направи индивидуален списък с въпроси и не обявявай непроверена клауза за приложим закон.","Условията отразяват обхвата; непровереното е маркирано като въпрос, не като готова клауза."],"nextStep":"Подготви 12 точки за договор по примерния проект и 3 въпроса към юрист или счетоводител."},"points":1,"required":true}]},{"module_id":"s02-m13","lesson_id":"pv13-15","title":"Определи политика за брой ревизии предварително","subtitle":"Клиентски бриф, изпълним бюджет и професионално предаване","objective":"Клиент и екип класифицират конкретна бележка по едни критерии и знаят следващия срок.","hook":"Четвъртата „малка промяна“ е нов сценарий, а офертата обещава „до пълно удовлетворение“.","estimated_minutes":36,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Клиент и екип класифицират конкретна бележка по едни критерии и знаят следващия срок."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Четвъртата „малка промяна“ е нов сценарий, а офертата обещава „до пълно удовлетворение“."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Ревизия е кръг консолидирани бележки по договорен обхват. Нова цел, формат или снимки са нова задача. Уточни брой кръгове, кой събира бележките, срок и оценка на промяната. Собствена техническа грешка не трябва да се прехвърля на клиента като платена ревизия."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Дръж отделно допускане, потвърден факт и обещание към клиента. Сверявай разходите и часовете с действителния обхват; примерните суми в урока не са тарифа. За договор, данъци, професионална реклама или лични данни провери приложимите правила и потърси компетентен преглед преди реална употреба. Не публикувай човек, музика, чужд продукт или резултат без проверен обхват на правото.\n\nЗа тази задача: Поправи собствената грешка; консолидирай останалото и оцени новата задача."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Покажи чернова с номер и дата.\n2. Вземи един списък с timecode от одобрителя.\n3. Раздели поправка на грешка, включена ревизия и нов обхват.\n4. Потвърди нова цена и срок преди допълнителна работа.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Грешно изписан модел от монтажиста се поправя. Искане за втори автомобил и нов CTA получава отделна оценка.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Броиш всяко съобщение като ревизия и спориш за своя сгрешен надпис."},"after":{"label":"Как го поправяш","text":"Поправи собствената грешка; консолидирай останалото и оцени новата задача."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Броиш всяко съобщение като ревизия и спориш за своя сгрешен надпис.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Покажи чернова с номер и дата. След него: Раздели поправка на грешка, включена ревизия и нов обхват.\n\nКорекция: Поправи собствената грешка; консолидирай останалото и оцени новата задача.\n\nНови данни, които ще приемеш за успешна поправка: Клиент и екип класифицират конкретна бележка по едни критерии и знаят следващия срок. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Напиши политика с два кръга, един одобрител и примери за включено и допълнително.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Клиент и екип класифицират конкретна бележка по едни критерии и знаят следващия срок.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Грешно изписан модел от монтажиста се поправя. Искане за втори автомобил и нов CTA получава отделна оценка.\n\nДоставка: Напиши политика с два кръга, един одобрител и примери за включено и допълнително.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Клиент и екип класифицират конкретна бележка по едни критерии и знаят следващия срок."},"points":1,"required":false},{"position":11,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Кое е поправка на изпълнителя?","options":[{"id":"a","label":"Нова публика."},{"id":"b","label":"Нов продукт."},{"id":"c","label":"Неточен надпис спрямо одобрения бриф."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Неточен надпис спрямо одобрения бриф.\n\nПървият слаб ход — Нов продукт. — пропуска тази проверка: Клиент и екип класифицират конкретна бележка по едни критерии и знаят следващия срок. Вторият — Нова публика. — оставя този риск: Броиш всяко съобщение като ревизия и спориш за своя сгрешен надпис. В работна ситуация поправката е: Поправи собствената грешка; консолидирай останалото и оцени новата задача. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Искат трети формат след приемане. Какво правиш?","options":[{"id":"a","label":"Оценяваш формат и срок преди работа."},{"id":"b","label":"Скриваш труда."},{"id":"c","label":"Отказваш всяка промяна."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Оценяваш формат и срок преди работа.\n\nПървият слаб ход — Скриваш труда. — пропуска тази проверка: Клиент и екип класифицират конкретна бележка по едни критерии и знаят следващия срок. Вторият — Отказваш всяка промяна. — оставя този риск: Броиш всяко съобщение като ревизия и спориш за своя сгрешен надпис. В работна ситуация поправката е: Поправи собствената грешка; консолидирай останалото и оцени новата задача. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Какво трябва да има бележката?","options":[{"id":"a","label":"Само emoji."},{"id":"b","label":"Версия, timecode и един консолидиран отговорник."},{"id":"c","label":"Много отделни чатове."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Версия, timecode и един консолидиран отговорник.\n\nПървият слаб ход — Само emoji. — пропуска тази проверка: Клиент и екип класифицират конкретна бележка по едни критерии и знаят следващия срок. Вторият — Много отделни чатове. — оставя този риск: Броиш всяко съобщение като ревизия и спориш за своя сгрешен надпис. В работна ситуация поправката е: Поправи собствената грешка; консолидирай останалото и оцени новата задача. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Броиш всяко съобщение като ревизия и спориш за своя сгрешен надпис. Как продължаваш?","options":[{"id":"a","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"b","label":"Поправи собствената грешка; консолидирай останалото и оцени новата задача."},{"id":"c","label":"Продължаваш без проверка и наричаш тази версия окончателна."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Поправи собствената грешка; консолидирай останалото и оцени новата задача.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Клиент и екип класифицират конкретна бележка по едни критерии и знаят следващия срок. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Броиш всяко съобщение като ревизия и спориш за своя сгрешен надпис. В работна ситуация поправката е: Поправи собствената грешка; консолидирай останалото и оцени новата задача. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s4","text":"Потвърди нова цена и срок преди допълнителна работа."},{"id":"s1","text":"Покажи чернова с номер и дата."},{"id":"s2","text":"Вземи един списък с timecode от одобрителя."},{"id":"s3","text":"Раздели поправка на грешка, включена ревизия и нов обхват."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Покажи чернова с номер и дата.\n2. Вземи един списък с timecode от одобрителя.\n3. Раздели поправка на грешка, включена ревизия и нов обхват.\n4. Потвърди нова цена и срок преди допълнителна работа.\n\nПреди окончателното предаване потвърди: Клиент и екип класифицират конкретна бележка по едни критерии и знаят следващия срок. Ако разместиш проверката след предаването, остава този риск: Броиш всяко съобщение като ревизия и спориш за своя сгрешен надпис."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Ревизия е кръг консолидирани бележки по договорен обхват. Нова цел, формат или снимки са нова задача. Уточни брой кръгове, кой събира бележките, срок и оценка на промяната. Собствена техническа грешка не трябва да се прехвърля на клиента като платена ревизия.","Поправи собствената грешка; консолидирай останалото и оцени новата задача.","Клиент и екип класифицират конкретна бележка по едни критерии и знаят следващия срок."],"nextStep":"Напиши политика с два кръга, един одобрител и примери за включено и допълнително."},"points":1,"required":true}]},{"module_id":"s02-m13","lesson_id":"pv13-16","title":"Реши дали предлагаш абонамент или проектна работа","subtitle":"Клиентски бриф, изпълним бюджет и професионално предаване","objective":"Изборът е мотивиран с честота и капацитет; и двата варианта имат ясни граници.","hook":"Клиент иска абонамент „колкото видеа се сетим“, но продуктовите снимки зависят от сезона.","estimated_minutes":36,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Изборът е мотивиран с честота и капацитет; и двата варианта имат ясни граници."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Клиент иска абонамент „колкото видеа се сетим“, но продуктовите снимки зависят от сезона."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Проектът купува резултат и срок; абонаментът резервира капацитет, ритъм и правила при неизползвана или извънредна работа. Избери според честота, входни материали, одобрител и наличен капацитет. Абонаментът има предел, а проектната работа може да се повтаря."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Дръж отделно допускане, потвърден факт и обещание към клиента. Сверявай разходите и часовете с действителния обхват; примерните суми в урока не са тарифа. За договор, данъци, професионална реклама или лични данни провери приложимите правила и потърси компетентен преглед преди реална употреба. Не публикувай човек, музика, чужд продукт или резултат без проверен обхват на правото.\n\nЗа тази задача: Ограничи капацитет, файлове, срокове и цена за допълнителна задача."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Оцени нуждите за три месеца.\n2. Сравни конкретни файлове срещу резервирани часове и дни.\n3. Запиши правила при пропуснат материал, допълнителна задача и пауза.\n4. Предложи пилот с срок за преглед.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Магазин резервира един снимачен ден и четири файла месечно; голяма сезонна кампания остава отделен проект.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Продаваш месечен абонамент без предел и работата става двойна."},"after":{"label":"Как го поправяш","text":"Ограничи капацитет, файлове, срокове и цена за допълнителна задача."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Продаваш месечен абонамент без предел и работата става двойна.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Оцени нуждите за три месеца. След него: Запиши правила при пропуснат материал, допълнителна задача и пауза.\n\nКорекция: Ограничи капацитет, файлове, срокове и цена за допълнителна задача.\n\nНови данни, които ще приемеш за успешна поправка: Изборът е мотивиран с честота и капацитет; и двата варианта имат ясни граници. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Направи предложения за еднократен проект и тримесечен пилот за една и съща фирма.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Изборът е мотивиран с честота и капацитет; и двата варианта имат ясни граници.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Магазин резервира един снимачен ден и четири файла месечно; голяма сезонна кампания остава отделен проект.\n\nДоставка: Направи предложения за еднократен проект и тримесечен пилот за една и съща фирма.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Изборът е мотивиран с честота и капацитет; и двата варианта имат ясни граници."},"points":1,"required":false},{"position":11,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Кога абонаментът има смисъл?","options":[{"id":"a","label":"При едно събитие."},{"id":"b","label":"Само за по-голяма сума."},{"id":"c","label":"При повтаряща се работа с предвидим вход и капацитет."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: При повтаряща се работа с предвидим вход и капацитет.\n\nПървият слаб ход — При едно събитие. — пропуска тази проверка: Изборът е мотивиран с честота и капацитет; и двата варианта имат ясни граници. Вторият — Само за по-голяма сума. — оставя този риск: Продаваш месечен абонамент без предел и работата става двойна. В работна ситуация поправката е: Ограничи капацитет, файлове, срокове и цена за допълнителна задача. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Клиентът не изпраща материал този месец. Какво правиш?","options":[{"id":"a","label":"Трупаш неограничен дълг."},{"id":"b","label":"Измисляш клипове."},{"id":"c","label":"Прилагаш договореното правило и планираш следващия."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Прилагаш договореното правило и планираш следващия.\n\nПървият слаб ход — Измисляш клипове. — пропуска тази проверка: Изборът е мотивиран с честота и капацитет; и двата варианта имат ясни граници. Вторият — Трупаш неограничен дълг. — оставя този риск: Продаваш месечен абонамент без предел и работата става двойна. В работна ситуация поправката е: Ограничи капацитет, файлове, срокове и цена за допълнителна задача. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Как измерваш пилота?","options":[{"id":"a","label":"Доставки, часове и полезно действие за клиента."},{"id":"b","label":"Само брой сторита."},{"id":"c","label":"Само месечната такса."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Доставки, часове и полезно действие за клиента.\n\nПървият слаб ход — Само брой сторита. — пропуска тази проверка: Изборът е мотивиран с честота и капацитет; и двата варианта имат ясни граници. Вторият — Само месечната такса. — оставя този риск: Продаваш месечен абонамент без предел и работата става двойна. В работна ситуация поправката е: Ограничи капацитет, файлове, срокове и цена за допълнителна задача. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Продаваш месечен абонамент без предел и работата става двойна. Как продължаваш?","options":[{"id":"a","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"b","label":"Ограничи капацитет, файлове, срокове и цена за допълнителна задача."},{"id":"c","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Ограничи капацитет, файлове, срокове и цена за допълнителна задача.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Изборът е мотивиран с честота и капацитет; и двата варианта имат ясни граници. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Продаваш месечен абонамент без предел и работата става двойна. В работна ситуация поправката е: Ограничи капацитет, файлове, срокове и цена за допълнителна задача. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s4","text":"Предложи пилот с срок за преглед."},{"id":"s3","text":"Запиши правила при пропуснат материал, допълнителна задача и пауза."},{"id":"s2","text":"Сравни конкретни файлове срещу резервирани часове и дни."},{"id":"s1","text":"Оцени нуждите за три месеца."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Оцени нуждите за три месеца.\n2. Сравни конкретни файлове срещу резервирани часове и дни.\n3. Запиши правила при пропуснат материал, допълнителна задача и пауза.\n4. Предложи пилот с срок за преглед.\n\nПреди окончателното предаване потвърди: Изборът е мотивиран с честота и капацитет; и двата варианта имат ясни граници. Ако разместиш проверката след предаването, остава този риск: Продаваш месечен абонамент без предел и работата става двойна."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Проектът купува резултат и срок; абонаментът резервира капацитет, ритъм и правила при неизползвана или извънредна работа. Избери според честота, входни материали, одобрител и наличен капацитет. Абонаментът има предел, а проектната работа може да се повтаря.","Ограничи капацитет, файлове, срокове и цена за допълнителна задача.","Изборът е мотивиран с честота и капацитет; и двата варианта имат ясни граници."],"nextStep":"Направи предложения за еднократен проект и тримесечен пилот за една и съща фирма."},"points":1,"required":true}]},{"module_id":"s02-m13","lesson_id":"pv13-17","title":"Направи пълен бриф по избран казус","subtitle":"Клиентски бриф, изпълним бюджет и професионално предаване","objective":"Непознат колега планира снимачен ден от документа; блокерите имат отговорник.","hook":"Добра идея за клип, но снимките се местят три пъти, защото никой не е уточнил обекта и одобрителя.","estimated_minutes":42,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Непознат колега планира снимачен ден от документа; блокерите имат отговорник."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Добра идея за клип, но снимките се местят три пъти, защото никой не е уточнил обекта и одобрителя."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Пълният бриф свързва цел, кадър, ресурс, бюджет, срок и потвърден факт. Отдели потвърдено, хипотеза и блокиращо неизвестно. Документът води до снимачен план, а не просто до дълъг текст."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Дръж отделно допускане, потвърден факт и обещание към клиента. Сверявай разходите и часовете с действителния обхват; примерните суми в урока не са тарифа. За договор, данъци, професионална реклама или лични данни провери приложимите правила и потърси компетентен преглед преди реална употреба. Не публикувай човек, музика, чужд продукт или резултат без проверен обхват на правото.\n\nЗа тази задача: Замени оценъчните думи със сцена, собственик, достъп и критерий за изход."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Запиши проблем, публика, действие и доказателство.\n2. Направи сцени, формати, ресурсен план и права.\n3. Добави бюджет, календар, одобрител и блокери.\n4. Дай брифа на външен човек и поправи неясното.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Сервизен бриф посочва разрешен автомобил, техник, ден без клиенти, две вертикални версии и път за записване.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Пишеш „динамично и професионално“, но не знаеш дали има достъп до сервиза."},"after":{"label":"Как го поправяш","text":"Замени оценъчните думи със сцена, собственик, достъп и критерий за изход."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Пишеш „динамично и професионално“, но не знаеш дали има достъп до сервиза.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Запиши проблем, публика, действие и доказателство. След него: Добави бюджет, календар, одобрител и блокери.\n\nКорекция: Замени оценъчните думи със сцена, собственик, достъп и критерий за изход.\n\nНови данни, които ще приемеш за успешна поправка: Непознат колега планира снимачен ден от документа; блокерите имат отговорник. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Състави пълен бриф за ниша: цел, човек, обещание, 6 кадъра, права, бюджет, срок, формати и въпроси.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Непознат колега планира снимачен ден от документа; блокерите имат отговорник.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Сервизен бриф посочва разрешен автомобил, техник, ден без клиенти, две вертикални версии и път за записване.\n\nДоставка: Състави пълен бриф за ниша: цел, човек, обещание, 6 кадъра, права, бюджет, срок, формати и въпроси.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Непознат колега планира снимачен ден от документа; блокерите имат отговорник."},"points":1,"required":false},{"position":11,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Какъв е изходът от брифа?","options":[{"id":"a","label":"Снимачен план и проверими решения."},{"id":"b","label":"Безкрайни референции."},{"id":"c","label":"Прилагателни."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Снимачен план и проверими решения.\n\nПървият слаб ход — Прилагателни. — пропуска тази проверка: Непознат колега планира снимачен ден от документа; блокерите имат отговорник. Вторият — Безкрайни референции. — оставя този риск: Пишеш „динамично и професионално“, но не знаеш дали има достъп до сервиза. В работна ситуация поправката е: Замени оценъчните думи със сцена, собственик, достъп и критерий за изход. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Няма потвърден автомобил. Какво правиш?","options":[{"id":"a","label":"Вземаш кола от паркинга."},{"id":"b","label":"Премълчаваш."},{"id":"c","label":"Маркираш блокер и не обещаваш кадъра."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Маркираш блокер и не обещаваш кадъра.\n\nПървият слаб ход — Вземаш кола от паркинга. — пропуска тази проверка: Непознат колега планира снимачен ден от документа; блокерите имат отговорник. Вторият — Премълчаваш. — оставя този риск: Пишеш „динамично и професионално“, но не знаеш дали има достъп до сервиза. В работна ситуация поправката е: Замени оценъчните думи със сцена, собственик, достъп и критерий за изход. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Как тестваш документа?","options":[{"id":"a","label":"Сменяш шрифта."},{"id":"b","label":"Броиш страници."},{"id":"c","label":"Друг човек може да планира без устни догадки."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Друг човек може да планира без устни догадки.\n\nПървият слаб ход — Броиш страници. — пропуска тази проверка: Непознат колега планира снимачен ден от документа; блокерите имат отговорник. Вторият — Сменяш шрифта. — оставя този риск: Пишеш „динамично и професионално“, но не знаеш дали има достъп до сервиза. В работна ситуация поправката е: Замени оценъчните думи със сцена, собственик, достъп и критерий за изход. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Пишеш „динамично и професионално“, но не знаеш дали има достъп до сервиза. Как продължаваш?","options":[{"id":"a","label":"Замени оценъчните думи със сцена, собственик, достъп и критерий за изход."},{"id":"b","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"c","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Замени оценъчните думи със сцена, собственик, достъп и критерий за изход.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Непознат колега планира снимачен ден от документа; блокерите имат отговорник. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Пишеш „динамично и професионално“, но не знаеш дали има достъп до сервиза. В работна ситуация поправката е: Замени оценъчните думи със сцена, собственик, достъп и критерий за изход. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s2","text":"Направи сцени, формати, ресурсен план и права."},{"id":"s3","text":"Добави бюджет, календар, одобрител и блокери."},{"id":"s4","text":"Дай брифа на външен човек и поправи неясното."},{"id":"s1","text":"Запиши проблем, публика, действие и доказателство."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Запиши проблем, публика, действие и доказателство.\n2. Направи сцени, формати, ресурсен план и права.\n3. Добави бюджет, календар, одобрител и блокери.\n4. Дай брифа на външен човек и поправи неясното.\n\nПреди окончателното предаване потвърди: Непознат колега планира снимачен ден от документа; блокерите имат отговорник. Ако разместиш проверката след предаването, остава този риск: Пишеш „динамично и професионално“, но не знаеш дали има достъп до сервиза."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Пълният бриф свързва цел, кадър, ресурс, бюджет, срок и потвърден факт. Отдели потвърдено, хипотеза и блокиращо неизвестно. Документът води до снимачен план, а не просто до дълъг текст.","Замени оценъчните думи със сцена, собственик, достъп и критерий за изход.","Непознат колега планира снимачен ден от документа; блокерите имат отговорник."],"nextStep":"Състави пълен бриф за ниша: цел, човек, обещание, 6 кадъра, права, бюджет, срок, формати и въпроси."},"points":1,"required":true}]},{"module_id":"s02-m13","lesson_id":"pv13-18","title":"Направи ценова листа и изпрати реална оферта","subtitle":"Клиентски бриф, изпълним бюджет и професионално предаване","objective":"Сумите имат допускания; „изпратено“ се пише само след действително изпращане.","hook":"Имаш ценова листа, но конкретният клиент иска други файлове и още не е съгласувал задачата.","estimated_minutes":42,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Сумите имат допускания; „изпратено“ се пише само след действително изпращане."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Имаш ценова листа, но конкретният клиент иска други файлове и още не е съгласувал задачата."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Ценовата листа е рамка за разговор: 2–3 услуги с базов резултат, входни условия и правило за индивидуална оценка. Реална оферта се изпраща след проверен бриф до уместен контакт; без такъв подготви готов за изпращане пример с фиктивни данни. Отбелязвай реален статус, не измислена продажба."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Дръж отделно допускане, потвърден факт и обещание към клиента. Сверявай разходите и часовете с действителния обхват; примерните суми в урока не са тарифа. За договор, данъци, професионална реклама или лични данни провери приложимите правила и потърси компетентен преглед преди реална употреба. Не публикувай човек, музика, чужд продукт или резултат без проверен обхват на правото.\n\nЗа тази задача: Персонализирай след проверена задача; при липса на контакт маркирай симулацията като неизпратена."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Изчисли база за всяка услуга и граница на обхвата.\n2. Сравни брифа с базовата услуга.\n3. Напиши оферта с файлове, срок, цена, права и ревизии.\n4. Провери адресат и факти; при реален контакт изпрати по съгласувания канал.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"За магазин рамката е снимачен ден и основен монтаж; конкретната оферта добавя две разрешени вертикални версии и отделна локация.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Пращаш една ценова листа на 20 бизнеса и приемаш мълчанието за интерес."},"after":{"label":"Как го поправяш","text":"Персонализирай след проверена задача; при липса на контакт маркирай симулацията като неизпратена."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Пращаш една ценова листа на 20 бизнеса и приемаш мълчанието за интерес.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Изчисли база за всяка услуга и граница на обхвата. След него: Напиши оферта с файлове, срок, цена, права и ревизии.\n\nКорекция: Персонализирай след проверена задача; при липса на контакт маркирай симулацията като неизпратена.\n\nНови данни, които ще приемеш за успешна поправка: Сумите имат допускания; „изпратено“ се пише само след действително изпращане. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Създай три рамкови услуги и една конкретна оферта. Ако имаш уместен контакт и съгласуван бриф, изпрати я и отбележи действителния статус.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Сумите имат допускания; „изпратено“ се пише само след действително изпращане.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: За магазин рамката е снимачен ден и основен монтаж; конкретната оферта добавя две разрешени вертикални версии и отделна локация.\n\nДоставка: Създай три рамкови услуги и една конкретна оферта. Ако имаш уместен контакт и съгласуван бриф, изпрати я и отбележи действителния статус.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Сумите имат допускания; „изпратено“ се пише само след действително изпращане."},"points":1,"required":false},{"position":11,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Коя ценова листа помага?","options":[{"id":"a","label":"Копирани цени."},{"id":"b","label":"Услуги с обхват и условие за индивидуална оценка."},{"id":"c","label":"Едно число за всичко."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Услуги с обхват и условие за индивидуална оценка.\n\nПървият слаб ход — Едно число за всичко. — пропуска тази проверка: Сумите имат допускания; „изпратено“ се пише само след действително изпращане. Вторият — Копирани цени. — оставя този риск: Пращаш една ценова листа на 20 бизнеса и приемаш мълчанието за интерес. В работна ситуация поправката е: Персонализирай след проверена задача; при липса на контакт маркирай симулацията като неизпратена. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Нямаш контакт или одобрен бриф. Какъв е изходът?","options":[{"id":"a","label":"Готова симулационна оферта, маркирана като неизпратена."},{"id":"b","label":"Запис „клиентът прие“."},{"id":"c","label":"Измислен имейл."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Готова симулационна оферта, маркирана като неизпратена.\n\nПървият слаб ход — Измислен имейл. — пропуска тази проверка: Сумите имат допускания; „изпратено“ се пише само след действително изпращане. Вторият — Запис „клиентът прие“. — оставя този риск: Пращаш една ценова листа на 20 бизнеса и приемаш мълчанието за интерес. В работна ситуация поправката е: Персонализирай след проверена задача; при липса на контакт маркирай симулацията като неизпратена. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Какво учиш от реалния отговор?","options":[{"id":"a","label":"Само отваряния на PDF."},{"id":"b","label":"Само броя писма."},{"id":"c","label":"Въпроси и причина за решение спрямо обхвата."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Въпроси и причина за решение спрямо обхвата.\n\nПървият слаб ход — Само отваряния на PDF. — пропуска тази проверка: Сумите имат допускания; „изпратено“ се пише само след действително изпращане. Вторият — Само броя писма. — оставя този риск: Пращаш една ценова листа на 20 бизнеса и приемаш мълчанието за интерес. В работна ситуация поправката е: Персонализирай след проверена задача; при липса на контакт маркирай симулацията като неизпратена. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Пращаш една ценова листа на 20 бизнеса и приемаш мълчанието за интерес. Как продължаваш?","options":[{"id":"a","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"b","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"c","label":"Персонализирай след проверена задача; при липса на контакт маркирай симулацията като неизпратена."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Персонализирай след проверена задача; при липса на контакт маркирай симулацията като неизпратена.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Сумите имат допускания; „изпратено“ се пише само след действително изпращане. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Пращаш една ценова листа на 20 бизнеса и приемаш мълчанието за интерес. В работна ситуация поправката е: Персонализирай след проверена задача; при липса на контакт маркирай симулацията като неизпратена. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s2","text":"Сравни брифа с базовата услуга."},{"id":"s1","text":"Изчисли база за всяка услуга и граница на обхвата."},{"id":"s4","text":"Провери адресат и факти; при реален контакт изпрати по съгласувания канал."},{"id":"s3","text":"Напиши оферта с файлове, срок, цена, права и ревизии."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Изчисли база за всяка услуга и граница на обхвата.\n2. Сравни брифа с базовата услуга.\n3. Напиши оферта с файлове, срок, цена, права и ревизии.\n4. Провери адресат и факти; при реален контакт изпрати по съгласувания канал.\n\nПреди окончателното предаване потвърди: Сумите имат допускания; „изпратено“ се пише само след действително изпращане. Ако разместиш проверката след предаването, остава този риск: Пращаш една ценова листа на 20 бизнеса и приемаш мълчанието за интерес."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Ценовата листа е рамка за разговор: 2–3 услуги с базов резултат, входни условия и правило за индивидуална оценка. Реална оферта се изпраща след проверен бриф до уместен контакт; без такъв подготви готов за изпращане пример с фиктивни данни. Отбелязвай реален статус, не измислена продажба.","Персонализирай след проверена задача; при липса на контакт маркирай симулацията като неизпратена.","Сумите имат допускания; „изпратено“ се пише само след действително изпращане."],"nextStep":"Създай три рамкови услуги и една конкретна оферта. Ако имаш уместен контакт и съгласуван бриф, изпрати я и отбележи действителния статус."},"points":1,"required":true}]},{"module_id":"s02-m14","lesson_id":"pv14-01","title":"Адаптирай (не копирай) готов hook върху своя тема","subtitle":"Работещи шаблони, собствен стил и одит с доказателства","objective":"Непознат зрител разбира темата и вижда обещания резултат в клипа; няма заемка едно към едно.","hook":"Виждаш hook „Никой не ти казва това“ и го лепиш на клип за смяна на гума, без да казваш какво ще научи човекът.","estimated_minutes":36,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Непознат зрител разбира темата и вижда обещания резултат в клипа; няма заемка едно към едно."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Виждаш hook „Никой не ти казва това“ и го лепиш на клип за смяна на гума, без да казваш какво ще научи човекът."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Вземи механизма на hook-а, не чуждите думи: конкретно напрежение, демонстрация и честен резултат в първите секунди. Обещанието трябва да има кадър, който го изпълнява. Сравни вариант, който говори на нов клиент, и вариант за човек с вече възникнал проблем; използвай конкретен език, не сензация."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Запази изходната версия и описвай промяна с конкретен кадър или timecode. Шаблонът е структура за собствено доказателство, не чужд текст за копиране. Провери права за активите, четимост и звук на целевия екран, както и версията, която действително е качена. При тест с малко хора записвай ограниченията на наблюдението; не наричай предположение измерен ефект.\n\nЗа тази задача: Напиши началото от собствен факт и пренареди първия кадър така, че да покаже отговора."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Определи въпроса на зрителя и резултата на клипа.\n2. Извади структурата на примерния hook, без фразата му.\n3. Напиши два собствени варианта и кадъра, който ги доказва.\n4. Покажи началото на трима души без контекст и запиши какво очакват.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"За сервиз вместо „тайна, която майсторите крият“ началото е „Чуваш този звук след смяна на гума? Ето какво първо проверяваме.“ Кадърът показва конкретна диагностика.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Взимаш дословен hook и видео, което не изпълнява обещанието."},"after":{"label":"Как го поправяш","text":"Напиши началото от собствен факт и пренареди първия кадър така, че да покаже отговора."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Взимаш дословен hook и видео, което не изпълнява обещанието.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Определи въпроса на зрителя и резултата на клипа. След него: Напиши два собствени варианта и кадъра, който ги доказва.\n\nКорекция: Напиши началото от собствен факт и пренареди първия кадър така, че да покаже отговора.\n\nНови данни, които ще приемеш за успешна поправка: Непознат зрител разбира темата и вижда обещания резултат в клипа; няма заемка едно към едно. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Адаптирай три чужди структури върху собствена тема без копирани фрази; за всеки hook посочи доказващ кадър.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Непознат зрител разбира темата и вижда обещания резултат в клипа; няма заемка едно към едно.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: За сервиз вместо „тайна, която майсторите крият“ началото е „Чуваш този звук след смяна на гума? Ето какво първо проверяваме.“ Кадърът показва конкретна диагностика.\n\nДоставка: Адаптирай три чужди структури върху собствена тема без копирани фрази; за всеки hook посочи доказващ кадър.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Непознат зрител разбира темата и вижда обещания резултат в клипа; няма заемка едно към едно."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Проверен първоизточник","content":{"body":"YouTube Help — моменти на задържане: https://support.google.com/youtube/answer/9314415\nПровери текущата версия на функцията преди да повториш стъпките."},"points":0,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Кое е адаптация?","options":[{"id":"a","label":"Дословна фраза."},{"id":"b","label":"Собствен въпрос, конкретен кадър и нови думи по общ механизъм."},{"id":"c","label":"Сензация без доказателство."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Собствен въпрос, конкретен кадър и нови думи по общ механизъм.\n\nПървият слаб ход — Дословна фраза. — пропуска тази проверка: Непознат зрител разбира темата и вижда обещания резултат в клипа; няма заемка едно към едно. Вторият — Сензация без доказателство. — оставя този риск: Взимаш дословен hook и видео, което не изпълнява обещанието. В работна ситуация поправката е: Напиши началото от собствен факт и пренареди първия кадър така, че да покаже отговора. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Кадърът не показва обещания резултат. Какво правиш?","options":[{"id":"a","label":"Добавяш удивителни."},{"id":"b","label":"Променяш началото или заснемаш липсващото доказателство."},{"id":"c","label":"Оставяш hook-а за гледания."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Променяш началото или заснемаш липсващото доказателство.\n\nПървият слаб ход — Оставяш hook-а за гледания. — пропуска тази проверка: Непознат зрител разбира темата и вижда обещания резултат в клипа; няма заемка едно към едно. Вторият — Добавяш удивителни. — оставя този риск: Взимаш дословен hook и видео, което не изпълнява обещанието. В работна ситуация поправката е: Напиши началото от собствен факт и пренареди първия кадър така, че да покаже отговора. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Какъв тест правиш?","options":[{"id":"a","label":"Питаш какво очакват трима души и сравняваш с реалния клип."},{"id":"b","label":"Избираш най-шумната музика."},{"id":"c","label":"Само броиш думи."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Питаш какво очакват трима души и сравняваш с реалния клип.\n\nПървият слаб ход — Само броиш думи. — пропуска тази проверка: Непознат зрител разбира темата и вижда обещания резултат в клипа; няма заемка едно към едно. Вторият — Избираш най-шумната музика. — оставя този риск: Взимаш дословен hook и видео, което не изпълнява обещанието. В работна ситуация поправката е: Напиши началото от собствен факт и пренареди първия кадър така, че да покаже отговора. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Взимаш дословен hook и видео, което не изпълнява обещанието. Как продължаваш?","options":[{"id":"a","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"b","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"c","label":"Напиши началото от собствен факт и пренареди първия кадър така, че да покаже отговора."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Напиши началото от собствен факт и пренареди първия кадър така, че да покаже отговора.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Непознат зрител разбира темата и вижда обещания резултат в клипа; няма заемка едно към едно. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Взимаш дословен hook и видео, което не изпълнява обещанието. В работна ситуация поправката е: Напиши началото от собствен факт и пренареди първия кадър така, че да покаже отговора. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s4","text":"Покажи началото на трима души без контекст и запиши какво очакват."},{"id":"s1","text":"Определи въпроса на зрителя и резултата на клипа."},{"id":"s2","text":"Извади структурата на примерния hook, без фразата му."},{"id":"s3","text":"Напиши два собствени варианта и кадъра, който ги доказва."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Определи въпроса на зрителя и резултата на клипа.\n2. Извади структурата на примерния hook, без фразата му.\n3. Напиши два собствени варианта и кадъра, който ги доказва.\n4. Покажи началото на трима души без контекст и запиши какво очакват.\n\nПреди окончателното предаване потвърди: Непознат зрител разбира темата и вижда обещания резултат в клипа; няма заемка едно към едно. Ако разместиш проверката след предаването, остава този риск: Взимаш дословен hook и видео, което не изпълнява обещанието."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Вземи механизма на hook-а, не чуждите думи: конкретно напрежение, демонстрация и честен резултат в първите секунди. Обещанието трябва да има кадър, който го изпълнява. Сравни вариант, който говори на нов клиент, и вариант за човек с вече възникнал проблем; използвай конкретен език, не сензация.","Напиши началото от собствен факт и пренареди първия кадър така, че да покаже отговора.","Непознат зрител разбира темата и вижда обещания резултат в клипа; няма заемка едно към едно."],"nextStep":"Адаптирай три чужди структури върху собствена тема без копирани фрази; за всеки hook посочи доказващ кадър."},"points":1,"required":true}]},{"module_id":"s02-m14","lesson_id":"pv14-02","title":"Адаптирай готов CTA върху своя оферта","subtitle":"Работещи шаблони, собствен стил и одит с доказателства","objective":"Зрителят знае какво следва и къде; текстът, каналът и действителната дестинация съвпадат.","hook":"Видео обещава час за преглед, но последният надпис казва само „последвай ни“.","estimated_minutes":34,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Зрителят знае какво следва и къде; текстът, каналът и действителната дестинация съвпадат."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Видео обещава час за преглед, но последният надпис казва само „последвай ни“."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"CTA е следващата малка стъпка, свързана с задачата и канала. На човек, който още проверява, можеш да покажеш полезен критерий; на готов клиент — точен път за записване. Избери едно основно действие, провери дестинацията на телефон и не обещавай наличност, която не контролираш."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Запази изходната версия и описвай промяна с конкретен кадър или timecode. Шаблонът е структура за собствено доказателство, не чужд текст за копиране. Провери права за активите, четимост и звук на целевия екран, както и версията, която действително е качена. При тест с малко хора записвай ограниченията на наблюдението; не наричай предположение измерен ефект.\n\nЗа тази задача: Остави едно действие и директна проверена дестинация; уточни, ако записванията още не са отворени."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Запиши целта на видеото и текущата готовност на зрителя.\n2. Избери едно действие и адрес/механизъм за изпълнение.\n3. Напиши CTA с полза и точни условия.\n4. Кликни го от реалния канал и виж дали формулярът работи.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"За кулинарен курс клипът показва първа техника, после „Виж програмата и свободните дати в линка“. Провереният линк води до правилната страница, а датите са актуални.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Каниш към пет различни действия и линкът отваря началната страница без курс."},"after":{"label":"Как го поправяш","text":"Остави едно действие и директна проверена дестинация; уточни, ако записванията още не са отворени."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Каниш към пет различни действия и линкът отваря началната страница без курс.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Запиши целта на видеото и текущата готовност на зрителя. След него: Напиши CTA с полза и точни условия.\n\nКорекция: Остави едно действие и директна проверена дестинация; уточни, ако записванията още не са отворени.\n\nНови данни, които ще приемеш за успешна поправка: Зрителят знае какво следва и къде; текстът, каналът и действителната дестинация съвпадат. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Напиши два CTA за една оферта: за първо запознаване и за човек, готов да заяви; провери двата пътя на телефон.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Зрителят знае какво следва и къде; текстът, каналът и действителната дестинация съвпадат.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: За кулинарен курс клипът показва първа техника, после „Виж програмата и свободните дати в линка“. Провереният линк води до правилната страница, а датите са актуални.\n\nДоставка: Напиши два CTA за една оферта: за първо запознаване и за човек, готов да заяви; провери двата пътя на телефон.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Зрителят знае какво следва и къде; текстът, каналът и действителната дестинация съвпадат."},"points":1,"required":false},{"position":11,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Кой CTA е конкретен?","options":[{"id":"a","label":"„Виж свободните дати за курса в линка“ при работеща страница."},{"id":"b","label":"„Харесай, сподели и купи“."},{"id":"c","label":"„Знаеш какво да правиш“."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: „Виж свободните дати за курса в линка“ при работеща страница.\n\nПървият слаб ход — „Харесай, сподели и купи“. — пропуска тази проверка: Зрителят знае какво следва и къде; текстът, каналът и действителната дестинация съвпадат. Вторият — „Знаеш какво да правиш“. — оставя този риск: Каниш към пет различни действия и линкът отваря началната страница без курс. В работна ситуация поправката е: Остави едно действие и директна проверена дестинация; уточни, ако записванията още не са отворени. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Страницата за записване е затворена. Какво правиш?","options":[{"id":"a","label":"Оставяш „резервирай днес“."},{"id":"b","label":"Сменяш обещанието и посочваш актуалната следваща стъпка."},{"id":"c","label":"Криеш линка."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Сменяш обещанието и посочваш актуалната следваща стъпка.\n\nПървият слаб ход — Оставяш „резервирай днес“. — пропуска тази проверка: Зрителят знае какво следва и къде; текстът, каналът и действителната дестинация съвпадат. Вторият — Криеш линка. — оставя този риск: Каниш към пет различни действия и линкът отваря началната страница без курс. В работна ситуация поправката е: Остави едно действие и директна проверена дестинация; уточни, ако записванията още не са отворени. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Какво проверяваш?","options":[{"id":"a","label":"Само броя емоджита."},{"id":"b","label":"Реален клик от целевия екран до правилната страница."},{"id":"c","label":"Само цвета на бутона."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Реален клик от целевия екран до правилната страница.\n\nПървият слаб ход — Само цвета на бутона. — пропуска тази проверка: Зрителят знае какво следва и къде; текстът, каналът и действителната дестинация съвпадат. Вторият — Само броя емоджита. — оставя този риск: Каниш към пет различни действия и линкът отваря началната страница без курс. В работна ситуация поправката е: Остави едно действие и директна проверена дестинация; уточни, ако записванията още не са отворени. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Каниш към пет различни действия и линкът отваря началната страница без курс. Как продължаваш?","options":[{"id":"a","label":"Остави едно действие и директна проверена дестинация; уточни, ако записванията още не са отворени."},{"id":"b","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"c","label":"Продължаваш без проверка и наричаш тази версия окончателна."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Остави едно действие и директна проверена дестинация; уточни, ако записванията още не са отворени.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Зрителят знае какво следва и къде; текстът, каналът и действителната дестинация съвпадат. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Каниш към пет различни действия и линкът отваря началната страница без курс. В работна ситуация поправката е: Остави едно действие и директна проверена дестинация; уточни, ако записванията още не са отворени. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s4","text":"Кликни го от реалния канал и виж дали формулярът работи."},{"id":"s3","text":"Напиши CTA с полза и точни условия."},{"id":"s2","text":"Избери едно действие и адрес/механизъм за изпълнение."},{"id":"s1","text":"Запиши целта на видеото и текущата готовност на зрителя."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Запиши целта на видеото и текущата готовност на зрителя.\n2. Избери едно действие и адрес/механизъм за изпълнение.\n3. Напиши CTA с полза и точни условия.\n4. Кликни го от реалния канал и виж дали формулярът работи.\n\nПреди окончателното предаване потвърди: Зрителят знае какво следва и къде; текстът, каналът и действителната дестинация съвпадат. Ако разместиш проверката след предаването, остава този риск: Каниш към пет различни действия и линкът отваря началната страница без курс."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["CTA е следващата малка стъпка, свързана с задачата и канала. На човек, който още проверява, можеш да покажеш полезен критерий; на готов клиент — точен път за записване. Избери едно основно действие, провери дестинацията на телефон и не обещавай наличност, която не контролираш.","Остави едно действие и директна проверена дестинация; уточни, ако записванията още не са отворени.","Зрителят знае какво следва и къде; текстът, каналът и действителната дестинация съвпадат."],"nextStep":"Напиши два CTA за една оферта: за първо запознаване и за човек, готов да заяви; провери двата пътя на телефон."},"points":1,"required":true}]},{"module_id":"s02-m14","lesson_id":"pv14-03","title":"Адаптирай готов сценариен темплейт за реален проект","subtitle":"Работещи шаблони, собствен стил и одит с доказателства","objective":"Никой ред не остава като placeholder; за всеки факт има кадър или одобрен източник.","hook":"Взимаш сценарий „проблем–решение–CTA“, но твоят продукт няма кадър, който доказва решението.","estimated_minutes":36,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Никой ред не остава като placeholder; за всеки факт има кадър или одобрен източник."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Взимаш сценарий „проблем–решение–CTA“, но твоят продукт няма кадър, който доказва решението."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Темплейтът е празна последователност на решения, не готов текст. Напълни всяка сцена със специфичен факт, действие, звук или визуално доказателство; маркирай какво липсва и кой го дава. Ако доказателството не съществува, смени структурата или направи проверима демонстрация вместо твърдение."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Запази изходната версия и описвай промяна с конкретен кадър или timecode. Шаблонът е структура за собствено доказателство, не чужд текст за копиране. Провери права за активите, четимост и звук на целевия екран, както и версията, която действително е качена. При тест с малко хора записвай ограниченията на наблюдението; не наричай предположение измерен ефект.\n\nЗа тази задача: Замени общата реплика с наблюдаемо действие и конкретна граница."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Разпиши вход, напрежение, демонстрация, изход и действие.\n2. За всяка част посочи конкретен кадър, реплика, продължителност и източник.\n3. Провери твърденията с продукта или компетентния човек.\n4. Направи груб storyboard и изрежи частите без функция.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Магазин за велосипеди показва как велосипедът влиза в асансьор, вместо да твърди „идеален за всеки дом“. Сценарият отговаря на едно реално ограничение.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Сценарият казва „улесни живота си“, но зрителят не вижда как."},"after":{"label":"Как го поправяш","text":"Замени общата реплика с наблюдаемо действие и конкретна граница."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Сценарият казва „улесни живота си“, но зрителят не вижда как.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Разпиши вход, напрежение, демонстрация, изход и действие. След него: Провери твърденията с продукта или компетентния човек.\n\nКорекция: Замени общата реплика с наблюдаемо действие и конкретна граница.\n\nНови данни, които ще приемеш за успешна поправка: Никой ред не остава като placeholder; за всеки факт има кадър или одобрен източник. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Вземи един шаблон и напиши 30-секунден сценарий с 5 сцени за свой разрешен продукт; отбележи източника на всяко обещание.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Никой ред не остава като placeholder; за всеки факт има кадър или одобрен източник.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Магазин за велосипеди показва как велосипедът влиза в асансьор, вместо да твърди „идеален за всеки дом“. Сценарият отговаря на едно реално ограничение.\n\nДоставка: Вземи един шаблон и напиши 30-секунден сценарий с 5 сцени за свой разрешен продукт; отбележи източника на всяко обещание.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Никой ред не остава като placeholder; за всеки факт има кадър или одобрен източник."},"points":1,"required":false},{"position":11,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Какво прави шаблона полезен?","options":[{"id":"a","label":"Повече прилагателни."},{"id":"b","label":"Повторена готова фраза."},{"id":"c","label":"Конкретен кадър и проверимо действие във всяка сцена."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Конкретен кадър и проверимо действие във всяка сцена.\n\nПървият слаб ход — Повторена готова фраза. — пропуска тази проверка: Никой ред не остава като placeholder; за всеки факт има кадър или одобрен източник. Вторият — Повече прилагателни. — оставя този риск: Сценарият казва „улесни живота си“, но зрителят не вижда как. В работна ситуация поправката е: Замени общата реплика с наблюдаемо действие и конкретна граница. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Нямаш доказателство за резултат. Какво правиш?","options":[{"id":"a","label":"Сменяш твърдението или заснемаш доказуема демонстрация."},{"id":"b","label":"Добавяш stock кадър."},{"id":"c","label":"Говориш по-уверено."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Сменяш твърдението или заснемаш доказуема демонстрация.\n\nПървият слаб ход — Добавяш stock кадър. — пропуска тази проверка: Никой ред не остава като placeholder; за всеки факт има кадър или одобрен източник. Вторият — Говориш по-уверено. — оставя този риск: Сценарият казва „улесни живота си“, но зрителят не вижда как. В работна ситуация поправката е: Замени общата реплика с наблюдаемо действие и конкретна граница. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Как проверяваш сценария?","options":[{"id":"a","label":"Само дължината."},{"id":"b","label":"Storyboard и списък на източници за твърденията."},{"id":"c","label":"Само броя сцени."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Storyboard и списък на източници за твърденията.\n\nПървият слаб ход — Само дължината. — пропуска тази проверка: Никой ред не остава като placeholder; за всеки факт има кадър или одобрен източник. Вторият — Само броя сцени. — оставя този риск: Сценарият казва „улесни живота си“, но зрителят не вижда как. В работна ситуация поправката е: Замени общата реплика с наблюдаемо действие и конкретна граница. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Сценарият казва „улесни живота си“, но зрителят не вижда как. Как продължаваш?","options":[{"id":"a","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"b","label":"Замени общата реплика с наблюдаемо действие и конкретна граница."},{"id":"c","label":"Продължаваш без проверка и наричаш тази версия окончателна."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Замени общата реплика с наблюдаемо действие и конкретна граница.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Никой ред не остава като placeholder; за всеки факт има кадър или одобрен източник. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Сценарият казва „улесни живота си“, но зрителят не вижда как. В работна ситуация поправката е: Замени общата реплика с наблюдаемо действие и конкретна граница. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s2","text":"За всяка част посочи конкретен кадър, реплика, продължителност и източник."},{"id":"s3","text":"Провери твърденията с продукта или компетентния човек."},{"id":"s4","text":"Направи груб storyboard и изрежи частите без функция."},{"id":"s1","text":"Разпиши вход, напрежение, демонстрация, изход и действие."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Разпиши вход, напрежение, демонстрация, изход и действие.\n2. За всяка част посочи конкретен кадър, реплика, продължителност и източник.\n3. Провери твърденията с продукта или компетентния човек.\n4. Направи груб storyboard и изрежи частите без функция.\n\nПреди окончателното предаване потвърди: Никой ред не остава като placeholder; за всеки факт има кадър или одобрен източник. Ако разместиш проверката след предаването, остава този риск: Сценарият казва „улесни живота си“, но зрителят не вижда как."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Темплейтът е празна последователност на решения, не готов текст. Напълни всяка сцена със специфичен факт, действие, звук или визуално доказателство; маркирай какво липсва и кой го дава. Ако доказателството не съществува, смени структурата или направи проверима демонстрация вместо твърдение.","Замени общата реплика с наблюдаемо действие и конкретна граница.","Никой ред не остава като placeholder; за всеки факт има кадър или одобрен източник."],"nextStep":"Вземи един шаблон и напиши 30-секунден сценарий с 5 сцени за свой разрешен продукт; отбележи източника на всяко обещание."},"points":1,"required":true}]},{"module_id":"s02-m14","lesson_id":"pv14-04","title":"Приложи storytelling структура върху съществуваща идея","subtitle":"Работещи шаблони, собствен стил и одит с доказателства","objective":"Човек извън проекта може да назове промяната и доказателството без да му я обясняваш.","hook":"Историята започва с „един ден всичко се промени“, но няма реален избор и няма истински клиентски резултат.","estimated_minutes":36,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Човек извън проекта може да назове промяната и доказателството без да му я обясняваш."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Историята започва с „един ден всичко се промени“, но няма реален избор и няма истински клиентски резултат."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Storytelling е наблюдаема промяна: начална ситуация, залог, избор, действие, резултат и граница. Не измисляй клиентска история; при липса на разрешен случай използвай ясно обозначена демонстрация. Запази човешки момент, но не скривай необходимата информация заради драматичен обрат."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Запази изходната версия и описвай промяна с конкретен кадър или timecode. Шаблонът е структура за собствено доказателство, не чужд текст за копиране. Провери права за активите, четимост и звук на целевия екран, както и версията, която действително е качена. При тест с малко хора записвай ограниченията на наблюдението; не наричай предположение измерен ефект.\n\nЗа тази задача: Върни се към разрешен реален случай или маркирана демонстрация с проверим изход."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Избери реално напрежение и участник с разрешение.\n2. Запиши неговото решение и това, което камерата може да докаже.\n3. Построй три сцени: преди, действие, след с честна граница.\n4. Покажи rough cut на човек, който не знае историята.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Пекарка получава заявка с необичаен размер, измерва кутията, променя подредбата и показва готовата торта. Финалът е реален процес, не твърдение, че всички поръчки са за ден.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Монтираш чуждо testimonial видео като собствена история."},"after":{"label":"Как го поправяш","text":"Върни се към разрешен реален случай или маркирана демонстрация с проверим изход."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Монтираш чуждо testimonial видео като собствена история.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Избери реално напрежение и участник с разрешение. След него: Построй три сцени: преди, действие, след с честна граница.\n\nКорекция: Върни се към разрешен реален случай или маркирана демонстрация с проверим изход.\n\nНови данни, които ще приемеш за успешна поправка: Човек извън проекта може да назове промяната и доказателството без да му я обясняваш. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Пренапиши своя идея като 3 сцени с начално условие, решение, видим резултат и граница на твърдението.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Човек извън проекта може да назове промяната и доказателството без да му я обясняваш.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Пекарка получава заявка с необичаен размер, измерва кутията, променя подредбата и показва готовата торта. Финалът е реален процес, не твърдение, че всички поръчки са за ден.\n\nДоставка: Пренапиши своя идея като 3 сцени с начално условие, решение, видим резултат и граница на твърдението.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Човек извън проекта може да назове промяната и доказателството без да му я обясняваш."},"points":1,"required":false},{"position":11,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Коя история е честна?","options":[{"id":"a","label":"Генеричен герой с измислена победа."},{"id":"b","label":"Скрит ключов отговор."},{"id":"c","label":"Реален избор с видим резултат и ограничение."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Реален избор с видим резултат и ограничение.\n\nПървият слаб ход — Генеричен герой с измислена победа. — пропуска тази проверка: Човек извън проекта може да назове промяната и доказателството без да му я обясняваш. Вторият — Скрит ключов отговор. — оставя този риск: Монтираш чуждо testimonial видео като собствена история. В работна ситуация поправката е: Върни се към разрешен реален случай или маркирана демонстрация с проверим изход. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Клиент няма разрешен testimonial. Какво правиш?","options":[{"id":"a","label":"Слагаш актьор като реален клиент."},{"id":"b","label":"Приписваш анонимен отзив."},{"id":"c","label":"Използваш маркирана демонстрация или собствен процес."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Използваш маркирана демонстрация или собствен процес.\n\nПървият слаб ход — Приписваш анонимен отзив. — пропуска тази проверка: Човек извън проекта може да назове промяната и доказателството без да му я обясняваш. Вторият — Слагаш актьор като реален клиент. — оставя този риск: Монтираш чуждо testimonial видео като собствена история. В работна ситуация поправката е: Върни се към разрешен реален случай или маркирана демонстрация с проверим изход. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Какво проверява грубият монтаж?","options":[{"id":"a","label":"Дали промяната се разбира от непознат зрител."},{"id":"b","label":"Само драматичната музика."},{"id":"c","label":"Само броя завои."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Дали промяната се разбира от непознат зрител.\n\nПървият слаб ход — Само драматичната музика. — пропуска тази проверка: Човек извън проекта може да назове промяната и доказателството без да му я обясняваш. Вторият — Само броя завои. — оставя този риск: Монтираш чуждо testimonial видео като собствена история. В работна ситуация поправката е: Върни се към разрешен реален случай или маркирана демонстрация с проверим изход. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Монтираш чуждо testimonial видео като собствена история. Как продължаваш?","options":[{"id":"a","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"b","label":"Върни се към разрешен реален случай или маркирана демонстрация с проверим изход."},{"id":"c","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Върни се към разрешен реален случай или маркирана демонстрация с проверим изход.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Човек извън проекта може да назове промяната и доказателството без да му я обясняваш. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Монтираш чуждо testimonial видео като собствена история. В работна ситуация поправката е: Върни се към разрешен реален случай или маркирана демонстрация с проверим изход. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s2","text":"Запиши неговото решение и това, което камерата може да докаже."},{"id":"s1","text":"Избери реално напрежение и участник с разрешение."},{"id":"s4","text":"Покажи rough cut на човек, който не знае историята."},{"id":"s3","text":"Построй три сцени: преди, действие, след с честна граница."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Избери реално напрежение и участник с разрешение.\n2. Запиши неговото решение и това, което камерата може да докаже.\n3. Построй три сцени: преди, действие, след с честна граница.\n4. Покажи rough cut на човек, който не знае историята.\n\nПреди окончателното предаване потвърди: Човек извън проекта може да назове промяната и доказателството без да му я обясняваш. Ако разместиш проверката след предаването, остава този риск: Монтираш чуждо testimonial видео като собствена история."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Storytelling е наблюдаема промяна: начална ситуация, залог, избор, действие, резултат и граница. Не измисляй клиентска история; при липса на разрешен случай използвай ясно обозначена демонстрация. Запази човешки момент, но не скривай необходимата информация заради драматичен обрат.","Върни се към разрешен реален случай или маркирана демонстрация с проверим изход.","Човек извън проекта може да назове промяната и доказателството без да му я обясняваш."],"nextStep":"Пренапиши своя идея като 3 сцени с начално условие, решение, видим резултат и граница на твърдението."},"points":1,"required":true}]},{"module_id":"s02-m14","lesson_id":"pv14-05","title":"Извлечи заглавие от готов списък и тествай реакция","subtitle":"Работещи шаблони, собствен стил и одит с доказателства","objective":"Всеки вариант отговаря на съдържанието; тестът е описан честно с размер и ограничения.","hook":"Избираш най-сензационното заглавие от списък, но видеото отговаря на по-тесен въпрос.","estimated_minutes":34,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Всеки вариант отговаря на съдържанието; тестът е описан честно с размер и ограничения."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Избираш най-сензационното заглавие от списък, но видеото отговаря на по-тесен въпрос."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Заглавие се взема от действителната задача на зрителя, не от готова фраза. Напиши 3 варианта с различна конкретика, провери дали кадърът и началото изпълняват обещанието и тествай реакция без да наричаш трима приятели статистически доказателство. Ако платформата дава A/B инструмент, разгледай и задържането/контекста, не само кликовете."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Запази изходната версия и описвай промяна с конкретен кадър или timecode. Шаблонът е структура за собствено доказателство, не чужд текст за копиране. Провери права за активите, четимост и звук на целевия екран, както и версията, която действително е качена. При тест с малко хора записвай ограниченията на наблюдението; не наричай предположение измерен ефект.\n\nЗа тази задача: Използвай реакцията като качествен сигнал, отстрани подвеждането и при наличност направи измерим тест."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Запиши реалния въпрос и границата на отговора.\n2. Напиши точен, любопитен и практичен вариант без подвеждане.\n3. Покажи вариантите на 3–5 души от целевата публика без обяснение.\n4. Запиши какво очакват и сравни с действителния клип.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Видео за филтър на конкретен модел получава „Как сменихме филтъра на X и проверихме монтажа“, не „Тази грешка унищожава всяка кола“.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Наричаш заглавието победител след три гласа, въпреки че то обещава друг продукт."},"after":{"label":"Как го поправяш","text":"Използвай реакцията като качествен сигнал, отстрани подвеждането и при наличност направи измерим тест."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Наричаш заглавието победител след три гласа, въпреки че то обещава друг продукт.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Запиши реалния въпрос и границата на отговора. След него: Покажи вариантите на 3–5 души от целевата публика без обяснение.\n\nКорекция: Използвай реакцията като качествен сигнал, отстрани подвеждането и при наличност направи измерим тест.\n\nНови данни, които ще приемеш за успешна поправка: Всеки вариант отговаря на съдържанието; тестът е описан честно с размер и ограничения. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Извлечи 3 заглавия за свой клип, запиши очакванията на минимум 3 души и какво би променил в началото.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Всеки вариант отговаря на съдържанието; тестът е описан честно с размер и ограничения.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Видео за филтър на конкретен модел получава „Как сменихме филтъра на X и проверихме монтажа“, не „Тази грешка унищожава всяка кола“.\n\nДоставка: Извлечи 3 заглавия за свой клип, запиши очакванията на минимум 3 души и какво би променил в началото.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Всеки вариант отговаря на съдържанието; тестът е описан честно с размер и ограничения."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Проверен първоизточник","content":{"body":"YouTube Help — A/B тест на заглавия и миниатюри: https://support.google.com/youtube/answer/16391400\nПровери текущата версия на функцията преди да повториш стъпките."},"points":0,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Какво е честен малък тест?","options":[{"id":"a","label":"Качествена проверка на очакванията, без претенция за статистика."},{"id":"b","label":"Избор по най-много удивителни."},{"id":"c","label":"„Доказана вирусност“ от трима души."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Качествена проверка на очакванията, без претенция за статистика.\n\nПървият слаб ход — „Доказана вирусност“ от трима души. — пропуска тази проверка: Всеки вариант отговаря на съдържанието; тестът е описан честно с размер и ограничения. Вторият — Избор по най-много удивителни. — оставя този риск: Наричаш заглавието победител след три гласа, въпреки че то обещава друг продукт. В работна ситуация поправката е: Използвай реакцията като качествен сигнал, отстрани подвеждането и при наличност направи измерим тест. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Харесват заглавие, което обещава невярно. Какво правиш?","options":[{"id":"a","label":"Пускаш го за кликове."},{"id":"b","label":"Сменяш само миниатюрата."},{"id":"c","label":"Отхвърляш обещанието и уточняваш версията."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Отхвърляш обещанието и уточняваш версията.\n\nПървият слаб ход — Пускаш го за кликове. — пропуска тази проверка: Всеки вариант отговаря на съдържанието; тестът е описан честно с размер и ограничения. Вторият — Сменяш само миниатюрата. — оставя този риск: Наричаш заглавието победител след три гласа, въпреки че то обещава друг продукт. В работна ситуация поправката е: Използвай реакцията като качествен сигнал, отстрани подвеждането и при наличност направи измерим тест. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Как гледаш платформен A/B резултат?","options":[{"id":"a","label":"Само първия час."},{"id":"b","label":"Само суров CTR."},{"id":"c","label":"Съобразяваш го с гледане и състав на публиката."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Съобразяваш го с гледане и състав на публиката.\n\nПървият слаб ход — Само суров CTR. — пропуска тази проверка: Всеки вариант отговаря на съдържанието; тестът е описан честно с размер и ограничения. Вторият — Само първия час. — оставя този риск: Наричаш заглавието победител след три гласа, въпреки че то обещава друг продукт. В работна ситуация поправката е: Използвай реакцията като качествен сигнал, отстрани подвеждането и при наличност направи измерим тест. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Наричаш заглавието победител след три гласа, въпреки че то обещава друг продукт. Как продължаваш?","options":[{"id":"a","label":"Използвай реакцията като качествен сигнал, отстрани подвеждането и при наличност направи измерим тест."},{"id":"b","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"c","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Използвай реакцията като качествен сигнал, отстрани подвеждането и при наличност направи измерим тест.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Всеки вариант отговаря на съдържанието; тестът е описан честно с размер и ограничения. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Наричаш заглавието победител след три гласа, въпреки че то обещава друг продукт. В работна ситуация поправката е: Използвай реакцията като качествен сигнал, отстрани подвеждането и при наличност направи измерим тест. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s4","text":"Запиши какво очакват и сравни с действителния клип."},{"id":"s1","text":"Запиши реалния въпрос и границата на отговора."},{"id":"s2","text":"Напиши точен, любопитен и практичен вариант без подвеждане."},{"id":"s3","text":"Покажи вариантите на 3–5 души от целевата публика без обяснение."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Запиши реалния въпрос и границата на отговора.\n2. Напиши точен, любопитен и практичен вариант без подвеждане.\n3. Покажи вариантите на 3–5 души от целевата публика без обяснение.\n4. Запиши какво очакват и сравни с действителния клип.\n\nПреди окончателното предаване потвърди: Всеки вариант отговаря на съдържанието; тестът е описан честно с размер и ограничения. Ако разместиш проверката след предаването, остава този риск: Наричаш заглавието победител след три гласа, въпреки че то обещава друг продукт."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Заглавие се взема от действителната задача на зрителя, не от готова фраза. Напиши 3 варианта с различна конкретика, провери дали кадърът и началото изпълняват обещанието и тествай реакция без да наричаш трима приятели статистически доказателство. Ако платформата дава A/B инструмент, разгледай и задържането/контекста, не само кликовете.","Използвай реакцията като качествен сигнал, отстрани подвеждането и при наличност направи измерим тест.","Всеки вариант отговаря на съдържанието; тестът е описан честно с размер и ограничения."],"nextStep":"Извлечи 3 заглавия за свой клип, запиши очакванията на минимум 3 души и какво би променил в началото."},"points":1,"required":true}]},{"module_id":"s02-m14","lesson_id":"pv14-06","title":"Направи списък със задължителни B-roll кадъри за своята ниша","subtitle":"Работещи шаблони, собствен стил и одит с доказателства","objective":"Всеки критичен глагол от сценария има четим кадър, а ненужните кадри са премахнати.","hook":"Монтажът има добър говор, но когато разказвачът казва „завърти винта“, няма кадър на винта.","estimated_minutes":36,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Всеки критичен глагол от сценария има четим кадър, а ненужните кадри са премахнати."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Монтажът има добър говор, но когато разказвачът казва „завърти винта“, няма кадър на винта."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"B-roll списъкът се прави по места, където изображението трябва да докаже, уточни или свърже действие. За всяка ниша намери обект, движение, мащаб, резултат и контекст. Не снимай само красиви детайли; осигури кадри на критичните стъпки и чист звук, когато действието го изисква."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Запази изходната версия и описвай промяна с конкретен кадър или timecode. Шаблонът е структура за собствено доказателство, не чужд текст за копиране. Провери права за активите, четимост и звук на целевия екран, както и версията, която действително е качена. При тест с малко хора записвай ограниченията на наблюдението; не наричай предположение измерен ефект.\n\nЗа тази задача: Върни се към сценария и заснеми липсващото действие в четим мащаб."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Маркирай в сценария всеки момент, който не може да остане на говореща глава.\n2. За всеки момент запиши широк, среден или близък кадър и какво доказва.\n3. Подреди кадрите по локация, светлина и зависимост.\n4. Провери пробния монтаж за визуални дупки и безопасност.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"За пекарна списъкът съдържа тесто преди печене, ръка с инструмент, момент на разрязване и действителна опаковка; всеки има конкретно място в историята.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Имаш десет атмосферни кадъра и нито един на ключовата операция."},"after":{"label":"Как го поправяш","text":"Върни се към сценария и заснеми липсващото действие в четим мащаб."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Имаш десет атмосферни кадъра и нито един на ключовата операция.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Маркирай в сценария всеки момент, който не може да остане на говореща глава. След него: Подреди кадрите по локация, светлина и зависимост.\n\nКорекция: Върни се към сценария и заснеми липсващото действие в четим мащаб.\n\nНови данни, които ще приемеш за успешна поправка: Всеки критичен глагол от сценария има четим кадър, а ненужните кадри са премахнати. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Направи B-roll карта за своя ниша: 10 кадъра с цел, мащаб, времеви момент и необходим достъп.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Всеки критичен глагол от сценария има четим кадър, а ненужните кадри са премахнати.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: За пекарна списъкът съдържа тесто преди печене, ръка с инструмент, момент на разрязване и действителна опаковка; всеки има конкретно място в историята.\n\nДоставка: Направи B-roll карта за своя ниша: 10 кадъра с цел, мащаб, времеви момент и необходим достъп.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Всеки критичен глагол от сценария има четим кадър, а ненужните кадри са премахнати."},"points":1,"required":false},{"position":11,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Кой кадър е задължителен?","options":[{"id":"a","label":"Още един общ кадър."},{"id":"b","label":"Този, който доказва критичното действие."},{"id":"c","label":"Произволен drone изглед."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Този, който доказва критичното действие.\n\nПървият слаб ход — Произволен drone изглед. — пропуска тази проверка: Всеки критичен глагол от сценария има четим кадър, а ненужните кадри са премахнати. Вторият — Още един общ кадър. — оставя този риск: Имаш десет атмосферни кадъра и нито един на ключовата операция. В работна ситуация поправката е: Върни се към сценария и заснеми липсващото действие в четим мащаб. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Липсва кадър на операцията. Какво правиш?","options":[{"id":"a","label":"Доснимаш с разрешение или редактираш твърдението."},{"id":"b","label":"Оставяш само музика."},{"id":"c","label":"Покриваш с несвързан stock."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Доснимаш с разрешение или редактираш твърдението.\n\nПървият слаб ход — Покриваш с несвързан stock. — пропуска тази проверка: Всеки критичен глагол от сценария има четим кадър, а ненужните кадри са премахнати. Вторият — Оставяш само музика. — оставя този риск: Имаш десет атмосферни кадъра и нито един на ключовата операция. В работна ситуация поправката е: Върни се към сценария и заснеми липсващото действие в четим мащаб. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Как оценяваш shot list?","options":[{"id":"a","label":"Само по броя кадри."},{"id":"b","label":"По цената на обектива."},{"id":"c","label":"Сверяваш го със сценария и пробния монтаж."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Сверяваш го със сценария и пробния монтаж.\n\nПървият слаб ход — Само по броя кадри. — пропуска тази проверка: Всеки критичен глагол от сценария има четим кадър, а ненужните кадри са премахнати. Вторият — По цената на обектива. — оставя този риск: Имаш десет атмосферни кадъра и нито един на ключовата операция. В работна ситуация поправката е: Върни се към сценария и заснеми липсващото действие в четим мащаб. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Имаш десет атмосферни кадъра и нито един на ключовата операция. Как продължаваш?","options":[{"id":"a","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"b","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"c","label":"Върни се към сценария и заснеми липсващото действие в четим мащаб."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Върни се към сценария и заснеми липсващото действие в четим мащаб.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Всеки критичен глагол от сценария има четим кадър, а ненужните кадри са премахнати. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Имаш десет атмосферни кадъра и нито един на ключовата операция. В работна ситуация поправката е: Върни се към сценария и заснеми липсващото действие в четим мащаб. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s4","text":"Провери пробния монтаж за визуални дупки и безопасност."},{"id":"s3","text":"Подреди кадрите по локация, светлина и зависимост."},{"id":"s2","text":"За всеки момент запиши широк, среден или близък кадър и какво доказва."},{"id":"s1","text":"Маркирай в сценария всеки момент, който не може да остане на говореща глава."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Маркирай в сценария всеки момент, който не може да остане на говореща глава.\n2. За всеки момент запиши широк, среден или близък кадър и какво доказва.\n3. Подреди кадрите по локация, светлина и зависимост.\n4. Провери пробния монтаж за визуални дупки и безопасност.\n\nПреди окончателното предаване потвърди: Всеки критичен глагол от сценария има четим кадър, а ненужните кадри са премахнати. Ако разместиш проверката след предаването, остава този риск: Имаш десет атмосферни кадъра и нито един на ключовата операция."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["B-roll списъкът се прави по места, където изображението трябва да докаже, уточни или свърже действие. За всяка ниша намери обект, движение, мащаб, резултат и контекст. Не снимай само красиви детайли; осигури кадри на критичните стъпки и чист звук, когато действието го изисква.","Върни се към сценария и заснеми липсващото действие в четим мащаб.","Всеки критичен глагол от сценария има четим кадър, а ненужните кадри са премахнати."],"nextStep":"Направи B-roll карта за своя ниша: 10 кадъра с цел, мащаб, времеви момент и необходим достъп."},"points":1,"required":true}]},{"module_id":"s02-m14","lesson_id":"pv14-07","title":"Дефинирай 3 елемента на визуалния си стил (цвят, темпо, кадриране)","subtitle":"Работещи шаблони, собствен стил и одит с доказателства","objective":"Нов монтажист може да повтори решенията, без да изкривява продукта или да губи четимост.","hook":"Всеки твой клип има различен филтър, скорост и кадриране, въпреки че разказва за един и същ бранд.","estimated_minutes":38,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Нов монтажист може да повтори решенията, без да изкривява продукта или да губи четимост."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Всеки твой клип има различен филтър, скорост и кадриране, въпреки че разказва за един и същ бранд."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Стилът е система от решения, които помагат за разпознаване и четимост. Избери три контролируеми променливи: цветови отношения и кожа/продукт, ритъм спрямо информацията, дистанция и композиция. Опиши кога правилото има изключение, защото тъмен склад и дневен прозорец няма да изглеждат еднакво с един LUT."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Запази изходната версия и описвай промяна с конкретен кадър или timecode. Шаблонът е структура за собствено доказателство, не чужд текст за копиране. Провери права за активите, четимост и звук на целевия екран, както и версията, която действително е качена. При тест с малко хора записвай ограниченията на наблюдението; не наричай предположение измерен ефект.\n\nЗа тази задача: Опиши целта и коригирай отделните сцени по референция, вместо да налагаш един филтър."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Избери два стари клипа и открий общия работещ елемент.\n2. Задай палитра/контраст, диапазон на темпо и кадриране с примерен стопкадър.\n3. Приложи правилата към два различни източника.\n4. Провери четимостта и истинността на продукта на телефон.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Ръчен производител пази топли неутрални фонове, близък план на действието и пауза за резултата. Дневният и вечерният кадър се коригират отделно, без да се променя реалният цвят на изделието.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Прилагаш един агресивен preset и продуктът изглежда с друг цвят."},"after":{"label":"Как го поправяш","text":"Опиши целта и коригирай отделните сцени по референция, вместо да налагаш един филтър."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Прилагаш един агресивен preset и продуктът изглежда с друг цвят.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Избери два стари клипа и открий общия работещ елемент. След него: Приложи правилата към два различни източника.\n\nКорекция: Опиши целта и коригирай отделните сцени по референция, вместо да налагаш един филтър.\n\nНови данни, които ще приемеш за успешна поправка: Нов монтажист може да повтори решенията, без да изкривява продукта или да губи четимост. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Направи страница с 3 правила, по два кадъра и изключение за всеки; тествай на два материала.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Нов монтажист може да повтори решенията, без да изкривява продукта или да губи четимост.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Ръчен производител пази топли неутрални фонове, близък план на действието и пауза за резултата. Дневният и вечерният кадър се коригират отделно, без да се променя реалният цвят на изделието.\n\nДоставка: Направи страница с 3 правила, по два кадъра и изключение за всеки; тествай на два материала.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Нов монтажист може да повтори решенията, без да изкривява продукта или да губи четимост."},"points":1,"required":false},{"position":11,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Кое е правило за стил?","options":[{"id":"a","label":"„Премиум усещане“ без пример."},{"id":"b","label":"Контролируем цвят, темпо и кадриране с пример."},{"id":"c","label":"Един LUT за всичко."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Контролируем цвят, темпо и кадриране с пример.\n\nПървият слаб ход — „Премиум усещане“ без пример. — пропуска тази проверка: Нов монтажист може да повтори решенията, без да изкривява продукта или да губи четимост. Вторият — Един LUT за всичко. — оставя този риск: Прилагаш един агресивен preset и продуктът изглежда с друг цвят. В работна ситуация поправката е: Опиши целта и коригирай отделните сцени по референция, вместо да налагаш един филтър. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Продуктът става друг цвят. Какво правиш?","options":[{"id":"a","label":"Криеш продукта."},{"id":"b","label":"Коригираш кадъра по реална референция и описваш изключение."},{"id":"c","label":"Оставяш, защото preset е красив."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Коригираш кадъра по реална референция и описваш изключение.\n\nПървият слаб ход — Оставяш, защото preset е красив. — пропуска тази проверка: Нов монтажист може да повтори решенията, без да изкривява продукта или да губи четимост. Вторият — Криеш продукта. — оставя този риск: Прилагаш един агресивен preset и продуктът изглежда с друг цвят. В работна ситуация поправката е: Опиши целта и коригирай отделните сцени по референция, вместо да налагаш един филтър. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Как тестваш системата?","options":[{"id":"a","label":"Прилагаш я върху два различни материала и екран."},{"id":"b","label":"Само с цветно колело."},{"id":"c","label":"Само върху едно студийно видео."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Прилагаш я върху два различни материала и екран.\n\nПървият слаб ход — Само върху едно студийно видео. — пропуска тази проверка: Нов монтажист може да повтори решенията, без да изкривява продукта или да губи четимост. Вторият — Само с цветно колело. — оставя този риск: Прилагаш един агресивен preset и продуктът изглежда с друг цвят. В работна ситуация поправката е: Опиши целта и коригирай отделните сцени по референция, вместо да налагаш един филтър. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Прилагаш един агресивен preset и продуктът изглежда с друг цвят. Как продължаваш?","options":[{"id":"a","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"b","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"c","label":"Опиши целта и коригирай отделните сцени по референция, вместо да налагаш един филтър."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Опиши целта и коригирай отделните сцени по референция, вместо да налагаш един филтър.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Нов монтажист може да повтори решенията, без да изкривява продукта или да губи четимост. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Прилагаш един агресивен preset и продуктът изглежда с друг цвят. В работна ситуация поправката е: Опиши целта и коригирай отделните сцени по референция, вместо да налагаш един филтър. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s2","text":"Задай палитра/контраст, диапазон на темпо и кадриране с примерен стопкадър."},{"id":"s3","text":"Приложи правилата към два различни източника."},{"id":"s4","text":"Провери четимостта и истинността на продукта на телефон."},{"id":"s1","text":"Избери два стари клипа и открий общия работещ елемент."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Избери два стари клипа и открий общия работещ елемент.\n2. Задай палитра/контраст, диапазон на темпо и кадриране с примерен стопкадър.\n3. Приложи правилата към два различни източника.\n4. Провери четимостта и истинността на продукта на телефон.\n\nПреди окончателното предаване потвърди: Нов монтажист може да повтори решенията, без да изкривява продукта или да губи четимост. Ако разместиш проверката след предаването, остава този риск: Прилагаш един агресивен preset и продуктът изглежда с друг цвят."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Стилът е система от решения, които помагат за разпознаване и четимост. Избери три контролируеми променливи: цветови отношения и кожа/продукт, ритъм спрямо информацията, дистанция и композиция. Опиши кога правилото има изключение, защото тъмен склад и дневен прозорец няма да изглеждат еднакво с един LUT.","Опиши целта и коригирай отделните сцени по референция, вместо да налагаш един филтър.","Нов монтажист може да повтори решенията, без да изкривява продукта или да губи четимост."],"nextStep":"Направи страница с 3 правила, по два кадъра и изключение за всеки; тествай на два материала."},"points":1,"required":true}]},{"module_id":"s02-m14","lesson_id":"pv14-08","title":"Определи собствена \"гласова\" идентичност в говора и текста","subtitle":"Работещи шаблони, собствен стил и одит с доказателства","objective":"Говорителят може да каже текста естествено, а зрителят разбира действието от първо слушане.","hook":"Сценарият звучи като реклама от чужда агенция, а човекът пред камерата обикновено говори просто и ясно.","estimated_minutes":36,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Говорителят може да каже текста естествено, а зрителят разбира действието от първо слушане."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Сценарият звучи като реклама от чужда агенция, а човекът пред камерата обикновено говори просто и ясно."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Гласовата идентичност е набор от проверими езикови навици: обръщение, дължина на изречение, терминология, хумор и граница на обещанието. Извлечи я от автентична реч, не от 10 прилагателни за бранда. Прочети текста на глас; ако говорителят не би го казал, пренапиши го. Пази точните професионални термини, когато те носят смисъл."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Запази изходната версия и описвай промяна с конкретен кадър или timecode. Шаблонът е структура за собствено доказателство, не чужд текст за копиране. Провери права за активите, четимост и звук на целевия екран, както и версията, която действително е качена. При тест с малко хора записвай ограниченията на наблюдението; не наричай предположение измерен ефект.\n\nЗа тази задача: Запази неговите точни думи и изрежи корпоративните украси без загуба на факт."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Запиши 60 секунди реално обяснение по тема.\n2. Отбележи повтарящи се думи, паузи и забранени обещания.\n3. Напиши версия за говор и отделна за екранен текст.\n4. Дай текста на говорителя и върни редакцията му като правило.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Майстор казва „първо виждаме откъде идва шумът“, а не „разгръщаме цялостна синергия на диагностиката“. Краткият надпис използва същия термин като в кадъра.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Текстът е граматически гладък, но говорителят го чете като чужд."},"after":{"label":"Как го поправяш","text":"Запази неговите точни думи и изрежи корпоративните украси без загуба на факт."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Текстът е граматически гладък, но говорителят го чете като чужд.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Запиши 60 секунди реално обяснение по тема. След него: Напиши версия за говор и отделна за екранен текст.\n\nКорекция: Запази неговите точни думи и изрежи корпоративните украси без загуба на факт.\n\nНови данни, които ще приемеш за успешна поправка: Говорителят може да каже текста естествено, а зрителят разбира действието от първо слушане. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Напиши мини речник с 5 използвани и 5 избягвани фрази; редактирай 20-секунден скрипт в собствен глас.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Говорителят може да каже текста естествено, а зрителят разбира действието от първо слушане.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Майстор казва „първо виждаме откъде идва шумът“, а не „разгръщаме цялостна синергия на диагностиката“. Краткият надпис използва същия термин като в кадъра.\n\nДоставка: Напиши мини речник с 5 използвани и 5 избягвани фрази; редактирай 20-секунден скрипт в собствен глас.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Говорителят може да каже текста естествено, а зрителят разбира действието от първо слушане."},"points":1,"required":false},{"position":11,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Кой е източникът на глас?","options":[{"id":"a","label":"Реална реч и редакция от говорителя."},{"id":"b","label":"Генеричен тонов prompt."},{"id":"c","label":"Чужд viral скрипт."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Реална реч и редакция от говорителя.\n\nПървият слаб ход — Генеричен тонов prompt. — пропуска тази проверка: Говорителят може да каже текста естествено, а зрителят разбира действието от първо слушане. Вторият — Чужд viral скрипт. — оставя този риск: Текстът е граматически гладък, но говорителят го чете като чужд. В работна ситуация поправката е: Запази неговите точни думи и изрежи корпоративните украси без загуба на факт. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Говорителят спъва ключова фраза. Какво правиш?","options":[{"id":"a","label":"Караш го да я повтаря 30 пъти."},{"id":"b","label":"Пренаписваш я със собствени думи и пазиш факта."},{"id":"c","label":"Заменяш с AI глас без съгласие."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Пренаписваш я със собствени думи и пазиш факта.\n\nПървият слаб ход — Караш го да я повтаря 30 пъти. — пропуска тази проверка: Говорителят може да каже текста естествено, а зрителят разбира действието от първо слушане. Вторият — Заменяш с AI глас без съгласие. — оставя този риск: Текстът е граматически гладък, но говорителят го чете като чужд. В работна ситуация поправката е: Запази неговите точни думи и изрежи корпоративните украси без загуба на факт. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Каква е финалната проба?","options":[{"id":"a","label":"Само брой думи."},{"id":"b","label":"Прочит на глас и разбиране от слушател."},{"id":"c","label":"Само правописна проверка."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Прочит на глас и разбиране от слушател.\n\nПървият слаб ход — Само правописна проверка. — пропуска тази проверка: Говорителят може да каже текста естествено, а зрителят разбира действието от първо слушане. Вторият — Само брой думи. — оставя този риск: Текстът е граматически гладък, но говорителят го чете като чужд. В работна ситуация поправката е: Запази неговите точни думи и изрежи корпоративните украси без загуба на факт. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Текстът е граматически гладък, но говорителят го чете като чужд. Как продължаваш?","options":[{"id":"a","label":"Запази неговите точни думи и изрежи корпоративните украси без загуба на факт."},{"id":"b","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"c","label":"Продължаваш без проверка и наричаш тази версия окончателна."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Запази неговите точни думи и изрежи корпоративните украси без загуба на факт.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Говорителят може да каже текста естествено, а зрителят разбира действието от първо слушане. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Текстът е граматически гладък, но говорителят го чете като чужд. В работна ситуация поправката е: Запази неговите точни думи и изрежи корпоративните украси без загуба на факт. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s2","text":"Отбележи повтарящи се думи, паузи и забранени обещания."},{"id":"s1","text":"Запиши 60 секунди реално обяснение по тема."},{"id":"s4","text":"Дай текста на говорителя и върни редакцията му като правило."},{"id":"s3","text":"Напиши версия за говор и отделна за екранен текст."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Запиши 60 секунди реално обяснение по тема.\n2. Отбележи повтарящи се думи, паузи и забранени обещания.\n3. Напиши версия за говор и отделна за екранен текст.\n4. Дай текста на говорителя и върни редакцията му като правило.\n\nПреди окончателното предаване потвърди: Говорителят може да каже текста естествено, а зрителят разбира действието от първо слушане. Ако разместиш проверката след предаването, остава този риск: Текстът е граматически гладък, но говорителят го чете като чужд."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Гласовата идентичност е набор от проверими езикови навици: обръщение, дължина на изречение, терминология, хумор и граница на обещанието. Извлечи я от автентична реч, не от 10 прилагателни за бранда. Прочети текста на глас; ако говорителят не би го казал, пренапиши го. Пази точните професионални термини, когато те носят смисъл.","Запази неговите точни думи и изрежи корпоративните украси без загуба на факт.","Говорителят може да каже текста естествено, а зрителят разбира действието от първо слушане."],"nextStep":"Напиши мини речник с 5 използвани и 5 избягвани фрази; редактирай 20-секунден скрипт в собствен глас."},"points":1,"required":true}]},{"module_id":"s02-m14","lesson_id":"pv14-09","title":"Добави повтарящ се визуален елемент без лого","subtitle":"Работещи шаблони, собствен стил и одит с доказателства","objective":"Мотивът се повтаря разпознаваемо, работи на телефон и не измества доказателството.","hook":"На всеки клип лепиш логото в ъгъла, но ако го махнеш, никой не познава поредицата.","estimated_minutes":34,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Мотивът се повтаря разпознаваемо, работи на телефон и не измества доказателството."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"На всеки клип лепиш логото в ъгъла, но ако го махнеш, никой не познава поредицата."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Повтарящ се визуален знак може да е конкретен начин на показване на задача: ръка чертае план, еднаква рамка за доказателство или постоянен завършващ кадър. Той трябва да помага на разбирането и да работи без да закрива продукт, надписи или платформи. Провери на два различни епизода и на малък екран."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Запази изходната версия и описвай промяна с конкретен кадър или timecode. Шаблонът е структура за собствено доказателство, не чужд текст за копиране. Провери права за активите, четимост и звук на целевия екран, както и версията, която действително е качена. При тест с малко хора записвай ограниченията на наблюдението; не наричай предположение измерен ефект.\n\nЗа тази задача: Остави знак, който подсилва полезния момент; намали или махни декоративното покритие."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Назови повтарящия се момент в историята, който има смисъл за бранда.\n2. Скицирай два варианта на мотив без лого.\n3. Постави ги в два различни клипа с различен фон.\n4. Провери разпознаване, четимост и дали елементът не пречи.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Пекарна завършва всеки клип с кадър на ръка, която отваря кутията и показва истинския продукт. В различните серии ъгълът е близък, но никой текст не покрива храната.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Добавяш тежка рамка, която скрива демонстрацията."},"after":{"label":"Как го поправяш","text":"Остави знак, който подсилва полезния момент; намали или махни декоративното покритие."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Добавяш тежка рамка, която скрива демонстрацията.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Назови повтарящия се момент в историята, който има смисъл за бранда. След него: Постави ги в два различни клипа с различен фон.\n\nКорекция: Остави знак, който подсилва полезния момент; намали или махни декоративното покритие.\n\nНови данни, които ще приемеш за успешна поправка: Мотивът се повтаря разпознаваемо, работи на телефон и не измества доказателството. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Направи два мотива за серия и ги приложи върху два различни откъса, без да използваш лого.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Мотивът се повтаря разпознаваемо, работи на телефон и не измества доказателството.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Пекарна завършва всеки клип с кадър на ръка, която отваря кутията и показва истинския продукт. В различните серии ъгълът е близък, но никой текст не покрива храната.\n\nДоставка: Направи два мотива за серия и ги приложи върху два различни откъса, без да използваш лого.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Мотивът се повтаря разпознаваемо, работи на телефон и не измества доказателството."},"points":1,"required":false},{"position":11,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Кой мотив помага?","options":[{"id":"a","label":"Рамка, която крие продукта."},{"id":"b","label":"Воден знак през цялото видео."},{"id":"c","label":"Повтарящ се кадър на действителния резултат."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Повтарящ се кадър на действителния резултат.\n\nПървият слаб ход — Воден знак през цялото видео. — пропуска тази проверка: Мотивът се повтаря разпознаваемо, работи на телефон и не измества доказателството. Вторият — Рамка, която крие продукта. — оставя този риск: Добавяш тежка рамка, която скрива демонстрацията. В работна ситуация поправката е: Остави знак, който подсилва полезния момент; намали или махни декоративното покритие. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"На вертикален екран знакът покрива надписа. Какво правиш?","options":[{"id":"a","label":"Преместваш или опростяваш мотива след пробен export."},{"id":"b","label":"Оставяш го за консистентност."},{"id":"c","label":"Намаляваш текста до нечетим."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Преместваш или опростяваш мотива след пробен export.\n\nПървият слаб ход — Оставяш го за консистентност. — пропуска тази проверка: Мотивът се повтаря разпознаваемо, работи на телефон и не измества доказателството. Вторият — Намаляваш текста до нечетим. — оставя този риск: Добавяш тежка рамка, която скрива демонстрацията. В работна ситуация поправката е: Остави знак, който подсилва полезния момент; намали или махни декоративното покритие. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Какъв е тестът?","options":[{"id":"a","label":"Само mockup на десктоп."},{"id":"b","label":"Два епизода, малък екран и проверка на четимост."},{"id":"c","label":"Само мнение на автора."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Два епизода, малък екран и проверка на четимост.\n\nПървият слаб ход — Само mockup на десктоп. — пропуска тази проверка: Мотивът се повтаря разпознаваемо, работи на телефон и не измества доказателството. Вторият — Само мнение на автора. — оставя този риск: Добавяш тежка рамка, която скрива демонстрацията. В работна ситуация поправката е: Остави знак, който подсилва полезния момент; намали или махни декоративното покритие. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Добавяш тежка рамка, която скрива демонстрацията. Как продължаваш?","options":[{"id":"a","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"b","label":"Остави знак, който подсилва полезния момент; намали или махни декоративното покритие."},{"id":"c","label":"Продължаваш без проверка и наричаш тази версия окончателна."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Остави знак, който подсилва полезния момент; намали или махни декоративното покритие.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Мотивът се повтаря разпознаваемо, работи на телефон и не измества доказателството. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Добавяш тежка рамка, която скрива демонстрацията. В работна ситуация поправката е: Остави знак, който подсилва полезния момент; намали или махни декоративното покритие. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s4","text":"Провери разпознаване, четимост и дали елементът не пречи."},{"id":"s1","text":"Назови повтарящия се момент в историята, който има смисъл за бранда."},{"id":"s2","text":"Скицирай два варианта на мотив без лого."},{"id":"s3","text":"Постави ги в два различни клипа с различен фон."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Назови повтарящия се момент в историята, който има смисъл за бранда.\n2. Скицирай два варианта на мотив без лого.\n3. Постави ги в два различни клипа с различен фон.\n4. Провери разпознаване, четимост и дали елементът не пречи.\n\nПреди окончателното предаване потвърди: Мотивът се повтаря разпознаваемо, работи на телефон и не измества доказателството. Ако разместиш проверката след предаването, остава този риск: Добавяш тежка рамка, която скрива демонстрацията."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Повтарящ се визуален знак може да е конкретен начин на показване на задача: ръка чертае план, еднаква рамка за доказателство или постоянен завършващ кадър. Той трябва да помага на разбирането и да работи без да закрива продукт, надписи или платформи. Провери на два различни епизода и на малък екран.","Остави знак, който подсилва полезния момент; намали или махни декоративното покритие.","Мотивът се повтаря разпознаваемо, работи на телефон и не измества доказателството."],"nextStep":"Направи два мотива за серия и ги приложи върху два различни откъса, без да използваш лого."},"points":1,"required":true}]},{"module_id":"s02-m14","lesson_id":"pv14-10","title":"Дефинирай стил в монтажа — преходи, темпо, шрифтове","subtitle":"Работещи шаблони, собствен стил и одит с доказателства","objective":"Друг човек може да следва правилата; зрителят не губи критично действие или текст.","hook":"Монтажистът добавя ефект на всяка смяна на кадър, а зрителят изпуска ключовата демонстрация.","estimated_minutes":38,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Друг човек може да следва правилата; зрителят не губи критично действие или текст."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Монтажистът добавя ефект на всяка смяна на кадър, а зрителят изпуска ключовата демонстрация."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Стил в монтажа е правило за смяна на сцена, пауза, звукова връзка, надписи и шрифтове. Темпото следва сложността на информацията; преходът обслужва смяна на място, време или мисъл. Направи ограничения, които колега може да повтори. Пробвай с изключен звук и после слушай без да гледаш, за да намериш пропуски."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Запази изходната версия и описвай промяна с конкретен кадър или timecode. Шаблонът е структура за собствено доказателство, не чужд текст за копиране. Провери права за активите, четимост и звук на целевия екран, както и версията, която действително е качена. При тест с малко хора записвай ограниченията на наблюдението; не наричай предположение измерен ефект.\n\nЗа тази задача: Задръж действието до завършване и намали декоративните преходи; провери с външен зрител."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Избери видео с един процес и маркирай важните действия.\n2. Опиши кога се реже, кога се задържа и кога има надпис.\n3. Задай шрифт, размер, контраст и максимум декоративни ефекти.\n4. Направи два монтажа на една сцена и сравни разбираемостта.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"При демонстрация на инструмент рязанията се случват при смяна на стъпка, не върху ръката в критичния момент. Надписът назовава точната част; единственият преход е към резултата.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Ритъмът е постоянен, но отрязва движението, което зрителят трябва да повтори."},"after":{"label":"Как го поправяш","text":"Задръж действието до завършване и намали декоративните преходи; провери с външен зрител."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Ритъмът е постоянен, но отрязва движението, което зрителят трябва да повтори.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Избери видео с един процес и маркирай важните действия. След него: Задай шрифт, размер, контраст и максимум декоративни ефекти.\n\nКорекция: Задръж действието до завършване и намали декоративните преходи; провери с външен зрител.\n\nНови данни, които ще приемеш за успешна поправка: Друг човек може да следва правилата; зрителят не губи критично действие или текст. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Напиши монтажно правило за 20-секунден откъс с cut, пауза, преход, надпис и шрифт. Направи две версии.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Друг човек може да следва правилата; зрителят не губи критично действие или текст.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: При демонстрация на инструмент рязанията се случват при смяна на стъпка, не върху ръката в критичния момент. Надписът назовава точната част; единственият преход е към резултата.\n\nДоставка: Напиши монтажно правило за 20-секунден откъс с cut, пауза, преход, надпис и шрифт. Направи две версии.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Друг човек може да следва правилата; зрителят не губи критично действие или текст."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Проверен първоизточник","content":{"body":"W3C WAI — надписи и достъпност на видео: https://www.w3.org/WAI/media/av/captions/\nПровери текущата версия на функцията преди да повториш стъпките."},"points":0,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Кога има смисъл от преход?","options":[{"id":"a","label":"При всяка секунда."},{"id":"b","label":"За да скрие липсващ кадър."},{"id":"c","label":"Когато обозначава смяна на място, време или мисъл."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Когато обозначава смяна на място, време или мисъл.\n\nПървият слаб ход — При всяка секунда. — пропуска тази проверка: Друг човек може да следва правилата; зрителят не губи критично действие или текст. Вторият — За да скрие липсващ кадър. — оставя този риск: Ритъмът е постоянен, но отрязва движението, което зрителят трябва да повтори. В работна ситуация поправката е: Задръж действието до завършване и намали декоративните преходи; провери с външен зрител. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Рязане скрива ключова стъпка. Какво правиш?","options":[{"id":"a","label":"Слагаш flash."},{"id":"b","label":"Ускоряваш още."},{"id":"c","label":"Удължаваш кадъра или добавяш доказващ близък план."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Удължаваш кадъра или добавяш доказващ близък план.\n\nПървият слаб ход — Ускоряваш още. — пропуска тази проверка: Друг човек може да следва правилата; зрителят не губи критично действие или текст. Вторият — Слагаш flash. — оставя този риск: Ритъмът е постоянен, но отрязва движението, което зрителят трябва да повтори. В работна ситуация поправката е: Задръж действието до завършване и намали декоративните преходи; провери с външен зрител. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Как тестваш четимост?","options":[{"id":"a","label":"Без звук и само със звук, плюс външен зрител."},{"id":"b","label":"Само на монтажния монитор."},{"id":"c","label":"Само по броя ефекти."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Без звук и само със звук, плюс външен зрител.\n\nПървият слаб ход — Само на монтажния монитор. — пропуска тази проверка: Друг човек може да следва правилата; зрителят не губи критично действие или текст. Вторият — Само по броя ефекти. — оставя този риск: Ритъмът е постоянен, но отрязва движението, което зрителят трябва да повтори. В работна ситуация поправката е: Задръж действието до завършване и намали декоративните преходи; провери с външен зрител. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Ритъмът е постоянен, но отрязва движението, което зрителят трябва да повтори. Как продължаваш?","options":[{"id":"a","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"b","label":"Задръж действието до завършване и намали декоративните преходи; провери с външен зрител."},{"id":"c","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Задръж действието до завършване и намали декоративните преходи; провери с външен зрител.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Друг човек може да следва правилата; зрителят не губи критично действие или текст. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Ритъмът е постоянен, но отрязва движението, което зрителят трябва да повтори. В работна ситуация поправката е: Задръж действието до завършване и намали декоративните преходи; провери с външен зрител. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s4","text":"Направи два монтажа на една сцена и сравни разбираемостта."},{"id":"s3","text":"Задай шрифт, размер, контраст и максимум декоративни ефекти."},{"id":"s2","text":"Опиши кога се реже, кога се задържа и кога има надпис."},{"id":"s1","text":"Избери видео с един процес и маркирай важните действия."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Избери видео с един процес и маркирай важните действия.\n2. Опиши кога се реже, кога се задържа и кога има надпис.\n3. Задай шрифт, размер, контраст и максимум декоративни ефекти.\n4. Направи два монтажа на една сцена и сравни разбираемостта.\n\nПреди окончателното предаване потвърди: Друг човек може да следва правилата; зрителят не губи критично действие или текст. Ако разместиш проверката след предаването, остава този риск: Ритъмът е постоянен, но отрязва движението, което зрителят трябва да повтори."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Стил в монтажа е правило за смяна на сцена, пауза, звукова връзка, надписи и шрифтове. Темпото следва сложността на информацията; преходът обслужва смяна на място, време или мисъл. Направи ограничения, които колега може да повтори. Пробвай с изключен звук и после слушай без да гледаш, за да намериш пропуски.","Задръж действието до завършване и намали декоративните преходи; провери с външен зрител.","Друг човек може да следва правилата; зрителят не губи критично действие или текст."],"nextStep":"Напиши монтажно правило за 20-секунден откъс с cut, пауза, преход, надпис и шрифт. Направи две версии."},"points":1,"required":true}]},{"module_id":"s02-m14","lesson_id":"pv14-11","title":"Провери дали стилът ти работи еднакво в 2 различни платформи","subtitle":"Работещи шаблони, собствен стил и одит с доказателства","objective":"Двете версии носят едно обещание и разпознаваем стил; текст, действие и CTA са видими и работят.","hook":"Вертикалният клип работи в Reels, но в друга платформа надписът е под интерфейса и CTA се реже.","estimated_minutes":38,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Двете версии носят едно обещание и разпознаваем стил; текст, действие и CTA са видими и работят."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Вертикалният клип работи в Reels, но в друга платформа надписът е под интерфейса и CTA се реже."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Един стил може да има общ език и различни технически варианти. Съхрани обещание, цветови решения и глас, но провери кадриране, безопасна зона, текст, звук, корица и път на действието за всеки канал. Не приемай, че един export е равен на две проверки; платформите и интерфейсите се променят."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Запази изходната версия и описвай промяна с конкретен кадър или timecode. Шаблонът е структура за собствено доказателство, не чужд текст за копиране. Провери права за активите, четимост и звук на целевия екран, както и версията, която действително е качена. При тест с малко хора записвай ограниченията на наблюдението; не наричай предположение измерен ефект.\n\nЗа тази задача: Премести текста и ако crop скрива действие, използвай втори кадър вместо изкуствено запълване."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Избери два целеви канала и напиши общия смисъл на видеото.\n2. Направи отделни работни копия за текст, кадър и действие.\n3. Прегледай всяко като зрител на истински телефон.\n4. Запиши какво запазваш и какво променяш, и направи повторен export.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Рецепта е снимана с пространство около ръцете. За първия канал финалът насочва към линк в профила, а за втория към конкретен линк в описанието; ключовата стъпка остава видима и в двете.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Публикуваш един файл и втората платформа покрива името на съставката."},"after":{"label":"Как го поправяш","text":"Премести текста и ако crop скрива действие, използвай втори кадър вместо изкуствено запълване."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Публикуваш един файл и втората платформа покрива името на съставката.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Избери два целеви канала и напиши общия смисъл на видеото. След него: Прегледай всяко като зрител на истински телефон.\n\nКорекция: Премести текста и ако crop скрива действие, използвай втори кадър вместо изкуствено запълване.\n\nНови данни, които ще приемеш за успешна поправка: Двете версии носят едно обещание и разпознаваем стил; текст, действие и CTA са видими и работят. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Подготви две версии на 20-секунден клип с таблица общо/различно и screenshot от целевите екрани.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Двете версии носят едно обещание и разпознаваем стил; текст, действие и CTA са видими и работят.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Рецепта е снимана с пространство около ръцете. За първия канал финалът насочва към линк в профила, а за втория към конкретен линк в описанието; ключовата стъпка остава видима и в двете.\n\nДоставка: Подготви две версии на 20-секунден клип с таблица общо/различно и screenshot от целевите екрани.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Двете версии носят едно обещание и разпознаваем стил; текст, действие и CTA са видими и работят."},"points":1,"required":false},{"position":11,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Какво трябва да остане общо?","options":[{"id":"a","label":"Обещание, глас и доказателство, адаптирани към канала."},{"id":"b","label":"Един и същ линк навсякъде."},{"id":"c","label":"Еднакви координати на всеки надпис."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Обещание, глас и доказателство, адаптирани към канала.\n\nПървият слаб ход — Еднакви координати на всеки надпис. — пропуска тази проверка: Двете версии носят едно обещание и разпознаваем стил; текст, действие и CTA са видими и работят. Вторият — Един и същ линк навсякъде. — оставя този риск: Публикуваш един файл и втората платформа покрива името на съставката. В работна ситуация поправката е: Премести текста и ако crop скрива действие, използвай втори кадър вместо изкуствено запълване. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Втората платформа скрива ключов кадър. Какво правиш?","options":[{"id":"a","label":"Публикуваш както е."},{"id":"b","label":"Смаляваш всичко до точка."},{"id":"c","label":"Нов crop или отделен кадър и проверен export."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Нов crop или отделен кадър и проверен export.\n\nПървият слаб ход — Публикуваш както е. — пропуска тази проверка: Двете версии носят едно обещание и разпознаваем стил; текст, действие и CTA са видими и работят. Вторият — Смаляваш всичко до точка. — оставя този риск: Публикуваш един файл и втората платформа покрива името на съставката. В работна ситуация поправката е: Премести текста и ако crop скрива действие, използвай втори кадър вместо изкуствено запълване. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Какво доказва готовност?","options":[{"id":"a","label":"Само размерът на файла."},{"id":"b","label":"Само preview в editor-а."},{"id":"c","label":"Преглед на всеки целеви екран и работещ път на CTA."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Преглед на всеки целеви екран и работещ път на CTA.\n\nПървият слаб ход — Само preview в editor-а. — пропуска тази проверка: Двете версии носят едно обещание и разпознаваем стил; текст, действие и CTA са видими и работят. Вторият — Само размерът на файла. — оставя този риск: Публикуваш един файл и втората платформа покрива името на съставката. В работна ситуация поправката е: Премести текста и ако crop скрива действие, използвай втори кадър вместо изкуствено запълване. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Публикуваш един файл и втората платформа покрива името на съставката. Как продължаваш?","options":[{"id":"a","label":"Премести текста и ако crop скрива действие, използвай втори кадър вместо изкуствено запълване."},{"id":"b","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"c","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Премести текста и ако crop скрива действие, използвай втори кадър вместо изкуствено запълване.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Двете версии носят едно обещание и разпознаваем стил; текст, действие и CTA са видими и работят. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Публикуваш един файл и втората платформа покрива името на съставката. В работна ситуация поправката е: Премести текста и ако crop скрива действие, използвай втори кадър вместо изкуствено запълване. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s2","text":"Направи отделни работни копия за текст, кадър и действие."},{"id":"s3","text":"Прегледай всяко като зрител на истински телефон."},{"id":"s4","text":"Запиши какво запазваш и какво променяш, и направи повторен export."},{"id":"s1","text":"Избери два целеви канала и напиши общия смисъл на видеото."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Избери два целеви канала и напиши общия смисъл на видеото.\n2. Направи отделни работни копия за текст, кадър и действие.\n3. Прегледай всяко като зрител на истински телефон.\n4. Запиши какво запазваш и какво променяш, и направи повторен export.\n\nПреди окончателното предаване потвърди: Двете версии носят едно обещание и разпознаваем стил; текст, действие и CTA са видими и работят. Ако разместиш проверката след предаването, остава този риск: Публикуваш един файл и втората платформа покрива името на съставката."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Един стил може да има общ език и различни технически варианти. Съхрани обещание, цветови решения и глас, но провери кадриране, безопасна зона, текст, звук, корица и път на действието за всеки канал. Не приемай, че един export е равен на две проверки; платформите и интерфейсите се променят.","Премести текста и ако crop скрива действие, използвай втори кадър вместо изкуствено запълване.","Двете версии носят едно обещание и разпознаваем стил; текст, действие и CTA са видими и работят."],"nextStep":"Подготви две версии на 20-секунден клип с таблица общо/различно и screenshot от целевите екрани."},"points":1,"required":true}]},{"module_id":"s02-m14","lesson_id":"pv14-12","title":"Направи кратък стил гид за собствения бранд","subtitle":"Работещи шаблони, собствен стил и одит с доказателства","objective":"Друг човек възпроизвежда разпознаваем и четим клип без допълнителни устни инструкции.","hook":"Нов колега пита „кой цвят и шрифт използваме“, а получава папка с 30 клипа без обяснение.","estimated_minutes":40,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Друг човек възпроизвежда разпознаваем и четим клип без допълнителни устни инструкции."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Нов колега пита „кой цвят и шрифт използваме“, а получава папка с 30 клипа без обяснение."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Краткият стил гид е инструкция за решения, не албум с вдъхновение. Покажи обещание и публика, тон, визуални правила, монтажен ритъм, надписи, звук, корици, CTA и примери за правилно/грешно. Задай граници и изключения, така че материал от различни условия да остане верен на продукта."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Запази изходната версия и описвай промяна с конкретен кадър или timecode. Шаблонът е структура за собствено доказателство, не чужд текст за копиране. Провери права за активите, четимост и звук на целевия екран, както и версията, която действително е качена. При тест с малко хора записвай ограниченията на наблюдението; не наричай предположение измерен ефект.\n\nЗа тази задача: Замени прилагателните с кадър, настройка, пример и проверка."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Извади проверените правила от два успешни собствени клипа.\n2. Добави примерен кадър, точни настройки и причина за всяко правило.\n3. Напиши три „не прави“ с поправка и изключение.\n4. Дай гида на друг монтажист за 15-секунден пробен откъс.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Бранд за керамика има 2-страничен гид: истински цветове на глазурата, тиха демонстрация, една типография и конкретен финален кадър. Ако лампата променя глазурата, правилото е корекция по референция, не „един LUT“.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Гидът казва само „премиум, динамично, модерно“ и никой не знае какво да направи."},"after":{"label":"Как го поправяш","text":"Замени прилагателните с кадър, настройка, пример и проверка."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Гидът казва само „премиум, динамично, модерно“ и никой не знае какво да направи.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Извади проверените правила от два успешни собствени клипа. След него: Напиши три „не прави“ с поправка и изключение.\n\nКорекция: Замени прилагателните с кадър, настройка, пример и проверка.\n\nНови данни, които ще приемеш за успешна поправка: Друг човек възпроизвежда разпознаваем и четим клип без допълнителни устни инструкции. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Напиши двустраничен стил гид с 6 решения, 3 грешки и 2 изключения; тествай чрез чужд пробен монтаж.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Друг човек възпроизвежда разпознаваем и четим клип без допълнителни устни инструкции.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Бранд за керамика има 2-страничен гид: истински цветове на глазурата, тиха демонстрация, една типография и конкретен финален кадър. Ако лампата променя глазурата, правилото е корекция по референция, не „един LUT“.\n\nДоставка: Напиши двустраничен стил гид с 6 решения, 3 грешки и 2 изключения; тествай чрез чужд пробен монтаж.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Друг човек възпроизвежда разпознаваем и четим клип без допълнителни устни инструкции."},"points":1,"required":false},{"position":11,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Кое е полезно правило?","options":[{"id":"a","label":"Само „премиум“."},{"id":"b","label":"Пример, настройка, граница и причина."},{"id":"c","label":"Само moodboard."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Пример, настройка, граница и причина.\n\nПървият слаб ход — Само moodboard. — пропуска тази проверка: Друг човек възпроизвежда разпознаваем и четим клип без допълнителни устни инструкции. Вторият — Само „премиум“. — оставя този риск: Гидът казва само „премиум, динамично, модерно“ и никой не знае какво да направи. В работна ситуация поправката е: Замени прилагателните с кадър, настройка, пример и проверка. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Колега не знае какво значи „динамично“. Какво добавяш?","options":[{"id":"a","label":"Диапазон и пример за ритъм спрямо действие."},{"id":"b","label":"По-ярък цвят."},{"id":"c","label":"Още един синоним."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Диапазон и пример за ритъм спрямо действие.\n\nПървият слаб ход — Още един синоним. — пропуска тази проверка: Друг човек възпроизвежда разпознаваем и четим клип без допълнителни устни инструкции. Вторият — По-ярък цвят. — оставя този риск: Гидът казва само „премиум, динамично, модерно“ и никой не знае какво да направи. В работна ситуация поправката е: Замени прилагателните с кадър, настройка, пример и проверка. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Как доказваш, че гидът работи?","options":[{"id":"a","label":"Само авторът го харесва."},{"id":"b","label":"Има много страници."},{"id":"c","label":"Друг монтажист прилага го към пробен откъс."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Друг монтажист прилага го към пробен откъс.\n\nПървият слаб ход — Само авторът го харесва. — пропуска тази проверка: Друг човек възпроизвежда разпознаваем и четим клип без допълнителни устни инструкции. Вторият — Има много страници. — оставя този риск: Гидът казва само „премиум, динамично, модерно“ и никой не знае какво да направи. В работна ситуация поправката е: Замени прилагателните с кадър, настройка, пример и проверка. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Гидът казва само „премиум, динамично, модерно“ и никой не знае какво да направи. Как продължаваш?","options":[{"id":"a","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"b","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"c","label":"Замени прилагателните с кадър, настройка, пример и проверка."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Замени прилагателните с кадър, настройка, пример и проверка.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Друг човек възпроизвежда разпознаваем и четим клип без допълнителни устни инструкции. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Гидът казва само „премиум, динамично, модерно“ и никой не знае какво да направи. В работна ситуация поправката е: Замени прилагателните с кадър, настройка, пример и проверка. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s2","text":"Добави примерен кадър, точни настройки и причина за всяко правило."},{"id":"s1","text":"Извади проверените правила от два успешни собствени клипа."},{"id":"s4","text":"Дай гида на друг монтажист за 15-секунден пробен откъс."},{"id":"s3","text":"Напиши три „не прави“ с поправка и изключение."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Извади проверените правила от два успешни собствени клипа.\n2. Добави примерен кадър, точни настройки и причина за всяко правило.\n3. Напиши три „не прави“ с поправка и изключение.\n4. Дай гида на друг монтажист за 15-секунден пробен откъс.\n\nПреди окончателното предаване потвърди: Друг човек възпроизвежда разпознаваем и четим клип без допълнителни устни инструкции. Ако разместиш проверката след предаването, остава този риск: Гидът казва само „премиум, динамично, модерно“ и никой не знае какво да направи."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Краткият стил гид е инструкция за решения, не албум с вдъхновение. Покажи обещание и публика, тон, визуални правила, монтажен ритъм, надписи, звук, корици, CTA и примери за правилно/грешно. Задай граници и изключения, така че материал от различни условия да остане верен на продукта.","Замени прилагателните с кадър, настройка, пример и проверка.","Друг човек възпроизвежда разпознаваем и четим клип без допълнителни устни инструкции."],"nextStep":"Напиши двустраничен стил гид с 6 решения, 3 грешки и 2 изключения; тествай чрез чужд пробен монтаж."},"points":1,"required":true}]},{"module_id":"s02-m14","lesson_id":"pv14-13","title":"Одитирай последно видео за грешки в камера/светлина/композиция","subtitle":"Работещи шаблони, собствен стил и одит с доказателства","objective":"Всеки проблем има видимо доказателство и отделна поправка за текущата и бъдещата версия.","hook":"Последното видео изглежда „плоско“, но екипът иска нова камера, без да е проверил светлина и композиция.","estimated_minutes":40,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Всеки проблем има видимо доказателство и отделна поправка за текущата и бъдещата версия."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Последното видео изглежда „плоско“, но екипът иска нова камера, без да е проверил светлина и композиция."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Одитът започва с конкретни timecode, симптом, вероятна причина и проба. За камера виж стабилност, фокус и експозиция; за светлина — посока, смесени източници и реален цвят; за композиция — къде зрителят трябва да гледа и дали действието остава видимо. Раздели дефект в изходния материал от дефект в export-а. Смени най-евтината проверима причина първо."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Запази изходната версия и описвай промяна с конкретен кадър или timecode. Шаблонът е структура за собствено доказателство, не чужд текст за копиране. Провери права за активите, четимост и звук на целевия екран, както и версията, която действително е качена. При тест с малко хора записвай ограниченията на наблюдението; не наричай предположение измерен ефект.\n\nЗа тази задача: Изолирай дефектите по timecode и тествай осветление, фокус и кадриране преди инвестиция."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Изгледай клипа на целеви екран и маркирай три timecode.\n2. За всеки запиши наблюдение, не етикет „грозно“.\n3. Сравни оригинал, timeline и export за причината.\n4. Предложи една снимачна и една монтажна поправка с цена/време.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"В сервизен клип инструментът излиза от фокус при критичната стъпка. Одитът посочва 00:12, близък план с фокусна проба за следващия снимачен ден и изрязване на неизползваемия кадър с честен текст в текущия.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Слагаш „купете по-скъпа камера“ като решение за всички три проблема."},"after":{"label":"Как го поправяш","text":"Изолирай дефектите по timecode и тествай осветление, фокус и кадриране преди инвестиция."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Слагаш „купете по-скъпа камера“ като решение за всички три проблема.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Изгледай клипа на целеви екран и маркирай три timecode. След него: Сравни оригинал, timeline и export за причината.\n\nКорекция: Изолирай дефектите по timecode и тествай осветление, фокус и кадриране преди инвестиция.\n\nНови данни, които ще приемеш за успешна поправка: Всеки проблем има видимо доказателство и отделна поправка за текущата и бъдещата версия. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Одитирай 30 секунди от свой клип: 3 timecode, доказателство, причина и поправка с приоритет.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Всеки проблем има видимо доказателство и отделна поправка за текущата и бъдещата версия.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: В сервизен клип инструментът излиза от фокус при критичната стъпка. Одитът посочва 00:12, близък план с фокусна проба за следващия снимачен ден и изрязване на неизползваемия кадър с честен текст в текущия.\n\nДоставка: Одитирай 30 секунди от свой клип: 3 timecode, доказателство, причина и поправка с приоритет.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Всеки проблем има видимо доказателство и отделна поправка за текущата и бъдещата версия."},"points":1,"required":false},{"position":11,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Кой е добър одитен запис?","options":[{"id":"a","label":"„Камерата е зле“."},{"id":"b","label":"00:12 инструментът излиза от фокус; следващ път близък план с проба."},{"id":"c","label":"„Сложи cinematic LUT“."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: 00:12 инструментът излиза от фокус; следващ път близък план с проба.\n\nПървият слаб ход — „Камерата е зле“. — пропуска тази проверка: Всеки проблем има видимо доказателство и отделна поправка за текущата и бъдещата версия. Вторият — „Сложи cinematic LUT“. — оставя този риск: Слагаш „купете по-скъпа камера“ като решение за всички три проблема. В работна ситуация поправката е: Изолирай дефектите по timecode и тествай осветление, фокус и кадриране преди инвестиция. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Оригиналът е ясен, export-ът размазан. Какво правиш?","options":[{"id":"a","label":"Повтаряш снимките без тест."},{"id":"b","label":"Проверяваш скалиране и настройки на export-а."},{"id":"c","label":"Купуваш нов обектив."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Проверяваш скалиране и настройки на export-а.\n\nПървият слаб ход — Купуваш нов обектив. — пропуска тази проверка: Всеки проблем има видимо доказателство и отделна поправка за текущата и бъдещата версия. Вторият — Повтаряш снимките без тест. — оставя този риск: Слагаш „купете по-скъпа камера“ като решение за всички три проблема. В работна ситуация поправката е: Изолирай дефектите по timecode и тествай осветление, фокус и кадриране преди инвестиция. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Как приоритизираш?","options":[{"id":"a","label":"По вреда за разбирането и цена на проверимата поправка."},{"id":"b","label":"По чужд preset."},{"id":"c","label":"По скъпост на техниката."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: По вреда за разбирането и цена на проверимата поправка.\n\nПървият слаб ход — По скъпост на техниката. — пропуска тази проверка: Всеки проблем има видимо доказателство и отделна поправка за текущата и бъдещата версия. Вторият — По чужд preset. — оставя този риск: Слагаш „купете по-скъпа камера“ като решение за всички три проблема. В работна ситуация поправката е: Изолирай дефектите по timecode и тествай осветление, фокус и кадриране преди инвестиция. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Слагаш „купете по-скъпа камера“ като решение за всички три проблема. Как продължаваш?","options":[{"id":"a","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"b","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"c","label":"Изолирай дефектите по timecode и тествай осветление, фокус и кадриране преди инвестиция."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Изолирай дефектите по timecode и тествай осветление, фокус и кадриране преди инвестиция.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Всеки проблем има видимо доказателство и отделна поправка за текущата и бъдещата версия. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Слагаш „купете по-скъпа камера“ като решение за всички три проблема. В работна ситуация поправката е: Изолирай дефектите по timecode и тествай осветление, фокус и кадриране преди инвестиция. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s4","text":"Предложи една снимачна и една монтажна поправка с цена/време."},{"id":"s1","text":"Изгледай клипа на целеви екран и маркирай три timecode."},{"id":"s2","text":"За всеки запиши наблюдение, не етикет „грозно“."},{"id":"s3","text":"Сравни оригинал, timeline и export за причината."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Изгледай клипа на целеви екран и маркирай три timecode.\n2. За всеки запиши наблюдение, не етикет „грозно“.\n3. Сравни оригинал, timeline и export за причината.\n4. Предложи една снимачна и една монтажна поправка с цена/време.\n\nПреди окончателното предаване потвърди: Всеки проблем има видимо доказателство и отделна поправка за текущата и бъдещата версия. Ако разместиш проверката след предаването, остава този риск: Слагаш „купете по-скъпа камера“ като решение за всички три проблема."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Одитът започва с конкретни timecode, симптом, вероятна причина и проба. За камера виж стабилност, фокус и експозиция; за светлина — посока, смесени източници и реален цвят; за композиция — къде зрителят трябва да гледа и дали действието остава видимо. Раздели дефект в изходния материал от дефект в export-а. Смени най-евтината проверима причина първо.","Изолирай дефектите по timecode и тествай осветление, фокус и кадриране преди инвестиция.","Всеки проблем има видимо доказателство и отделна поправка за текущата и бъдещата версия."],"nextStep":"Одитирай 30 секунди от свой клип: 3 timecode, доказателство, причина и поправка с приоритет."},"points":1,"required":true}]},{"module_id":"s02-m14","lesson_id":"pv14-14","title":"Одитирай последно видео за грешки в звук/сценарий","subtitle":"Работещи шаблони, собствен стил и одит с доказателства","objective":"Ключовите думи се разбират и надписите ги предават точно; повторенията са изрязани без загуба на смисъл.","hook":"Зрителят усилва звука, но пак не разбира репликата, а сценарият повтаря една и съща обща идея.","estimated_minutes":40,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Ключовите думи се разбират и надписите ги предават точно; повторенията са изрязани без загуба на смисъл."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Зрителят усилва звука, но пак не разбира репликата, а сценарият повтаря една и съща обща идея."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Одитът на звук търси шум, разбираемост, ниво, прекъсване и синхрон; сценарият търси ясно обещание, доказателство, преход и излишни изречения. Проверявай със слушалки и на телефон. Автоматичното почистване може да повреди гласа; не прикривай неразбираема критична информация с музика. Надписите се сверяват с реално казаното."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Запази изходната версия и описвай промяна с конкретен кадър или timecode. Шаблонът е структура за собствено доказателство, не чужд текст за копиране. Провери права за активите, четимост и звук на целевия екран, както и версията, която действително е качена. При тест с малко хора записвай ограниченията на наблюдението; не наричай предположение измерен ефект.\n\nЗа тази задача: Изолирай проблемното място, провери суровината и ако думата е невъзстановима, не измисляй репликата."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Изслушай без картина и маркирай неразбрана дума по timecode.\n2. Сравни суровия запис, обработената версия и музикалния микс.\n3. Маркирай повторения и изречения без доказателство.\n4. Направи две поправки и провери надписите ръчно.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Пекарка назовава съставка на 00:08, но миксерът я покрива. Текущият клип използва проверен надпис и по-тих микс; следващият снимачен ден включва пауза и проба на микрофона.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Усилваш целия звук и шумът става още по-силен."},"after":{"label":"Как го поправяш","text":"Изолирай проблемното място, провери суровината и ако думата е невъзстановима, не измисляй репликата."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Усилваш целия звук и шумът става още по-силен.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Изслушай без картина и маркирай неразбрана дума по timecode. След него: Маркирай повторения и изречения без доказателство.\n\nКорекция: Изолирай проблемното място, провери суровината и ако думата е невъзстановима, не измисляй репликата.\n\nНови данни, които ще приемеш за успешна поправка: Ключовите думи се разбират и надписите ги предават точно; повторенията са изрязани без загуба на смисъл. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Направи одит на 30 секунди: 3 timecode, версия на звука, проблем в сценария и реалистични корекции.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Ключовите думи се разбират и надписите ги предават точно; повторенията са изрязани без загуба на смисъл.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Пекарка назовава съставка на 00:08, но миксерът я покрива. Текущият клип използва проверен надпис и по-тих микс; следващият снимачен ден включва пауза и проба на микрофона.\n\nДоставка: Направи одит на 30 секунди: 3 timecode, версия на звука, проблем в сценария и реалистични корекции.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Ключовите думи се разбират и надписите ги предават точно; повторенията са изрязани без загуба на смисъл."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Проверен първоизточник","content":{"body":"W3C WAI — надписи и достъпност на видео: https://www.w3.org/WAI/media/av/captions/\nПровери текущата версия на функцията преди да повториш стъпките."},"points":0,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Коя е първата проверка?","options":[{"id":"a","label":"Суров звук, микс и точен timecode."},{"id":"b","label":"Глобално усилване."},{"id":"c","label":"Само нова музика."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Суров звук, микс и точен timecode.\n\nПървият слаб ход — Глобално усилване. — пропуска тази проверка: Ключовите думи се разбират и надписите ги предават точно; повторенията са изрязани без загуба на смисъл. Вторият — Само нова музика. — оставя този риск: Усилваш целия звук и шумът става още по-силен. В работна ситуация поправката е: Изолирай проблемното място, провери суровината и ако думата е невъзстановима, не измисляй репликата. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Думата не се чува в суровината. Какво правиш?","options":[{"id":"a","label":"AI дописва по контекст."},{"id":"b","label":"Не я измисляш; уточняваш или доснимаш според значимостта."},{"id":"c","label":"Оставяш грешен надпис."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Не я измисляш; уточняваш или доснимаш според значимостта.\n\nПървият слаб ход — AI дописва по контекст. — пропуска тази проверка: Ключовите думи се разбират и надписите ги предават точно; повторенията са изрязани без загуба на смисъл. Вторият — Оставяш грешен надпис. — оставя този риск: Усилваш целия звук и шумът става още по-силен. В работна ситуация поправката е: Изолирай проблемното място, провери суровината и ако думата е невъзстановима, не измисляй репликата. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Какво правиш с надписите?","options":[{"id":"a","label":"Махаш ги за стил."},{"id":"b","label":"Сверяваш ги ръчно с действителната реч."},{"id":"c","label":"Приемаш автоматичния файл без преглед."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Сверяваш ги ръчно с действителната реч.\n\nПървият слаб ход — Приемаш автоматичния файл без преглед. — пропуска тази проверка: Ключовите думи се разбират и надписите ги предават точно; повторенията са изрязани без загуба на смисъл. Вторият — Махаш ги за стил. — оставя този риск: Усилваш целия звук и шумът става още по-силен. В работна ситуация поправката е: Изолирай проблемното място, провери суровината и ако думата е невъзстановима, не измисляй репликата. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Усилваш целия звук и шумът става още по-силен. Как продължаваш?","options":[{"id":"a","label":"Изолирай проблемното място, провери суровината и ако думата е невъзстановима, не измисляй репликата."},{"id":"b","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"c","label":"Продължаваш без проверка и наричаш тази версия окончателна."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Изолирай проблемното място, провери суровината и ако думата е невъзстановима, не измисляй репликата.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Ключовите думи се разбират и надписите ги предават точно; повторенията са изрязани без загуба на смисъл. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Усилваш целия звук и шумът става още по-силен. В работна ситуация поправката е: Изолирай проблемното място, провери суровината и ако думата е невъзстановима, не измисляй репликата. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s4","text":"Направи две поправки и провери надписите ръчно."},{"id":"s3","text":"Маркирай повторения и изречения без доказателство."},{"id":"s2","text":"Сравни суровия запис, обработената версия и музикалния микс."},{"id":"s1","text":"Изслушай без картина и маркирай неразбрана дума по timecode."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Изслушай без картина и маркирай неразбрана дума по timecode.\n2. Сравни суровия запис, обработената версия и музикалния микс.\n3. Маркирай повторения и изречения без доказателство.\n4. Направи две поправки и провери надписите ръчно.\n\nПреди окончателното предаване потвърди: Ключовите думи се разбират и надписите ги предават точно; повторенията са изрязани без загуба на смисъл. Ако разместиш проверката след предаването, остава този риск: Усилваш целия звук и шумът става още по-силен."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Одитът на звук търси шум, разбираемост, ниво, прекъсване и синхрон; сценарият търси ясно обещание, доказателство, преход и излишни изречения. Проверявай със слушалки и на телефон. Автоматичното почистване може да повреди гласа; не прикривай неразбираема критична информация с музика. Надписите се сверяват с реално казаното.","Изолирай проблемното място, провери суровината и ако думата е невъзстановима, не измисляй репликата.","Ключовите думи се разбират и надписите ги предават точно; повторенията са изрязани без загуба на смисъл."],"nextStep":"Направи одит на 30 секунди: 3 timecode, версия на звука, проблем в сценария и реалистични корекции."},"points":1,"required":true}]},{"module_id":"s02-m14","lesson_id":"pv14-15","title":"Одитирай последно видео за грешки в монтаж/публикуване","subtitle":"Работещи шаблони, собствен стил и одит с доказателства","objective":"Приемането е върху публикуваното преживяване; зрителят вижда обещания резултат и работещ следващ път.","hook":"Видеото е чисто в монтажната, но публикуваният файл е с отрязан CTA и грешна корица.","estimated_minutes":38,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Приемането е върху публикуваното преживяване; зрителят вижда обещания резултат и работещ следващ път."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Видеото е чисто в монтажната, но публикуваният файл е с отрязан CTA и грешна корица."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Одитът обхваща цялата верига: монтажен ритъм, доказателства, надписи, export, метаданни, корица, текст, линк и версията, която действително е публикувана. Записвай дефект, място, въздействие и собственик. Провери публикувания файл на целеви телефон; редакторският preview не доказва доставка."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Запази изходната версия и описвай промяна с конкретен кадър или timecode. Шаблонът е структура за собствено доказателство, не чужд текст за копиране. Провери права за активите, четимост и звук на целевия екран, както и версията, която действително е качена. При тест с малко хора записвай ограниченията на наблюдението; не наричай предположение измерен ефект.\n\nЗа тази задача: Провери действителната публикация и коригирай файла или метаданните с нова версия и запис на промяната."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Сравни брифа с timeline-а и последния export.\n2. Изгледай файл без прекъсване с надписи и звук.\n3. Отвори публикуваната версия, корицата и CTA на телефон.\n4. Запиши три най-важни дефекта и точна нова проверка.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Онлайн магазин има добра демонстрация, но линкът сочи обща категория. Одитът маркира 00:24 CTA и реалния URL; преди нов export се потвърждава действащата продуктова страница.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Слагаш отметка „готово“, когато render-ът приключи, без да гледаш upload-а."},"after":{"label":"Как го поправяш","text":"Провери действителната публикация и коригирай файла или метаданните с нова версия и запис на промяната."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Слагаш отметка „готово“, когато render-ът приключи, без да гледаш upload-а.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Сравни брифа с timeline-а и последния export. След него: Отвори публикуваната версия, корицата и CTA на телефон.\n\nКорекция: Провери действителната публикация и коригирай файла или метаданните с нова версия и запис на промяната.\n\nНови данни, които ще приемеш за успешна поправка: Приемането е върху публикуваното преживяване; зрителят вижда обещания резултат и работещ следващ път. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Одитирай един собствен публикуван клип и предай таблица дефект × timecode/екран × поправка × доказателство.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Приемането е върху публикуваното преживяване; зрителят вижда обещания резултат и работещ следващ път.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Онлайн магазин има добра демонстрация, но линкът сочи обща категория. Одитът маркира 00:24 CTA и реалния URL; преди нов export се потвърждава действащата продуктова страница.\n\nДоставка: Одитирай един собствен публикуван клип и предай таблица дефект × timecode/екран × поправка × доказателство.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Приемането е върху публикуваното преживяване; зрителят вижда обещания резултат и работещ следващ път."},"points":1,"required":false},{"position":11,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Кой файл се одитира последен?","options":[{"id":"a","label":"Само proxy файл."},{"id":"b","label":"Само timeline preview."},{"id":"c","label":"Действително публикуваната версия."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Действително публикуваната версия.\n\nПървият слаб ход — Само timeline preview. — пропуска тази проверка: Приемането е върху публикуваното преживяване; зрителят вижда обещания резултат и работещ следващ път. Вторият — Само proxy файл. — оставя този риск: Слагаш отметка „готово“, когато render-ът приключи, без да гледаш upload-а. В работна ситуация поправката е: Провери действителната публикация и коригирай файла или метаданните с нова версия и запис на промяната. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Линкът е счупен след публикуване. Какво правиш?","options":[{"id":"a","label":"Поправяш дестинацията и проверяваш от зрителския екран."},{"id":"b","label":"Чакаш алгоритъмът да го оправи."},{"id":"c","label":"Сменяш музиката."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Поправяш дестинацията и проверяваш от зрителския екран.\n\nПървият слаб ход — Чакаш алгоритъмът да го оправи. — пропуска тази проверка: Приемането е върху публикуваното преживяване; зрителят вижда обещания резултат и работещ следващ път. Вторият — Сменяш музиката. — оставя този риск: Слагаш отметка „готово“, когато render-ът приключи, без да гледаш upload-а. В работна ситуация поправката е: Провери действителната публикация и коригирай файла или метаданните с нова версия и запис на промяната. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Как изглежда полезен одит?","options":[{"id":"a","label":"Само оценка 7/10."},{"id":"b","label":"Дефект, конкретно място, въздействие, собственик и повторна проверка."},{"id":"c","label":"Само списък с ефекти."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Дефект, конкретно място, въздействие, собственик и повторна проверка.\n\nПървият слаб ход — Само оценка 7/10. — пропуска тази проверка: Приемането е върху публикуваното преживяване; зрителят вижда обещания резултат и работещ следващ път. Вторият — Само списък с ефекти. — оставя този риск: Слагаш отметка „готово“, когато render-ът приключи, без да гледаш upload-а. В работна ситуация поправката е: Провери действителната публикация и коригирай файла или метаданните с нова версия и запис на промяната. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Слагаш отметка „готово“, когато render-ът приключи, без да гледаш upload-а. Как продължаваш?","options":[{"id":"a","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"b","label":"Провери действителната публикация и коригирай файла или метаданните с нова версия и запис на промяната."},{"id":"c","label":"Продължаваш без проверка и наричаш тази версия окончателна."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Провери действителната публикация и коригирай файла или метаданните с нова версия и запис на промяната.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Приемането е върху публикуваното преживяване; зрителят вижда обещания резултат и работещ следващ път. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Слагаш отметка „готово“, когато render-ът приключи, без да гледаш upload-а. В работна ситуация поправката е: Провери действителната публикация и коригирай файла или метаданните с нова версия и запис на промяната. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s2","text":"Изгледай файл без прекъсване с надписи и звук."},{"id":"s3","text":"Отвори публикуваната версия, корицата и CTA на телефон."},{"id":"s4","text":"Запиши три най-важни дефекта и точна нова проверка."},{"id":"s1","text":"Сравни брифа с timeline-а и последния export."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Сравни брифа с timeline-а и последния export.\n2. Изгледай файл без прекъсване с надписи и звук.\n3. Отвори публикуваната версия, корицата и CTA на телефон.\n4. Запиши три най-важни дефекта и точна нова проверка.\n\nПреди окончателното предаване потвърди: Приемането е върху публикуваното преживяване; зрителят вижда обещания резултат и работещ следващ път. Ако разместиш проверката след предаването, остава този риск: Слагаш отметка „готово“, когато render-ът приключи, без да гледаш upload-а."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Одитът обхваща цялата верига: монтажен ритъм, доказателства, надписи, export, метаданни, корица, текст, линк и версията, която действително е публикувана. Записвай дефект, място, въздействие и собственик. Провери публикувания файл на целеви телефон; редакторският preview не доказва доставка.","Провери действителната публикация и коригирай файла или метаданните с нова версия и запис на промяната.","Приемането е върху публикуваното преживяване; зрителят вижда обещания резултат и работещ следващ път."],"nextStep":"Одитирай един собствен публикуван клип и предай таблица дефект × timecode/екран × поправка × доказателство."},"points":1,"required":true}]},{"module_id":"s02-m14","lesson_id":"pv14-16","title":"Провери дали гониш тренд, който не пасва на бранда ти","subtitle":"Работещи шаблони, собствен стил и одит с доказателства","objective":"Решението е обосновано с полза и граници, а не с предположение за „вирусност“.","hook":"Трендът е забавен, но кара адвокатска кантора да играе роля, която подкопава доверието на клиентите.","estimated_minutes":36,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Решението е обосновано с полза и граници, а не с предположение за „вирусност“."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Трендът е забавен, но кара адвокатска кантора да играе роля, която подкопава доверието на клиентите."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Преди да използваш тренд, провери съвместимост с цел, публика, доказателство, тон, права и нужната скорост. Ако не носи собствен смисъл, пропусни го. Можеш да вземеш формат на въпрос/отговор, но не чужд звук или реплика без право. Оцени риска за репутацията спрямо реалната задача, а не само очаквания обхват."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Запази изходната версия и описвай промяна с конкретен кадър или timecode. Шаблонът е структура за собствено доказателство, не чужд текст за копиране. Провери права за активите, четимост и звук на целевия екран, както и версията, която действително е качена. При тест с малко хора записвай ограниченията на наблюдението; не наричай предположение измерен ефект.\n\nЗа тази задача: Върни се към клиентския въпрос; създай собствена сцена или пропусни тренда."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Опиши механизма на тренда без конкретния чужд актив.\n2. Постави до него целта, гласовите правила и реален пример от бизнеса.\n3. Провери право на звук и допустимост на твърденията.\n4. Избери адаптация с доказателство или откажи и предложи собствен формат.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Кантора взема структурата „въпрос, кратък отговор, следваща стъпка“ за реален процес на консултация, но не използва шеговития чужд звук и не обещава решение по конкретен случай.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Копираш модерен звук и текст само защото други акаунти имат много гледания."},"after":{"label":"Как го поправяш","text":"Върни се към клиентския въпрос; създай собствена сцена или пропусни тренда."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Копираш модерен звук и текст само защото други акаунти имат много гледания.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Опиши механизма на тренда без конкретния чужд актив. След него: Провери право на звук и допустимост на твърденията.\n\nКорекция: Върни се към клиентския въпрос; създай собствена сцена или пропусни тренда.\n\nНови данни, които ще приемеш за успешна поправка: Решението е обосновано с полза и граници, а не с предположение за „вирусност“. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Оцени един тренд с матрица цел × публика × тон × права × доказателство; напиши алтернативен собствен формат.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Решението е обосновано с полза и граници, а не с предположение за „вирусност“.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Кантора взема структурата „въпрос, кратък отговор, следваща стъпка“ за реален процес на консултация, но не използва шеговития чужд звук и не обещава решение по конкретен случай.\n\nДоставка: Оцени един тренд с матрица цел × публика × тон × права × доказателство; напиши алтернативен собствен формат.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Решението е обосновано с полза и граници, а не с предположение за „вирусност“."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Проверен първоизточник","content":{"body":"Your Europe — авторски права и лицензиране: https://europa.eu/youreurope/business/growing/protecting-intellectual-property/copyright/index_en.htm\nПровери текущата версия на функцията преди да повториш стъпките."},"points":0,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Кога пропускаш тренд?","options":[{"id":"a","label":"Когато е популярен."},{"id":"b","label":"Когато може да се заснеме бързо."},{"id":"c","label":"Когато не помага на целта или няма доказуеми права и тон."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Когато не помага на целта или няма доказуеми права и тон.\n\nПървият слаб ход — Когато е популярен. — пропуска тази проверка: Решението е обосновано с полза и граници, а не с предположение за „вирусност“. Вторият — Когато може да се заснеме бързо. — оставя този риск: Копираш модерен звук и текст само защото други акаунти имат много гледания. В работна ситуация поправката е: Върни се към клиентския въпрос; създай собствена сцена или пропусни тренда. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Нямаш право за трендовия звук. Какво правиш?","options":[{"id":"a","label":"Тихо го оставяш."},{"id":"b","label":"Сваляш аудиото от друг профил."},{"id":"c","label":"Ползваш разрешен звук или собствен формат."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Ползваш разрешен звук или собствен формат.\n\nПървият слаб ход — Сваляш аудиото от друг профил. — пропуска тази проверка: Решението е обосновано с полза и граници, а не с предположение за „вирусност“. Вторият — Тихо го оставяш. — оставя този риск: Копираш модерен звук и текст само защото други акаунти имат много гледания. В работна ситуация поправката е: Върни се към клиентския въпрос; създай собствена сцена или пропусни тренда. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Какво е резултатът от проверката?","options":[{"id":"a","label":"Адаптация с доказателство или мотивиран отказ."},{"id":"b","label":"Само прогнозирани гледания."},{"id":"c","label":"Копие на чужда сцена."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Адаптация с доказателство или мотивиран отказ.\n\nПървият слаб ход — Само прогнозирани гледания. — пропуска тази проверка: Решението е обосновано с полза и граници, а не с предположение за „вирусност“. Вторият — Копие на чужда сцена. — оставя този риск: Копираш модерен звук и текст само защото други акаунти имат много гледания. В работна ситуация поправката е: Върни се към клиентския въпрос; създай собствена сцена или пропусни тренда. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Копираш модерен звук и текст само защото други акаунти имат много гледания. Как продължаваш?","options":[{"id":"a","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"b","label":"Върни се към клиентския въпрос; създай собствена сцена или пропусни тренда."},{"id":"c","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Върни се към клиентския въпрос; създай собствена сцена или пропусни тренда.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Решението е обосновано с полза и граници, а не с предположение за „вирусност“. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Копираш модерен звук и текст само защото други акаунти имат много гледания. В работна ситуация поправката е: Върни се към клиентския въпрос; създай собствена сцена или пропусни тренда. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s2","text":"Постави до него целта, гласовите правила и реален пример от бизнеса."},{"id":"s1","text":"Опиши механизма на тренда без конкретния чужд актив."},{"id":"s4","text":"Избери адаптация с доказателство или откажи и предложи собствен формат."},{"id":"s3","text":"Провери право на звук и допустимост на твърденията."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Опиши механизма на тренда без конкретния чужд актив.\n2. Постави до него целта, гласовите правила и реален пример от бизнеса.\n3. Провери право на звук и допустимост на твърденията.\n4. Избери адаптация с доказателство или откажи и предложи собствен формат.\n\nПреди окончателното предаване потвърди: Решението е обосновано с полза и граници, а не с предположение за „вирусност“. Ако разместиш проверката след предаването, остава този риск: Копираш модерен звук и текст само защото други акаунти имат много гледания."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Преди да използваш тренд, провери съвместимост с цел, публика, доказателство, тон, права и нужната скорост. Ако не носи собствен смисъл, пропусни го. Можеш да вземеш формат на въпрос/отговор, но не чужд звук или реплика без право. Оцени риска за репутацията спрямо реалната задача, а не само очаквания обхват.","Върни се към клиентския въпрос; създай собствена сцена или пропусни тренда.","Решението е обосновано с полза и граници, а не с предположение за „вирусност“."],"nextStep":"Оцени един тренд с матрица цел × публика × тон × права × доказателство; напиши алтернативен собствен формат."},"points":1,"required":true}]},{"module_id":"s02-m14","lesson_id":"pv14-17","title":"Адаптирай 5 готови шаблона за собствен проект","subtitle":"Работещи шаблони, собствен стил и одит с доказателства","objective":"Петте варианта решават различни въпроси и имат собствено доказателство; поне два са изпълними с текущия материал.","hook":"Имаш пет темплейта, но всеки започва със същото изречение и всички показват еднакъв stock кадър.","estimated_minutes":40,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Петте варианта решават различни въпроси и имат собствено доказателство; поне два са изпълними с текущия материал."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Имаш пет темплейта, но всеки започва със същото изречение и всички показват еднакъв stock кадър."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Библиотеката е набор от механизми за различни работни задачи: диагностика, демонстрация, сравнение, възражение и доказателство. Избери един реален проект, попълни всеки механизъм със собствен факт и различен кадър и изхвърли версията, която няма материал. Не натрупвай пет видеа с еднаква цел само заради броя шаблони."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Запази изходната версия и описвай промяна с конкретен кадър или timecode. Шаблонът е структура за собствено доказателство, не чужд текст за копиране. Провери права за активите, четимост и звук на целевия екран, както и версията, която действително е качена. При тест с малко хора записвай ограниченията на наблюдението; не наричай предположение измерен ефект.\n\nЗа тази задача: Добави собствено доказателство или откажи шаблона, за който нямаш материал."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Запиши пет различни зрителски въпроса за един продукт.\n2. Свържи всеки с структура, собствен кадър и конкретно доказателство.\n3. Отбележи какви снимки или права липсват и спри този вариант.\n4. Подреди изпълнимите видеа по етап на зрителя и избери първите две.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Пекарна прави: как се поръчва, как се украсява, сравнение на размери, отговор за срокове и разрез на готов продукт. Петте скрипта не повтарят една и съща реплика.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Заместваш липсващ продукт със stock и наричаш това адаптация."},"after":{"label":"Как го поправяш","text":"Добави собствено доказателство или откажи шаблона, за който нямаш материал."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Заместваш липсващ продукт със stock и наричаш това адаптация.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Запиши пет различни зрителски въпроса за един продукт. След него: Отбележи какви снимки или права липсват и спри този вариант.\n\nКорекция: Добави собствено доказателство или откажи шаблона, за който нямаш материал.\n\nНови данни, които ще приемеш за успешна поправка: Петте варианта решават различни въпроси и имат собствено доказателство; поне два са изпълними с текущия материал. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Адаптирай пет структури за един реален разрешен проект: въпрос, кадър, твърдение, CTA и блокер за всяка.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Петте варианта решават различни въпроси и имат собствено доказателство; поне два са изпълними с текущия материал.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Пекарна прави: как се поръчва, как се украсява, сравнение на размери, отговор за срокове и разрез на готов продукт. Петте скрипта не повтарят една и съща реплика.\n\nДоставка: Адаптирай пет структури за един реален разрешен проект: въпрос, кадър, твърдение, CTA и блокер за всяка.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Петте варианта решават различни въпроси и имат собствено доказателство; поне два са изпълними с текущия материал."},"points":1,"required":false},{"position":11,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Кое отличава пет адаптации?","options":[{"id":"a","label":"Пет различни зрителски задачи и доказващи кадри."},{"id":"b","label":"Пет еднакви hook-а."},{"id":"c","label":"Пет копия с различен филтър."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Пет различни зрителски задачи и доказващи кадри.\n\nПървият слаб ход — Пет копия с различен филтър. — пропуска тази проверка: Петте варианта решават различни въпроси и имат собствено доказателство; поне два са изпълними с текущия материал. Вторият — Пет еднакви hook-а. — оставя този риск: Заместваш липсващ продукт със stock и наричаш това адаптация. В работна ситуация поправката е: Добави собствено доказателство или откажи шаблона, за който нямаш материал. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Третият шаблон няма доказващ кадър. Какво правиш?","options":[{"id":"a","label":"Слагаш чужд stock."},{"id":"b","label":"Пишеш по-силно твърдение."},{"id":"c","label":"Планираш снимка или го изключваш от изпълнимите."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Планираш снимка или го изключваш от изпълнимите.\n\nПървият слаб ход — Слагаш чужд stock. — пропуска тази проверка: Петте варианта решават различни въпроси и имат собствено доказателство; поне два са изпълними с текущия материал. Вторият — Пишеш по-силно твърдение. — оставя този риск: Заместваш липсващ продукт със stock и наричаш това адаптация. В работна ситуация поправката е: Добави собствено доказателство или откажи шаблона, за който нямаш материал. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Как избираш първите две?","options":[{"id":"a","label":"Само по дължина."},{"id":"b","label":"По случаен ред."},{"id":"c","label":"По нужда на зрителя и налични права/материал."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: По нужда на зрителя и налични права/материал.\n\nПървият слаб ход — По случаен ред. — пропуска тази проверка: Петте варианта решават различни въпроси и имат собствено доказателство; поне два са изпълними с текущия материал. Вторият — Само по дължина. — оставя този риск: Заместваш липсващ продукт със stock и наричаш това адаптация. В работна ситуация поправката е: Добави собствено доказателство или откажи шаблона, за който нямаш материал. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Заместваш липсващ продукт със stock и наричаш това адаптация. Как продължаваш?","options":[{"id":"a","label":"Добави собствено доказателство или откажи шаблона, за който нямаш материал."},{"id":"b","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"c","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Добави собствено доказателство или откажи шаблона, за който нямаш материал.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Петте варианта решават различни въпроси и имат собствено доказателство; поне два са изпълними с текущия материал. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Заместваш липсващ продукт със stock и наричаш това адаптация. В работна ситуация поправката е: Добави собствено доказателство или откажи шаблона, за който нямаш материал. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s4","text":"Подреди изпълнимите видеа по етап на зрителя и избери първите две."},{"id":"s1","text":"Запиши пет различни зрителски въпроса за един продукт."},{"id":"s2","text":"Свържи всеки с структура, собствен кадър и конкретно доказателство."},{"id":"s3","text":"Отбележи какви снимки или права липсват и спри този вариант."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Запиши пет различни зрителски въпроса за един продукт.\n2. Свържи всеки с структура, собствен кадър и конкретно доказателство.\n3. Отбележи какви снимки или права липсват и спри този вариант.\n4. Подреди изпълнимите видеа по етап на зрителя и избери първите две.\n\nПреди окончателното предаване потвърди: Петте варианта решават различни въпроси и имат собствено доказателство; поне два са изпълними с текущия материал. Ако разместиш проверката след предаването, остава този риск: Заместваш липсващ продукт със stock и наричаш това адаптация."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Библиотеката е набор от механизми за различни работни задачи: диагностика, демонстрация, сравнение, възражение и доказателство. Избери един реален проект, попълни всеки механизъм със собствен факт и различен кадър и изхвърли версията, която няма материал. Не натрупвай пет видеа с еднаква цел само заради броя шаблони.","Добави собствено доказателство или откажи шаблона, за който нямаш материал.","Петте варианта решават различни въпроси и имат собствено доказателство; поне два са изпълними с текущия материал."],"nextStep":"Адаптирай пет структури за един реален разрешен проект: въпрос, кадър, твърдение, CTA и блокер за всяка."},"points":1,"required":true}]},{"module_id":"s02-m14","lesson_id":"pv14-18","title":"Направи пълен одит на едно старо свое видео","subtitle":"Работещи шаблони, собствен стил и одит с доказателства","objective":"Колега може да възпроизведе диагнозата и да види коя поправка е направена; не се приписва ефект без нови данни.","hook":"Гледаш старо видео и казваш „сега бих го направил по-хубаво“, но не можеш да посочиш кое точно.","estimated_minutes":44,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Колега може да възпроизведе диагнозата и да види коя поправка е направена; не се приписва ефект без нови данни."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Гледаш старо видео и казваш „сега бих го направил по-хубаво“, но не можеш да посочиш кое точно."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Пълният одит свързва бриф/цел, обещание, кадри, звук, монтаж, стил, права, публикация и данни с конкретни доказателства. Първо измери какво може да се види, после предложи малък набор поправки с очакван ефект и проверка. Крива на задържане подсказва къде да гледаш, но не доказва защо хората са си тръгнали. Без достъп до статистика отдели хипотезата от наблюдавания дефект."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Запази изходната версия и описвай промяна с конкретен кадър или timecode. Шаблонът е структура за собствено доказателство, не чужд текст за копиране. Провери права за активите, четимост и звук на целевия екран, както и версията, която действително е качена. При тест с малко хора записвай ограниченията на наблюдението; не наричай предположение измерен ефект.\n\nЗа тази задача: Назови дефекти, източник и конкретна поправка, после отдели неизмеримото като хипотеза."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Избери свое старо видео и запази линк, дата, версия и налични данни.\n2. Маркирай по timecode проблеми и силни места в картина, звук, история и действие.\n3. Подреди три поправки по полза, цена и риск за правата.\n4. Направи нов 15-секунден откъс или storyboard и запиши как ще провериш промяната.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Клип за магазин има силно начало, но на 00:11 продуктът е в сянка, на 00:19 цената е стара, а финалният линк е счупен. Новата версия поправя факт и път на действие първо; светлината се решава на следващите снимки.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Оценяваш цялото видео 6/10 и предлагаш нова камера без timecode или проверка."},"after":{"label":"Как го поправяш","text":"Назови дефекти, източник и конкретна поправка, после отдели неизмеримото като хипотеза."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Оценяваш цялото видео 6/10 и предлагаш нова камера без timecode или проверка.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Избери свое старо видео и запази линк, дата, версия и налични данни. След него: Подреди три поправки по полза, цена и риск за правата.\n\nКорекция: Назови дефекти, източник и конкретна поправка, после отдели неизмеримото като хипотеза.\n\nНови данни, които ще приемеш за успешна поправка: Колега може да възпроизведе диагнозата и да види коя поправка е направена; не се приписва ефект без нови данни. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Предай одит на свой стар клип: цел, 5 timecode, данни или ограничение, 3 приоритета, пробна нова версия и план за измерване.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Колега може да възпроизведе диагнозата и да види коя поправка е направена; не се приписва ефект без нови данни.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Клип за магазин има силно начало, но на 00:11 продуктът е в сянка, на 00:19 цената е стара, а финалният линк е счупен. Новата версия поправя факт и път на действие първо; светлината се решава на следващите снимки.\n\nДоставка: Предай одит на свой стар клип: цел, 5 timecode, данни или ограничение, 3 приоритета, пробна нова версия и план за измерване.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Колега може да възпроизведе диагнозата и да види коя поправка е направена; не се приписва ефект без нови данни."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Проверен първоизточник","content":{"body":"YouTube Help — моменти на задържане: https://support.google.com/youtube/answer/9314415\nW3C WAI — надписи и достъпност на видео: https://www.w3.org/WAI/media/av/captions/\nПровери текущата версия на функцията преди да повториш стъпките."},"points":0,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Кое е доказуем одит?","options":[{"id":"a","label":"Прогноза за милион гледания."},{"id":"b","label":"Timecode, наблюдение, приоритет и проверима поправка."},{"id":"c","label":"Само „не е cinematic“."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Timecode, наблюдение, приоритет и проверима поправка.\n\nПървият слаб ход — Само „не е cinematic“. — пропуска тази проверка: Колега може да възпроизведе диагнозата и да види коя поправка е направена; не се приписва ефект без нови данни. Вторият — Прогноза за милион гледания. — оставя този риск: Оценяваш цялото видео 6/10 и предлагаш нова камера без timecode или проверка. В работна ситуация поправката е: Назови дефекти, източник и конкретна поправка, после отдели неизмеримото като хипотеза. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Нямаш достъп до статистика. Какво правиш?","options":[{"id":"a","label":"Одитираш файла и маркираш предположенията като непотвърдени."},{"id":"b","label":"Спираш всички визуални проверки."},{"id":"c","label":"Измисляш retention."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Одитираш файла и маркираш предположенията като непотвърдени.\n\nПървият слаб ход — Измисляш retention. — пропуска тази проверка: Колега може да възпроизведе диагнозата и да види коя поправка е направена; не се приписва ефект без нови данни. Вторият — Спираш всички визуални проверки. — оставя този риск: Оценяваш цялото видео 6/10 и предлагаш нова камера без timecode или проверка. В работна ситуация поправката е: Назови дефекти, източник и конкретна поправка, после отдели неизмеримото като хипотеза. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Какво следва след поправката?","options":[{"id":"a","label":"Обявяване на успех веднага."},{"id":"b","label":"Само нов thumbnail."},{"id":"c","label":"Сравнение на релевантни данни и зрителския път при сходни условия."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Сравнение на релевантни данни и зрителския път при сходни условия.\n\nПървият слаб ход — Обявяване на успех веднага. — пропуска тази проверка: Колега може да възпроизведе диагнозата и да види коя поправка е направена; не се приписва ефект без нови данни. Вторият — Само нов thumbnail. — оставя този риск: Оценяваш цялото видео 6/10 и предлагаш нова камера без timecode или проверка. В работна ситуация поправката е: Назови дефекти, източник и конкретна поправка, после отдели неизмеримото като хипотеза. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Оценяваш цялото видео 6/10 и предлагаш нова камера без timecode или проверка. Как продължаваш?","options":[{"id":"a","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"b","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"c","label":"Назови дефекти, източник и конкретна поправка, после отдели неизмеримото като хипотеза."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Назови дефекти, източник и конкретна поправка, после отдели неизмеримото като хипотеза.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Колега може да възпроизведе диагнозата и да види коя поправка е направена; не се приписва ефект без нови данни. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Оценяваш цялото видео 6/10 и предлагаш нова камера без timecode или проверка. В работна ситуация поправката е: Назови дефекти, източник и конкретна поправка, после отдели неизмеримото като хипотеза. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s4","text":"Направи нов 15-секунден откъс или storyboard и запиши как ще провериш промяната."},{"id":"s3","text":"Подреди три поправки по полза, цена и риск за правата."},{"id":"s2","text":"Маркирай по timecode проблеми и силни места в картина, звук, история и действие."},{"id":"s1","text":"Избери свое старо видео и запази линк, дата, версия и налични данни."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Избери свое старо видео и запази линк, дата, версия и налични данни.\n2. Маркирай по timecode проблеми и силни места в картина, звук, история и действие.\n3. Подреди три поправки по полза, цена и риск за правата.\n4. Направи нов 15-секунден откъс или storyboard и запиши как ще провериш промяната.\n\nПреди окончателното предаване потвърди: Колега може да възпроизведе диагнозата и да види коя поправка е направена; не се приписва ефект без нови данни. Ако разместиш проверката след предаването, остава този риск: Оценяваш цялото видео 6/10 и предлагаш нова камера без timecode или проверка."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Пълният одит свързва бриф/цел, обещание, кадри, звук, монтаж, стил, права, публикация и данни с конкретни доказателства. Първо измери какво може да се види, после предложи малък набор поправки с очакван ефект и проверка. Крива на задържане подсказва къде да гледаш, но не доказва защо хората са си тръгнали. Без достъп до статистика отдели хипотезата от наблюдавания дефект.","Назови дефекти, източник и конкретна поправка, после отдели неизмеримото като хипотеза.","Колега може да възпроизведе диагнозата и да види коя поправка е направена; не се приписва ефект без нови данни."],"nextStep":"Предай одит на свой стар клип: цел, 5 timecode, данни или ограничение, 3 приоритета, пробна нова версия и план за измерване."},"points":1,"required":true}]}]$curriculum$::jsonb;
  lesson record;
  block jsonb;
  lesson_uuid uuid;
  version_uuid uuid;
  block_uuid uuid;
  report jsonb;
  new_lessons integer;
  published_count integer;
  new_keys integer;
  release_note text := 'Перфектното видео, модули 13–14: първо практическо издание v8';
BEGIN
  IF jsonb_typeof(payload)<>'array' OR jsonb_array_length(payload)<>36 THEN
    RAISE EXCEPTION 'Expected 36 lesson records';
  END IF;
  IF (SELECT count(DISTINCT p.lesson_id) FROM jsonb_to_recordset(payload)
      AS p(lesson_id text))<>36 OR
     (SELECT array_agg(p.lesson_id ORDER BY p.lesson_id)
      FROM jsonb_to_recordset(payload) AS p(lesson_id text))
       <>ARRAY['pv13-01','pv13-02','pv13-03','pv13-04','pv13-05','pv13-06','pv13-07','pv13-08','pv13-09','pv13-10','pv13-11','pv13-12','pv13-13','pv13-14','pv13-15','pv13-16','pv13-17','pv13-18','pv14-01','pv14-02','pv14-03','pv14-04','pv14-05','pv14-06','pv14-07','pv14-08','pv14-09','pv14-10','pv14-11','pv14-12','pv14-13','pv14-14','pv14-15','pv14-16','pv14-17','pv14-18']::text[] THEN
    RAISE EXCEPTION 'Unexpected or duplicate lesson IDs';
  END IF;
  IF (SELECT ARRAY[
        count(*) FILTER (WHERE p.module_id='s02-m13')::integer,
        count(*) FILTER (WHERE p.module_id='s02-m14')::integer
      ] FROM jsonb_to_recordset(payload) AS p(module_id text))
      <>ARRAY[18,18] THEN
    RAISE EXCEPTION 'Unexpected module distribution';
  END IF;
  IF EXISTS (SELECT 1 FROM public.academy_lessons
             WHERE module_id IN ('s02-m13','s02-m14')) THEN
    RAISE EXCEPTION 'Modules 13–14 already contain lessons; review rather than overwrite';
  END IF;
  IF EXISTS (SELECT 1 FROM public.interactive_lessons
             WHERE module_id IN ('s02-m13','s02-m14')) THEN
    RAISE EXCEPTION 'Legacy lessons exist for this catalog; review before release';
  END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_to_recordset(payload)
      AS p(module_id text, lesson_id text, title text, objective text,
           hook text, estimated_minutes integer, blocks jsonb)
    WHERE p.module_id<>('s02-m'||substring(p.lesson_id from 3 for 2))
       OR btrim(coalesce(p.title,''))=''
       OR btrim(coalesce(p.objective,''))=''
       OR btrim(coalesce(p.hook,''))=''
       OR p.estimated_minutes NOT BETWEEN 25 AND 50
       OR jsonb_typeof(p.blocks)<>'array'
       OR jsonb_array_length(p.blocks) NOT BETWEEN 13 AND 20
       OR (SELECT count(*) FROM jsonb_array_elements(p.blocks) b
           WHERE b ? 'answer_key')<>5
       OR (SELECT count(*) FROM jsonb_array_elements(p.blocks) b
           WHERE b->>'block_type'='quiz')<>2
       OR (SELECT count(*) FROM jsonb_array_elements(p.blocks) b
           WHERE b->>'block_type'='scenario')<>2
       OR (SELECT count(*) FROM jsonb_array_elements(p.blocks) b
           WHERE b->>'block_type'='sequence_sort')<>1
       OR EXISTS (SELECT 1 FROM jsonb_array_elements(p.blocks) b
           WHERE b->>'block_type' IN (
             'practical_response','reflection','homework','submission','prompt_builder'
           ))
  ) THEN
    RAISE EXCEPTION 'Content, lesson structure or assessment guard failed';
  END IF;

  FOR lesson IN SELECT * FROM jsonb_to_recordset(payload) AS p(
      module_id text,lesson_id text,title text,subtitle text,objective text,
      hook text,estimated_minutes integer,blocks jsonb)
      ORDER BY module_id,lesson_id
  LOOP
    INSERT INTO public.academy_lessons(module_id,lesson_id,status)
    VALUES (lesson.module_id,lesson.lesson_id,'draft')
    RETURNING id INTO lesson_uuid;

    INSERT INTO public.academy_lesson_versions(
      academy_lesson_id,version_number,title,subtitle,duration,objective,
      hook,estimated_minutes,source_kind,change_note)
    VALUES (lesson_uuid,1,lesson.title,lesson.subtitle,
            lesson.estimated_minutes::text||' минути',lesson.objective,
            lesson.hook,lesson.estimated_minutes,'editor',release_note)
    RETURNING id INTO version_uuid;

    FOR block IN SELECT value FROM jsonb_array_elements(lesson.blocks)
    LOOP
      INSERT INTO public.academy_lesson_blocks(
        version_id,block_key,"position",block_type,title,content,required,points)
      VALUES (version_uuid,block->>'block_key',(block->>'position')::integer,
              block->>'block_type',block->>'title',block->'content',
              (block->>'required')::boolean,(block->>'points')::integer)
      RETURNING id INTO block_uuid;

      IF block ? 'answer_key' THEN
        INSERT INTO academy_private.lesson_block_keys(
          block_id,answer_key,feedback,scoring)
        VALUES (block_uuid,block->'answer_key',block->'feedback',block->'scoring');
        IF block->>'block_type' IN ('quiz','scenario') AND NOT EXISTS (
          SELECT 1 FROM jsonb_array_elements(block->'content'->'options') o
          WHERE o->>'id'=block->'answer_key'->>'correct'
        ) THEN
          RAISE EXCEPTION 'Invalid answer key: % / %',
            lesson.lesson_id,block->>'block_key';
        END IF;
        IF block->>'block_type'='sequence_sort' AND
            jsonb_array_length(block->'answer_key'->'order')<>
            jsonb_array_length(block->'content'->'items') THEN
          RAISE EXCEPTION 'Invalid sequence key in %',lesson.lesson_id;
        END IF;
      END IF;
    END LOOP;

    report:=academy_private.lesson_validation(version_uuid);
    IF jsonb_array_length(report->'errors')<>0 OR
       jsonb_array_length(report->'warnings')<>0 THEN
      RAISE EXCEPTION 'Lesson % failed validation: %',lesson.lesson_id,report;
    END IF;
    UPDATE public.academy_lesson_versions SET validation=report
      WHERE id=version_uuid;
    UPDATE public.academy_lessons SET status='published',
      published_version_id=version_uuid,draft_version_id=version_uuid,
      updated_at=clock_timestamp()
      WHERE id=lesson_uuid;
    INSERT INTO public.academy_lesson_audit(
      academy_lesson_id,version_id,actor_id,action,details)
    VALUES (lesson_uuid,version_uuid,NULL,'published',
      jsonb_build_object('source','perfect_video_v8',
                         'previous_version_id',NULL,
                         'preserved_existing_progress',true));
  END LOOP;

  SELECT count(*),count(*) FILTER (WHERE l.status='published'
      AND l.published_version_id IS NOT NULL AND
      l.draft_version_id=l.published_version_id)
    INTO new_lessons,published_count
  FROM public.academy_lessons l
  WHERE l.module_id IN ('s02-m13','s02-m14');
  IF new_lessons<>36 OR published_count<>36 THEN
    RAISE EXCEPTION 'Publication incomplete: % / %',new_lessons,published_count;
  END IF;
  SELECT count(*) INTO new_keys
  FROM academy_private.lesson_block_keys k
  JOIN public.academy_lesson_blocks b ON b.id=k.block_id
  JOIN public.academy_lesson_versions v ON v.id=b.version_id
  JOIN public.academy_lessons l ON l.id=v.academy_lesson_id
  WHERE l.module_id IN ('s02-m13','s02-m14')
    AND l.published_version_id=v.id;
  IF new_keys<>180 THEN
    RAISE EXCEPTION 'Expected 180 private answer keys; found %',new_keys;
  END IF;
END
$release$;
